typedef long long ll;
typedef unsigned long long ull;
ll gcd(ll a,ll b) { return b==0?a:gcd(b,a%b); }

const int MAXN=100000;
const int MAXM=200000;

int n,m;
int ghead[MAXN],gnxt[2*MAXM],gto[2*MAXM];

int state[MAXN];
int comp[MAXN],ncomp;
int q[2*MAXN],qhead,qtail;
int cnt[MAXN]; bool bip[MAXN];


bool been[1000];
int qq[1000],qqhead,qqtail;
ll bf() {
	assert(n*n<=1000);
	memset(been,false,sizeof(been)); ll ret=0;
	REP(i,n*n) if(!been[i]) {
		qqhead=qqtail=0; been[i]=true,qq[qqhead++]=i,++ret;
		while(qqtail<qqhead) {
			int at=qq[qqtail++]; int at1=at/n,at2=at%n;
			for(int x=ghead[at1];x!=-1;x=gnxt[x]) for(int y=ghead[at2];y!=-1;y=gnxt[y]) {
				int to1=gto[x],to2=gto[y],to=to1*n+to2;
				if(!been[to]) been[to]=true,qq[qqhead++]=to;
			}
		}
	}
	return ret;
}

ll solve() {
	memset(state,0,sizeof(state)); ncomp=0;
	REP(i,n) if(state[i]==0) {
		qhead=qtail=0;
		state[i]=1,comp[i]=ncomp++,q[qhead++]=i;
		while(qtail<qhead) {
			int at=q[qtail++];
			for(int x=ghead[at];x!=-1;x=gnxt[x]) {
				int to=gto[x];
				int nval=state[at]==3?3:3-state[at];
				if((state[to]|nval)==state[to]) continue;
				state[to]|=nval,comp[to]=comp[i],q[qhead++]=to;
			}
		}
	}
	REP(i,ncomp) cnt[i]=0,bip[i]=true; REP(i,n) ++cnt[comp[i]]; REP(i,n) if(state[i]==3) bip[comp[i]]=false;
	int nsingle=0,nbip=0; REP(i,ncomp) if(cnt[i]==1) ++nsingle; else if(bip[i]) ++nbip;
	//REP(i,ncomp) printf("%d: %d %c\n",i,cnt[i],cnt[i]!=1&&bip[i]?'V':'x');

	ll ret=0;
	REP(i,ncomp) {
		if(cnt[i]==1) ret+=n;
		else if(bip[i]) ret+=(ll)cnt[i]*nsingle+2*nbip+(ncomp-nsingle-nbip);
		else ret+=(ll)cnt[i]*nsingle+nbip+(ncomp-nsingle-nbip);
	}
	return ret;
}


void run() {
	scanf("%d%d",&n,&m); REP(i,n) ghead[i]=-1;
	REP(i,m) {
		int a,b; scanf("%d%d",&a,&b); --a,--b;
		gnxt[2*i+0]=ghead[a]; ghead[a]=2*i+0; gto[2*i+0]=b;
		gnxt[2*i+1]=ghead[b]; ghead[b]=2*i+1; gto[2*i+1]=a;
	}
	ll ret=solve(); printf("%lld\n",ret);
	//ll chk=bf(); printf("chk=%lld\n",chk);
}

void stress() {
	while(true) {
		n=5,m=rand()%10;
		REP(i,n) ghead[i]=-1;
		REP(i,m) { int a,b; do { a=rand()%n,b=rand()%n; } while(a==b); gnxt[2*i+0]=ghead[a]; ghead[a]=2*i+0; gto[2*i+0]=b; gnxt[2*i+1]=ghead[b]; ghead[b]=2*i+1; gto[2*i+1]=a; }
		ll ret=solve(); printf("%lld\n",ret);
		ll chk=bf(); printf("chk=%lld\n",chk);
		if(ret!=chk) break;
	}
	printf("%d %d\n",n,m);
	REP(i,n) for(int x=ghead[i];x!=-1;x=gnxt[x]) if(gto[x]>i) printf("%d %d\n",i+1,gto[x]+1);
}



int main() {
	//stress();
	run();
	return 0;
}

