int rec(int node){
	int ans = 2;
	rep(i,0,adj[node].size()){
		int to=adj[node][i];
		if(vis[to]){
			if(dis[to] == dis[node])
				ans=1;
			continue;
		}
		vis[to]=1;
		dis[to]=1-dis[node];
		if(rec(to) == 1)
			ans=1;

	}
	return ans;
}

int main(){
