	ll s=0, d=0, l=0;
	rep(i,0,N){
		if(vis[i])
			continue;
		int type = rec(i);
		if(adj[i].size() == 0)
			type = 0;
		if(type == 0)
			++l;
		else if(type == 1)
			++s;
		else
			++d;
	}
