bool is_bipartite(int s, vector<vector<int> > const& g, vector<int>& used, int c = +1) {
    bool res = true;
    if (used[s] == -c) res = false;
    if (!used[s]) {
        used[s] = c;
        for (int x : g[s]) if (!is_bipartite(x,g,used,-c)) res = false;
    }
    return res;
}

