        g[u].push_back(v);
        g[v].push_back(u);
    }

    vector<int> used(n);
    int a = 0, b = 0, cnt = 0, nn = n;
    rep (i,n) {
        if (used[i]) continue;
        if (g[i].empty()) {
            cnt += 2*nn-1, nn--;
            continue;
        }
        if (is_bipartite(i,g,used)) a++; else b++;
    }
    cnt += a*a*2 + 2*a*b + b*b;
    cout << cnt << "\n";
}

