class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec color;

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
        color = vec(N, -1);
    }

    void add_edge(int from, int to, int cost = 0){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost = 0){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    void dfs(int v, int col, int &sz, bool &bin){
        sz++;
        color[v] = col;
        for(auto e: G[v]){
            if(color[e.to] == col) bin = false;
            else if(color[e.to] == -1) dfs(e.to, 1 - col, sz, bin);
        }
    }

};

