typedef long long LL;
struct edge
{
	int u,v;
	edge(){};
	edge(int _u,int _v):u(_u),v(_v){};
};
vector<edge> G[MAXN+5],edges;
int setfa[MAXN+5],setsp[MAXN+5],d[MAXN+5];
int dist[MAXN+5],n,m;
bool vis[MAXN+5];
void Init()
{
	for(int i=0;i<=MAXN;i++)
		setfa[i]=i;
}
int Findfa(int x)
{
	if(x==setfa[x])
		return x;
	return setfa[x]=Findfa(setfa[x]);
}
void Union(int x,int y)
{
	int fx=Findfa(x),fy=Findfa(y);
	if(fx==fy)
		return;
	setfa[fx]=fy;
}
void DFS(int u)
{
	for(int i=0;i<(int)G[u].size();i++)
	{
		int v=G[u][i].v;
		if(dist[v]!=0)
		{
			int cirlen=dist[u]-dist[v]+1;
			if(cirlen%2==1)
				setsp[Findfa(u)]=true;
			continue;
		}
		dist[v]=dist[u]+1;
		DFS(v);
	}
}
int main()
{
//	freopen("squared.in","r",stdin);
//	freopen("squared.out","w",stdout);
	Init();
	scanf("%d %d",&n,&m);
	int u,v;
	for(int i=1;i<=m;i++)
	{
		scanf("%d %d",&u,&v);
		G[u].push_back(edge(u,v));
		G[v].push_back(edge(v,u));
		edges.push_back(edge(u,v));
		d[u]++,d[v]++;
		Union(u,v);
	}
	for(int i=1;i<=n;i++)
		if(dist[i]==0)
		{
			dist[i]=1;
			DFS(i);
		}
	LL ans=0,num=0,num2=0;
	for(int i=1;i<=n;i++)
		if(vis[Findfa(i)]==false)
		{
			vis[Findfa(i)]=true;
			if(d[i]==0)
				continue;
			num++;
			if(setsp[Findfa(i)]==true)
				num2++;
			else
				num2+=2;
		}
	memset(vis,0,sizeof(vis));
	LL cnt=0;
	for(int i=1;i<=n;i++)
		if(vis[Findfa(i)]==false)
		{
			vis[Findfa(i)]=true;
			if(d[i]==0)
			{
				ans+=1LL*n;
				cnt+=1LL;
				continue;
			}
			if(setsp[Findfa(i)]==true)
				ans+=1LL*num;
			else
				ans+=1LL*num2;
		}
	ans+=cnt*(n-cnt);
	printf("%lld\n",ans);
	return 0;
}

