vector<vector<ll>> adj;
vector<ll> color;

bool dfs(ll n) {
  if (color[n]==-1) color[n] = 0;
  bool result = true;
  for (auto x: adj[n]) {
    if (color[x]==-1) {
      color[x] = !color[n];
      result &= dfs(x);
    }
    else result &= color[x]!=color[n];
  }
  return result;
}

int main() {
