    uf.unite(u,v);
    adj[u].push_back(v);
    adj[v].push_back(u);
  }

  color.resize(N,-1);
  ll one = 0, bi = 0, nbi = 0;
  rep(i,N) {
    if (uf.root(i)!=i) continue;
    if (uf.size(i)==1) one++;
    else {
      if (dfs(i)) bi++;
      else nbi++;
    }
  }
  // cout << one << " " << bi << " " << nbi << endl;

  ll result = (N*N-(N-one)*(N-one)) + bi*bi*2 + nbi*bi*2 + nbi*nbi;
  cout << result << endl;
  return 0;
}

