//Union Find Tree
class UnionFindTreeSize {
public:
	vector<int> parent;
    vector<int> maxidx;
    vector<int> minidx;

    UnionFindTreeSize(int N = 1) : parent(N,-1),maxidx(N),minidx(N){
        iota(maxidx.begin(),maxidx.end(),0);
        iota(minidx.begin(),minidx.end(),0);
	}

	int root(int n) {
        return (parent[n]<0?n:parent[n] = root(parent[n]));
	}

    bool same(int n, int m) {
		return root(n) == root(m);
	}

    int mini(int n) {
        return minidx[root(n)];
    }

    int maxi(int n) {
        return maxidx[root(n)];
    }

	void unite(int n, int m) {
		n = root(n);
		m = root(m);
		if (n == m) return;
		if(parent[n]>parent[m]) swap(n, m);
        parent[n] += parent[m];
        parent[m] = n;
        maxidx[n] = max(maxidx[n],maxidx[m]);
        minidx[n] = min(minidx[n],minidx[m]);
	}

    int size(int n){
        return (-parent[root(n)]);
    }

    void print() {
        for(int i = 0; i < parent.size(); ++i) cout << root(i) << " ";
        cout << endl;
    }
};

int main() {
	ll N,M; cin >> N >> M;
	vector<vector<int>> edge(N);
	UnionFindTreeSize uf(N);
	for(int i = 0; i < M; ++i) {
		int u,v; cin >> u >> v;
		u--,v--;
		edge[u].push_back(v);
		edge[v].push_back(u);
		uf.unite(u,v);
	}
	vector<int> c(N,-1);
	for(int i = 0; i < N; ++i) {
		if(c[i]!=-1) continue;
		queue<int> q;
		c[i]=0;
		q.push(i);
		while(q.size()){
			int from = q.front();
			q.pop();
			for(int to:edge[from]){
				if(c[to]!=-1) continue;
				c[to]=c[from]^1;
				q.push(to);
			}
		}
	}
	map<int,int> sz,bi;
	for(int i=0;i < N; ++i) {
		sz[uf.root(i)]=uf.size(i);
		for(int j:edge[i]){
			if(c[i]==c[j]) bi[uf.root(i)]=1;
		}
	}
	ll x=0,y=0,z=0;
	for(auto& e:sz){
		int root = e.first;
		if(sz[root]==1){
			x++;
			continue;	
		}
		(bi[root]?z:y)++;
	}
	ll ans = 0;
	ans += N*N - (N-x)*(N-x);
	ans += (y+z)*(y+z)-y*y;
	ans += y*y*2;
	cout << ans << endl;
    return 0;
}

