#include <bits/stdc++.h>
using namespace std;

// one-based numbering
struct UnionFind {
    vector<int> data;
    // i: (data[i] < 0) -> group size, (data[i] > 0) -> parent;
    UnionFind(int n) {
        data.resize(n+1, -1);
    }
    int find(int x) {
        if(data[x] < 0) return x;
        else return data[x] = find(data[x]);
    }
    int size(int x) {
        return -data[find(x)];
    }
    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return false;
        if (data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }
    bool same(int x, int y) {
        x = find(x); y = find(y);
        return x == y;
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n, m; cin >> n >> m;
    vector<vector<int>> e(n+1);
    vector<bool> vis(n+1, 1);
    vector<int> col(n+1, -1);
    UnionFind uf(n);
    for (int i = 0; i < m; i++) {
        int u, v; cin >> u >> v;
        e[u].emplace_back(v);
        e[v].emplace_back(u);
        uf.unite(u, v);
    }
    long long sx[3] = {0, 0, 0};
    long long num[3] = {0, 0, 0};
    auto calc = [&](int s) {
        bool ok = true;
        col[s] = 0;
        long long sum[2] = {0, 0};
        auto f = [&](auto f, int curr, int prev) -> void {
            sum[col[curr]]++;
            for (auto &to: e[curr]) {
                if (prev == to) continue;
                if (col[to] == -1) {
                    col[to] = 1 - col[curr];
                    f(f, to, curr);
                } else {
                    if (col[to] != 1 - col[curr]) ok = false;
                }
            }
        };
        f(f, s, -1);
        if (sum[0] + sum[1] == 1) return;
        if (ok) {
            sx[0] += sum[0], sx[1] += sum[1];
            num[0] += sum[0] > 0LL, num[1] += sum[1] > 0LL;
        } else {
            sx[2] += sum[0] + sum[1];
            num[2] += (sum[0] + sum[1]) > 0LL;
        }
    };
    long long ans = (long long) n * n;
    for (int i = 1; i <= n; i++) {
        int x = uf.find(i);
        if (vis[x]) {
            calc(i);
            vis[x] = 0;
        }
    }
    ans -= max(0LL, (sx[0] + sx[1]) * (sx[0] + sx[1]) - num[0] * 2);
    ans -= max(0LL, sx[2] * sx[2] - 1);
    ans -= max(0LL, sx[2] * (sx[0] + sx[1]) * 2 - 2);
    cout << ans << "\n";
    return 0;
}

