void sch(int now, int prev, int nowcol, const vvi &g, UnionFind &uf) {
  col[now] = nowcol;
  for(auto &nxt: g[now]) {
    if(nxt == prev) continue;
    if(col[nxt] == nowcol) {
      notnibu[uf.root(now)] = true;
      return;
    } else if(col[nxt] == -1) {
      sch(nxt, now, !nowcol, g, uf);
      if (notnibu[uf.root(now)]) return;
    }
  }
}

