class UF
{
private:
	vector<int> root;
	vector<bool> isacyclic;

public:
	UF(int n)
	{
		root = vector<int>(n + 1, -1);
		isacyclic = vector<bool>(n + 1, false);
	}

	int getroot(int x)
	{
		if(root[x] == -1) return x;
		else return root[x] = getroot(root[x]);
	}

	bool getacyclic(int x)
	{
		return isacyclic[getroot(x)];
	}

	void add(int x, int y)
	{
		x = getroot(x);
		y = getroot(y);
		if(x == y){
			isacyclic[x] = true;
			return;
		}
		if(x > y) swap(x, y);
		root[y] = x;
		isacyclic[x] = (isacyclic[x] || isacyclic[y]);
	}

};

int main()
{
	int n, m;
	cin >> n >> m;
	UF uf(n);
	vector<bool> isnoedge(n + 1, true);
	for(int i = 0; i < m; i++){
		int u, v;
		cin >> u >> v;
		uf.add(u, v);
		isnoedge[u] = false;
		isnoedge[v] = false;
	}
	long long int acyclic = 0, notacyclic = 0;
	long long int noedgenode = 0;
	for(int i = 1; i <= n; i++){
		if(isnoedge[i]){
			noedgenode++;
		} else if(uf.getroot(i) == i){
			if(uf.getacyclic(i)) acyclic++;
			else notacyclic++;
		}
	}
	long long int ans = acyclic * (acyclic + notacyclic);
	ans += notacyclic * (acyclic + 2 * notacyclic);
	ans += 2 * n * noedgenode - noedgenode * (noedgenode + 1) + noedgenode;
	cout << ans << endl;
	return 0;
}

