struct UnionFind{
    vector<int> par,dep;
    UnionFind(int n){
        dep.assign(n,1);
        par.assign(n,0);
        for(int i=0;i<n;i++)par[i]=i;
    }
    int find(int x){
        if(par[x]==x){
            return x;
        }else{
            return par[x]=find(par[x]);
        }
    }
    bool unite(int u,int v){
        u=find(u);
        v=find(v);
        if(u==v)return false;
        if(dep[u]>dep[v]){
            par[v]=u;
        }else if(dep[u]<=dep[v]){
            par[u]=v;
            if(dep[u]==dep[v]){
                dep[v]++;
            }
        }
        return true;
    }
};
