    for(int i=1;i<=n;i++)if(app[i])
    {
        cnt++;
        if(p[i]==i)
        {
            if(!h[i])c1++;
             c2++;
        }
    }
    long long ans=n*n+(c2*c2+c1*c1-cnt*cnt);
    cout<<ans;
}

