        vector<int> vis(n);
        LL cnt=0, conn=0, ev=0;
        for(int i=0; i<n; ++i){
            if(uf.par[i]<-1){
                if(!oddloop(i))ev++;
                conn+=uf.size(i);
                cnt++;
            }
        }
        cout << n*n-conn*conn+cnt*cnt+ev*ev <<"\n";

    }
};

