#define MAXN 300010

vector<int> edge[MAXN];
int fa[MAXN],color[MAXN],no,c2,el,visit[MAXN],n,m;

int findfa(int x)
{
	return fa[x]==x?x:fa[x]=findfa(fa[x]);
}

bool dfs(int u)
{
	for(auto v:edge[u])
	{
		if(color[v]==color[u])return false;
		if(color[v])continue;
		color[v]=3-color[u];
		if(!dfs(v))return false;
	}
	return true;
}

void cover(int u)
{
	visit[u]=true;
	for(auto v:edge[u])
	{
		if(visit[v])continue;
		cover(v);
	}
}

int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;++i)fa[i]=i;
	for(int i=1;i<=m;++i)
