		edge[u].push_back(v);
		edge[v].push_back(u);
		fa[findfa(u)]=findfa(v);
	}
	for(int i=1;i<=n;++i)
	{
		if(visit[i])continue;
		if(edge[i].empty())++no;
		else
		{
			color[i]=1;
			if(dfs(i))++c2;else ++el;
			cover(i);
		}
	}
