        if (l < r) {
            swap(l,r);
            swap(u,v);
        }
        if (l == r && x[u] == x[v]) {
			s[l] = 1;
		}
        if (l == r) continue;
        s[r] |= s[l];
        fa[l] = r;
        x[l] = x[u] ^ x[v] ^ 1;
    }
    rep(i, 1, n) if (!k[i]) {
		cnt++;
	}
    ans = (ll)cnt * (n - cnt) * 2 + (ll)cnt * cnt;
