ll N,M;
vector<ll> G[MAX];
bool visited[MAX];
int d[MAX];

bool dfs(int pos,int depth){
  if(visited[pos])return (d[pos]==depth%2);

  visited[pos]=true;
  d[pos]=depth%2;

  bool res=true;
  for(int i=0;i<(int)G[pos].size();i++){
    int to=G[pos][i];
    if( !dfs(to,depth+1) )res=false;
  }
  return res;
}

int main(){
  scanf("%lld %lld",&N,&M);
  for(int i=0;i<M;i++){
    ll x,y;
