    x--,y--;
    G[x].push_back(y);
    G[y].push_back(x);
  }

  ll ans=0;
  ll cnt=0;
  ll cntA=0;
  ll cntB=0;
  for(int i=0;i<N;i++){
    if(visited[i])continue;
    if(G[i].size()==0){
      cnt++;
      continue;
    }
    bool isb=dfs(i,0);
    if(isb){
      cntA++;
    }    else {
      cntB++;
    }
  }
  // cout<<cntA<<' '<<cntB<<endl;

  ans+= (cnt*N*2 - cnt*cnt);

  ans+= cntB*(cntB-1);
