void Brute(int n, int m) {
  vector<vector<int>> adj(n, vector<int>(n));
  for (int i = 0; i < m; ++i) {
    int u, v;
    scanf("%d%d", &u, &v);
    u--, v--;
    adj[u][v] = adj[v][u] = 1;
  }
  vector<int> uf(n * n);
  for (int i = 0; i < n * n; ++i) uf[i] = i;

  function<int(int)> Find = [&](int u) {
    if (uf[u] == u) return u;
    return uf[u] = Find(uf[u]);
  };

  auto Merge = [&](int u, int v) { uf[Find(u)] = Find(v); };

  for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
      for (int k = 0; k < n; ++k) {
        for (int l = 0; l < n; ++l) {
          if (adj[i][k] && adj[j][l]) {
            Merge(i * n + j, k * n + l);
          }
        }
      }
    }
  }
  int ans = 0;
  for (int i = 0; i < n * n; ++i) ans += Find(i) == i;
  printf("%d\n", ans);
}

