void U(int x, int y) {
	x = T(x);
	y = T(y);
	if (x != y) {
		if (t[x] < t[y]) {
			t[x] += t[y];
			t[y] = x;
		}
		else {
			t[y] += t[x];
			t[x] = y;
		}
	}
