void work ()
{
	// main work

	prec = kc = 0;
	INIT ( pre, -1 );
	lpi ( i, 1, n ) if ( pre[i] == -1 ) tarjan ( i, -1 );

	INIT ( fa, -1 );
	int ru, rv;
	for ( int i = 0; i < ke; i += 2 ){
		if ( inb[edge[i].u] ^ inb[edge[i].v] ){
			ru = getfa ( inb[edge[i].u] ), rv = getfa ( inb[edge[i].v] );
			if ( ru ^ rv ) fa[ru] = rv;
		}
	}

	lpi ( i, 1, kc ) ++cc[getfa(i)], ac[getfa(i)] += size[i];

	int c1 = 0, c2 = 0;
	int nk = 0;
	lpi ( i, 1, kc ){
