			else ans += nl * 2 + 1;
			++nl;
			nk += size[i];
		}
	}

	cout << ans << endl;
}



void tarjan ( int now, int fa )
{
	pre[now] = low[now] = ++prec;
	stck[top++] = now;

	int v;
	for ( int i = la[now]; ~i; i = edge[i].last ){
		v = edge[i].v;
		if ( pre[v] == -1 ){
			tarjan ( v, now );
			low[now] = qmin ( low[now], low[v] );
		}else if ( v ^ fa ) low[now] = qmin ( low[now], pre[v] );
	}

	if ( pre[now] == low[now] ){
		++kc;
		v = -1;
		while ( v ^ now ){
			v = stck[--top];
			inb[v] = kc;
			++size[kc];
		}
	}
}

