template<typename a>
struct S006 {
  std::vector<std::vector<long>> xs; // children
  std::vector<long> ys; // parent
  std::vector<long> zs; // component-root
  const a& g;
  S006(const a& g_) : g(g_) {
    long n = g.v();
    xs.resize(n);
    ys.resize(n);
    std::vector<bool> ws(n, false);
    for(long i = 0; i < n; ++i) {
      if( ws[i] ) continue;
      ws[i] = true;
      ys[i] = -1;
      zs.push_back(i);
      dfs(i, ws);
    }
  }
  void dfs(long i, std::vector<bool>& ws) {
    for(typename a::e x : g[i]) {
      if( ws[x.d] ) continue;
      ws[x.d] = true;
      ys[x.d] = i;
      xs[i].push_back(x.d);
      dfs(x.d, ws);
    }
  }
  // children
  std::vector<long>& c(long i) {
    return xs[i];
  }
  // parent
  long p(long i) {
    return ys[i];
  }
  // coomponent-roots
  std::vector<long>& r() {
    return zs;
  }
};

