/* union-find */
struct S007 {
  std::vector<long> xs;
  std::vector<long> ys;
  S007(long n) : xs(n), ys(n, 1) {
    for(long i = 0; i < n; ++i) {
      xs[i] = i;
    }
  }
  long find(long x) {
    if( xs[x] == x ) return x;
    return xs[x] = find(xs[x]);
  }
  void unite(long x, long y) {
    x = find(x);
    y = find(y);
    if( x == y ) return;
    if( not ( ys[x] <= ys[y] ) ) std::swap(x, y);
    xs[x] = y;
    ys[y] += ys[x];
  }
  bool same(long x, long y) {
    return find(x) == find(y);
  }
  long getN(long x) {
    return ys[x];
  }
};

/* bipartite? */
template<typename a>
struct S008 {
  std::vector<bool> xs;
  const a& g;
  S008(const a& g_) : g(g_) {
    S007 u(g.v() * 2);
    for(typename a::e x : g.es()) {
      long s = x.s;
      long d = x.d;
      u.unite(s * 2    , d * 2 + 1);
      u.unite(s * 2 + 1, d * 2    );
    }
    long n = g.v();
    xs.resize(n);
    for(long i = 0; i < n; ++i) {
      xs[i] = not u.same(i * 2, i * 2 + 1);
    }
  }
  bool f(long i) {
    return xs[i];
  }
};

struct Solver {
  long n, m;
  std::vector<std::array<long, 2>> xs;
  Solver() {
    S002 r;
    r >= n >= m >m>= xs;
  }
  void solve() {
    std::vector<S004> ys;
    for(std::array<long, 2> x : xs) {
      ys.push_back(S004(x[0]-1, x[1]-1));
      ys.push_back(S004(x[1]-1, x[0]-1));
    }
    S005<S004> g(ys, n);
    S006<S005<S004>> d(g);
    S008<S005<S004>> b(g);
    long w[3] = {};
    for(long x : d.r()) {
      if( d.c(x).size() != 0 and b.f(x) ) {
        w[0] += 1;
      }
      else if( d.c(x).size() != 0 and not b.f(x) ) {
        w[1] += 1;
      }
      else {
        w[2] += 1;
      }
    }
    // dumpll(ws[0], ws[1]);
    long res =
      2 * w[0] * w[0] +
      w[1] * w[0] + w[0] * w[1] + w[1] * w[1] +
      w[2] * (g.v() - w[2]) + (g.v() - w[2]) * w[2] + w[2] * w[2];
    printf("%ld\n", res);
  }
};

int main() {
  for(;;) std::unique_ptr<Solver>(new Solver())->solve();
  return 0;
}

