ll const MAX = 200005;
vll G[MAX];
ll color[MAX] = {};
ll isolate = 0;
ll conn = 0;
ll sigl = 0;

void dfs(ll start) {
	if (SIZE(G[start]) == 0) {
		isolate++;
		return;
	}
	bool flag = 0;
	color[start] = 0;
	stack<ll> st;
	st.push(start);
	while (!st.empty()) {
		ll cur = st.top();
		st.pop();
		for (auto nex : G[cur]) {
			if (color[nex] == -1) {
				color[nex] = !color[cur];
				st.push(nex);
			}
			else if (color[nex] == color[cur]) {
				flag = 1;
			}
		}
	}
	conn++;
	if (flag) {
		sigl++;
	}
}

int main() {
	ll n, m; cin >> n >> m;
	REP(i, 0, MAX - 1) {
		color[i] = -1;
	}
	REP(i, 1, m) {
		ll a, b;
		cin >> a >> b;
		G[a].push_back(b);
		G[b].push_back(a);
	}
	REP(i, 1, n) {
		if (color[i] == -1) {
			dfs(i);
		}
	}
	ll ans = 0;
	ans = n * n - (n-isolate) * (n-isolate);
	ans += sigl * conn * 2 - sigl * sigl;
	ll semi = conn - sigl;
	ans += semi * semi * 2;
	cout << ans << endl;
}

