typedef long long ll;
ll n,m,a[111111],p[111111],r[111111],ans,sum,cnt,x[111111],y[111111];
ll fin(ll a)
{
	if(p[a]==a)
		return a;
	return p[a]=fin(p[a]);
}
void uni(ll a, ll b)
{
	a=fin(a),b=fin(b);
	if(a==b)
		return;
	if(r[a]>r[b])
		r[a]+=r[b],p[b]=a;
	else
		r[b]+=r[a],p[a]=b;
}
int main()
{
	cin>>n>>m;
	for(ll i=1;i<=n;i++)
		p[i]=i,r[i]=1;
	for(ll i=1;i<=m;i++)
		scanf("%lld%lld",&x[i],&y[i]),uni(x[i],y[i]);
	for(ll i=1;i<=n;i++)
		if(fin(i)==i&&r[i]>1)
			sum+=r[i],cnt++;
	for(ll i=1;i<=n;i++)
		if(fin(i)==i&&r[i]>1)
			ans+=sum*r[i];
	cout<<n*n-ans+cnt*cnt+1;
}

