typedef long long int lli;

const lli maxn = lli(1e5)+5;

lli vis[maxn], type[2];
vector<lli> graph[maxn];

lli dfs(lli node, lli parity)
{
	vis[node] = parity;
	lli ret = 1;
	for(auto it: graph[node])
	{
		if(vis[it] == -1)
		{
			ret = min(ret, dfs(it, !parity));
		}
		else ret = min(ret, lli(vis[it] == (!parity)));
	}
	return ret;
}

inline lli c2(lli x)
{
	return (x*(x-1))/2;
}

int main(void)
{
	lli n, m, u, v;
	scanf("%lld%lld", &n, &m);
	for(lli i = 0;i < n;i++) vis[i] = -1;
	vector<lli> process;
	while(m--)
	{
		scanf("%lld%lld", &u, &v);
		u--, v--;
		graph[u].push_back(v);
		graph[v].push_back(u);
	}

	lli res = 0, iso = 0;
	for(lli i = 0;i < n;i++)
	{
		if(vis[i] == -1)
		{
			lli x = dfs(i, 0);
			if(graph[i].empty()) iso++;
			else type[x]++;
		}
	}

	//cout << iso << " " << type[0] << " " << type[1] << "\n";
	//combo = (u non-bipartite, u non-bipartite)
	res += type[0];
	//combo = (isolated, something)
	res += iso*n*2ll-iso;
	//combo = (bipartite, bipartite)
	res += 2ll*c2(type[1]);
	//combo = (bipartite, non-bipartite)
	res += type[0]*type[1]*2ll;
	//combo = (non-bipartite, non-bipartite)
	res += c2(type[0])*2ll;
	//combo = (bipartite, self)
	res += 2ll*type[1];

	printf("%lld\n", res);
}

