#define N 100010
int par[N],rnk[N];
struct UF {

	void init(int n){
		for(int i = 0; i < n; i++){
			par[i] = i;
			rnk[i] = 0;
		}
	}

	int find(int x){
		if(par[x] == x){
			return x;
		}else{
			return par[x] = find(par[x]);
		}
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rnk[x] < rnk[y]){
			par[x] = y;
		}else{
			par[y] = par[x];
			if(rnk[x] == rnk[y]) rnk[y]++;
		}
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}
};

vector<int> g[N];
int d[N], odd[N];
int t[N];

bool dfs(int u, int x){
	t[u] = x;
	for(int &v: g[u]){
		if(!t[v] && dfs(v, x+1)) return true;
		else if((t[v]+x+1)%2) return true;
	}
	return false;
}

int main(){
