	}
	rep(i, n){
		int x = uf.find(i);
		d[x]++;
		if(x!=i) continue;
		if(dfs(i, 1)) odd[i] = 1;
	}
	ll vvv = 0, vv = 0, v = 0;
	rep(i, n){
		if(d[i]==1) v++;
		else if(d[i]){
			if(odd[i]) vvv++;
			else vv++;
		}
	}
	cerr<<vvv<<" "<<vv<<" "<<v<<endl;
	ll res = + vv*vv + (vvv+vv)*(vvv+vv) + 2*v*n-v*v;
	cout<<res<<endl;
	return 0;
}

