int Count(int v)
{
    if (tk[v]) return 0;
    tk[v] = true;
    int cnt = 1;
    for (int i = 0; i < neigh[v].size(); i++)
        cnt += Count(neigh[v][i]);
    return cnt;
}

bool Bic(int v, int c)
{
    if (col[v] != 0) return col[v] == c;
    col[v] = c;
    for (int i = 0; i < neigh[v].size(); i++)
        if (!Bic(neigh[v][i], -c)) return false;
    return true;
}

