    }
    lft = n;
    for (int i = 1; i <= n; i++) if (!tk[i]) {
        int siz = Count(i);
        if (siz == 1) { lft--; res += 2ll * lft + 1ll; }
        else if (Bic(i, 1)) bic++;
             else nonbic++;
    }
    while (nonbic > 0) {
        nonbic--;
        res += 2 * (bic + nonbic) + 1;
    }
    res += ll(bic) * bic * 2ll;
    cout << res << endl;
    return 0;
}

