class solver{
public:
	int dfs(int v, int c) {
		if (used[v] != -1) {
			return used[v] == c;
		}
		used[v] = c;
		if (sz(to[v]) == 0) return 2;
		int res = 1;
		for (int u : to[v]) {
			if (!dfs(u, c ^ 1)) res = 0;
		}
		return res;
	}

	long long int main(int n,int m,vector<pair<int,int> > lis) {
		to = vvi(n);
		rep(i, m) {
			int a, b;
			a = lis[i].first;
			b = lis[i].second;
			to[a].pb(b);
			to[b].pb(a);
		}
		used = vi(n, -1);
		vl g(3);
		rep(i, n) {
			if (used[i] != -1) continue;
			g[dfs(i, 0)]++;
		}
		// cout<<g<<endl;
		ll ans = 0;
		ans += g[0] * g[0];
		ans += g[0] * g[1] * 2;
		ans += g[1] * g[1] * 2;
		// cout<<g<<endl;
		ans += g[2] * n * 2;
		ans -= g[2] * g[2];
		return ans;
	}
};

