int getparent(int t)
{
	return t == parent[t] ? t : parent[t] = getparent(parent[t]);
}

void merge(int a, int b)
{
	a = getparent(a), b = getparent(b);
	parent[a] = b;
}

bool dfs(int t, int col = 1)
{
	color[t] = col;
	for (int nxt : graph[t])
	{
		if (color[nxt] == 0)
		{
			if (dfs(nxt, col ^ 3)) return true;
		}
		else
		{
			if (color[nxt] == col) return true;
		}
	}
	return false;
}

int main()
{
	int n, m;
	scanf("%d%d", &n, &m);

	for (int i = 1; i <= n; i++)
	{
		parent[i] = i;
	}

	for (int i = 0; i < m; i++)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		merge(a, b);
		graph[a].push_back(b);
		graph[b].push_back(a);
	}

	for (int i = 1; i <= n; i++)
	{
		if (color[i] == 0 && dfs(i))
			odd[getparent(i)] = true;
	}

	vector<int> og, eg;

	for (int i = 1; i <= n; i++)
	{
		gsize[getparent(i)]++;
	}

	long long ans = n * 1ll * n;
	int sum = 0;

	for (int i = 1; i <= n; i++)
	{
		if (getparent(i) == i)
		{
			if (gsize[i] == 1) continue;

			if (odd[i]) og.push_back(gsize[i]);
			else eg.push_back(gsize[i]);
			sum += gsize[i];
		}
	}

	for (int t : og) ans -= t * 1ll * sum - (int)(og.size() + eg.size());
	for (int t : eg) ans -= t * 1ll * sum - (int)(og.size() + eg.size());
	ans += (long long)eg.size() * (eg.size() + 1) / 2;


	printf("%lld\n", ans);
}

