#include<iostream>
#include<cstdio>
#define N 500000
using namespace std;
int p[N];
int getf(int x)
{
    int i=x,j=x;
    while(p[i]!=i)i=p[i];
    while(x!=i)
    {
        j=p[x];
        p[x]=i;
        x=j;
    }
    return i;
}
void merge(int a,int b)
{
    a=getf(a);
    b=getf(b);
    p[a]=b;
}
int to[N],nex[N],ver[N],tot;
void addedge(int u,int v)
{
    to[++tot]=v;
    nex[tot]=ver[u];
    ver[u]=tot;
}

int u,v,cnt;
int app[N]={0};
long long n,m;
int lian[N];
int main()
{
    cin>>n>>m;
    for(int i=1;i<=n;i++)p[i]=i;
    for(int i=1;i<=m;i++)
    {
        scanf("%d%d",&u,&v);
        app[u]=app[v]=1;
        addedge(u,v);
        addedge(v,u);
        u=getf(u);
        v=getf(v);
        merge(u,v);
    }

    long long kk=0;
    for(int i=1;i<=n;i++)
    {
        if(p[i]==i)kk++;
        p[i]=i;
    }
    for(int i=1;i<=n;i++)
    {
        for(int j=ver[i];nex[j];j=nex[j])
        {
            merge(to[j],to[nex[j]]);
        }
    }
    //c1:
    long long c1=0,c2=0;
    for(int i=1;i<=n;i++)
    {
        if(app[i])c1++;
        if(app[i]&&p[i]==i)c2++;
    }
    kk-=n-c1;

    long long ans=n*n+(kk*kk+1-c1*c1);
    cout<<ans<<endl;
}

