int main()
{
    Int N, M; cin >> N >> M;
    vector<vector<int>> G(N);
    for (int i = 0; i < M; i++) {
        int u, v; cin >> u >> v; u--, v--;
        G[u].push_back(v);
        G[v].push_back(u);
    }
    vector<int> visited(N);
    vector<pair<int, bool>> A;
    for (int i = 0; i < N; i++) {
        int cnt[2] = {};
        bool f = false;
        stack<pair<int, int>> S;
        S.emplace(i, 1);
        while (!S.empty()) {
            int t, c; tie(t, c) = S.top(); S.pop();
            if (visited[t]) continue;
            visited[t] = c, cnt[c-1]++;
            for (int n : G[t]) {
                if (visited[n] == 0) S.emplace(n, 3-c);
                if (visited[n] == c) f = true;
            }
        }
        if (abs(cnt[0]-cnt[1])>1) f = true;
        if (cnt[0]+cnt[1] >= 2) A.emplace_back(cnt[0]+cnt[1], f);
    }
    Int ans = N * N;
    for (int i = 0; i < A.size(); i++) {
        ans += (A[i].second ? 1 : 2) - A[i].first * A[i].first;
        for (int j = i + 1; j < A.size(); j++) {
            ans += (A[i].second && A[j].second ? 1 : 2) - A[i].first * A[j].first * 2;
        }
    }
    cout << ans << endl;
    return 0;
}

