#include <cstdio>
#include <vector>

using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

typedef long long ll;

const int N_MAX = 100000;
const int M_MAX = 200000;

int N, M;
int u[M_MAX];
int v[M_MAX];

vector<int> G[N_MAX];
int color[N_MAX];

bool dfs(int v, int c) {
  bool ret = false;
  color[v] = c;
  REP(i, G[v].size()) {
    int u = G[v][i];
    if (color[u] == 0) {
      ret |= dfs(u, 3 - c);
    } else if (color[u] == c) {
      ret = true;
    }
  }
  return ret;
}

void build_graph() {
  REP(i, M) {
    G[u[i] - 1].push_back(v[i] - 1);
    G[v[i] - 1].push_back(u[i] - 1);
  }
}

void solve() {
  build_graph();

  ll si = 0;
  ll bi = 0;
  ll ot = 0;
  REP(v, N) {
    if (color[v] == 0) {
      bool ret = dfs(v, 1);
      if (G[v].size() == 0) {
        si++;
      } else {
        ret ? ot++ : bi++;
      }
    }
  }

  ll ans = 0;
  ans += si * N * 2 - si * si;
  ans += (bi + ot) * (bi + ot);
  ans += bi * bi;
  printf("%lld\n", ans);
}

void input() {
  scanf("%d%d", &N, &M);
  REP(i, M) scanf("%d%d", u + i, v + i);
}

int main() {
  input();
  solve();
  return 0;
}

