int main(){
	ios_base::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<vector<int>> conn(n);
	for(int i = 0; i < m; ++i){
		int a, b;
		cin >> a >> b;
		--a; --b;
		conn[a].push_back(b);
		conn[b].push_back(a);
	}
	vector<int> done(n);
	int single = 0, bcount = 0, nbcount = 0;
	for(int r = 0; r < n; ++r){
		if(done[r]){ continue; }
		vector<int> passed;
		queue<int> q;
		q.push(r);
		done[r] = 1;
		while(!q.empty()){
			const int u = q.front();
			q.pop();
			passed.push_back(u);
			for(const int v : conn[u]){
				if(done[v]){ continue; }
				done[v] = -done[u];
				q.push(v);
			}
		}
		int b = 1, s = passed.size();
		for(const auto u : passed){
			for(const auto v : conn[u]){
				if(done[u] == done[v]){ b = 0; }
			}
		}
		if(s == 1){
			++single;
		}else if(b){
			++bcount;
		}else{
			++nbcount;
		}
	}
	ll answer =
		static_cast<ll>(n) * single * 2 -
		static_cast<ll>(single) * single;
	answer +=
		static_cast<ll>(bcount) * bcount * 2;
	answer +=
		static_cast<ll>(bcount + nbcount) * nbcount * 2 -
		static_cast<ll>(nbcount) * nbcount;
	cout << answer << endl;
	return 0;
}

