inline int find(int x)
{
	if(x==fa[x])return x;
	int t=find(fa[x]);
	f[x]^=f[fa[x]];
	return fa[x]=t;
}

inline int merge(int x,int y)
{
	if(find(x)==find(y))
	{
		if(f[x]==f[y])v[find(x)]=1;
	}
	else
	{
		int v=f[x]^f[y]^1;
		x=fa[x],y=fa[y];
		sz[x]+=sz[y];
		fa[y]=x,f[y]=v;
		::v[x]|=::v[y];
	}
}

