		M[make_pair(a[i], b[i])] = 1;
		z.push_back(a[i]); z.push_back(b[i]);
	}
	sort(z.begin(), z.end()); z.erase(unique(z.begin(), z.end()), z.end());
	for (int i = 0; i < m; i++) {
		if (a[i] == 0 && b[i] == 0)continue;
		a[i] = lower_bound(z.begin(), z.end(), a[i]) - z.begin();
		b[i] = lower_bound(z.begin(), z.end(), b[i]) - z.begin();
		x[a[i]].push_back(b[i]); x[b[i]].push_back(a[i]);
	}
	long long ans = n*n - 1LL * z.size()*z.size();
	for (int i = 0; i < z.size(); i++) {
		if (col[i] >= 1)continue;
		cnt++; dfs(i);
	}

	UnionFind UF(n);
	for (int i = 0; i < z.size(); i++)d[col[i]]++;
	for (int i = 0; i < m; i++) { if (a[i] >= 1 || b[i] >= 1) e[col[a[i]]]++; }
	for (int i = 0; i < m; i++) { if (a[i] >= 1 || b[i] >= 1) y[col[a[i]]].push_back(make_pair(a[i], b[i])); }

	ans += cnt*cnt;
	long long E = 0;
	for (int i = 1; i <= cnt; i++){
		if (d[i] - 1 == e[i])E++;
		else if (d[i] == e[i]) {
			for (int j = 0; j < y[i].size(); j++) { dist[y[i][j].first] = 999999; dist[y[i][j].second] = 999999; }
			for (int j = 0; j < y[i].size(); j++) {
				if (UF.same(y[i][j].first, y[i][j].second) == true) {
					queue<int>Q; Q.push(y[i][j].first); dist[y[i][j].first] = 0;
					while (!Q.empty()) {
						int a1 = Q.front(); Q.pop();
						for (int k = 0; k < w[a1].size(); k++) {
							if (dist[w[a1][k]] > dist[a1] + 1) {
								dist[w[a1][k]] = dist[a1] + 1;
								Q.push(w[a1][k]);
							}
						}
					}
					if (dist[y[i][j].second] % 2 == 1)E++;
				}
				else {
					UF.unite(y[i][j].first, y[i][j].second);
					w[y[i][j].second].push_back(y[i][j].first);
					w[y[i][j].first].push_back(y[i][j].second);
				}
			}
		}
	}
	ans += E*E;
	cout << ans << endl;
	return 0;
}

