typedef vector<int> vi;

struct UF {
	vi d;
	UF(int n): d(n, -1) {}
	int root(int x) {
    dump(x);
		if (d[x] < 0) return x;
		return d[x] = root(d[x]);
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	int size(int x) {
		return -d[root(x)];
	}
	bool unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return false;
		if (size(x) > size(y)) swap(x, y);
		d[x] += d[y];
		d[y] = x;
		return true;
	}
};
const int MAX_N = 2e5 + 10;
vi es[MAX_N];
int f[MAX_N];
set<int> not2bi;

int calc(UF& uf, int cur, int par) {
	if (f[cur] != 0) return f[cur];
	if (par == -1) f[cur] = 1;
	else f[cur] = -f[par];
  assert(f[cur] != 0);
	for (auto& to : es[cur]) {
		if (to == par) continue;
    if(f[to] == 0) calc(uf, to, cur);
		if (-f[cur] != f[to]) not2bi.insert(uf.root(cur));
	}
	return f[cur];
}

int main() {
	int n, m;
	cin >> n >> m;
  assert(m < 100);
	UF uf(n);
	rep(i, m) {
		int a, b;
		cin >> a >> b;
		a--; b--;
		es[a].pb(b);
		es[b].pb(a);
		uf.unite(a, b);
	}
  LINE;
	rep(i, n) {
    dump(i);
    uf.root(i);
  }
  LINE;
	rep(i, n) if (uf.size(i) > 1 && f[i] == 0) calc(uf, i, -1);
  LINE;
	int zero = 0;
	rep(i, n) if (uf.size(i) == 1) zero++;
	set<int> nibu;
	rep(i, n) if (uf.size(i) > 1 && not2bi.count(uf.root(i)) == 0) nibu.insert(uf.root(i));
	cout << (ll)zero*zero + (ll)zero*(n - zero) * 2LL + (ll)not2bi.size()*not2bi.size() + 2LL * not2bi.size()*nibu.size() + 2LL * nibu.size() << endl;
  dump(zero);
  dump(nibu.size());
  dump(not2bi.size());
  dumpV(nibu);
  dumpV(not2bi);
	return 0;
}

