typedef vector<int> Node;
typedef vector<Node> Graph;
const int MAX_N = 1e5 + 10;
vector<int> bfs(const Graph& G, vector<bool>& used, int s) {
    vector<int> res;
    queue<int> que;
    que.push(s);
    used[s] = true;
    while(!que.empty()) {
        int u = que.front(); que.pop();
        res.push_back(u);
        for(int v : G[u]) {
            if(!used[v]) {
                used[v] = true;
                que.push(v);
            }
        }
    }
    return res;
}
int bipartite_color[MAX_N];
bool bipartite(const Graph& G, vector<int> vs) {
    for(int v : vs) bipartite_color[v] = -1;
    bipartite_color[vs[0]] = 0;
    for(int v : vs) {
        for(int w : G[v]) {
            if(bipartite_color[w] == bipartite_color[v]) {
                return false;
            } else {
                bipartite_color[w] = !bipartite_color[v];
            }
        }
    }
    return true;
}
LL solve(Graph G) {
    int V = G.size();
    vector<bool> used(V, false);
    LL N = 0;
    LL M = 0;
    LL P = 0;
    REP(i, V) if(!used[i]) {
        vector<int> vs = bfs(G, used, i);
        if(vs.size() == 1) {
            P++;
        } else {
            if(bipartite(G, vs)) {
                N++;
            } else {
                M++;
            }
        }
    }
    error(N, M, P);

    LL answer = 0;
    answer += N * N * 2;
    answer += N * M;
    answer += M * N;
    answer += M * M;
    answer += (V-P) * P;
    answer += P * (V-P);
    answer += P * P;
    return answer;
}
Graph random(int N, int p) {
    Graph G(N);
    for(int i = 0; i < N; i++) {
        for(int j = i+1; j < N; j++) {
            if(rand() <= p) {
                G[i].push_back(j);
                G[j].push_back(i);
            }
        }
    }
    return G;
}
