const int MAXN = 1e5 + 10;

struct dsu {
  vector<int> Rank, P;
  int V;
  dsu(int v = 0) : V(v) {
    Rank = vector<int>(v + 1, 0);
    P = vector<int>(v + 1, 0);
    for(int i = 0; i < P.size(); i++) {
      P[i] = i, Rank[i] = 1;
    }
  }
  int find_root(int x) { return x == P[x] ? x : P[x] = find_root(P[x]); }
  void merge(int x, int y) {
    int xr = find_root(P[x]), yr = find_root(P[y]);
    if(xr == yr) return ;
    if(Rank[xr] < Rank[yr]) swap(xr, yr), swap(x, y);
    Rank[xr] += Rank[yr];
    P[yr] = xr;
  }
};

vector<int> adj[MAXN];
bool vis[MAXN];
bool color[MAXN];
bool is_bp[MAXN];
int n, m;
bool dfs(int r) {
  vis[r] = true;
  bool ok = true;
  for(auto &elem: adj[r]) {
    if(vis[elem] == false) {
      color[elem] = color[r] ^ true;
      ok &= dfs(elem);
    } else if(vis[elem] and color[elem] == color[r]) {
      ok = false;
    }
  }
  return ok;
}

int main() {
  ios_base::sync_with_stdio(false);
  int a, b;
  cin >> n >> m;
  dsu tester(n + 1);
  for(int i = 0; i < m; i++) {
    cin >> a >> b;
    adj[a].push_back(b);
    adj[b].push_back(a);
    tester.merge(a, b);
  }
  int bp = 0, nbp = 0;
  LL res = n * (LL)n;
  LL sum = 0;
  for(int i = 1; i <= n; i++) {
    if(tester.find_root(i) == i && tester.Rank[i] > 1) {
      sum += tester.Rank[i];
      if(dfs(i)) {
        is_bp[i] = true;
        bp++;
      } else {
        nbp++;
      }
    }
  }
  for(int i = 1; i <= n; i++) {
    if(tester.find_root(i) == i and tester.Rank[i] > 1) {
      res -= tester.Rank[i] * sum;
      if(is_bp[i]) {
        res += 2 * bp;
        res += nbp;
      } else {
        res += nbp + bp;
      }
    }
  }
  cout << res << endl;
  return 0;
}

