namespace Graph{
	struct edge{
		int y,next;
	}e[MAXN<<1];
	int LINK[MAXN],len=0;
	inline void ins(int x,int y){
		e[++len].next=LINK[x];LINK[x]=len;
		e[len].y=y;
	}
	inline void Ins(int x,int y){
		ins(x,y);
		ins(y,x);
		deg[x]++;deg[y]++;
	}
