int dfs(int i, vector<int> &color, vector<vector<int>> &G){
    int ret = 1;
    for(int j : G[i]){
        if(color[j] == color[i]) ret = 2;
        else if(color[j] == -1){
            color[j] = 1 - color[i];
            ret = max(ret, dfs(j, color, G));
        }
    }
    return ret;
}

int paint(int i, vector<int> &color, vector<vector<int>> &G){
    if(color[i] != -1) return -1;
    color[i] = 0;
    return dfs(i, color, G);
}

