const int MAX_UF = 210000;
struct UnionFind {
    int size_uf;
    int par[MAX_UF];
    int rank[MAX_UF];
    int size_component[MAX_UF];
    bool con[MAX_UF];

    UnionFind(int n = 0) { init(n); }
    void init(int n) { size_uf = n; for (int i = 0; i < n; ++i) par[i] = i, rank[i] = 0, size_component[i] = 1, con[i] = false; }
    int root(int x) { return par[x] == x ? x : par[x] = root(par[x]); }
    bool issame(int x, int y) { return root(x) == root(y); }
    int size(int x) { return size_component[root(x)]; }
    bool iscon(int x) { return con[root(x)]; }

    void connect(int x, int y) {
        x = root(x), y = root(y);
        int sx = size_component[x], sy = size_component[y];
        if (x == y) return;
        int r;
        if (rank[x] < rank[y]) par[x] = y, r = y;
        else { par[y] = x, r = x; if (rank[x] == rank[y]) ++rank[x]; }
        size_component[r] = sx + sy;
    }

    void conset(int x) {
        x = root(x);
        con[x] = true;
    }

    friend ostream& operator << (ostream& s, UnionFind uf) {
        map<int, vector<int> > res;
        for (int i = 0; i < uf.size_uf; ++i) {
            int r = uf.root(i);
            res[r].push_back(i);
        }
        for (map<int, vector<int> >::iterator it = res.begin(); it != res.end(); ++it) {
            s << it->second << endl;
        }
        return s;
    }
} uf;


int N, M;
int main() {
    while (cin >> N >> M) {
        long long res = 0;
        uf.init(N);
        for (int i = 0; i < M; ++i) {
            int u, v;
            cin >> u >> v;
            --u, --v;
            if (uf.issame(u, v)) {
                uf.conset(u);
            }
            else {
                uf.connect(u, v);
            }
        }
        bool used[MAX_UF];
        memset(used, 0, sizeof(used));

        long long S = 0;
        long long CN = 0;
        long long NN = 0;
        for (int v = 0; v < N; ++v) {
            int r = uf.root(v);
            if (used[r]) continue;
            used[r] = true;
            if (uf.size(v) == 1) ++S;
            else if (uf.iscon(v)) ++CN;
            else ++NN;
        }

        /*
        COUT(S);
        COUT(CN);
        COUT(NN);
        */

        res += (CN + NN) * (CN + NN);
        res += NN * NN;

        //COUT(res);

        res += (S * N) * 2 - (S * S);

        cout << res << endl;
    }
}

