struct UnionFind {
    UnionFind(int n) : p(n, -1), r(n) {}
    int root(int u) {
        return p[u] < 0 ? u : p[u] = root(p[u]);
    }
    bool same(int u, int v) {
        return root(u) == root(v);
    }
    void unite(int u, int v) {
        u = root(u);
        v = root(v);
        if (u == v) return;
        if (r[u] > r[v]) swap(u, v);
        p[u] = v;
        r[v] += (r[u] == r[v]);
    }
    vector<int> p, r;
};

int main() {
