        if (uf.p[i] >= 0) continue;
        if (uf.r[i] == 0) k[0]++;
        else {
            int v = i < n ? i + n : i - n;
            k[1 + uf.same(i, v)]++;
        }
    }

    k[0] /= 2;
    k[1] /= 2;
    k[2] += k[1];
    int64_t r = k[0] * (n * 2 - k[0]) + k[2] * k[2] + k[1] * k[1];

