class UF
{
private:
	vector<int> root;
	vector<bool> iscyclic;

public:
	UF(int n)
	{
		root = vector<int>(n + 1, -1);
		iscyclic = vector<bool>(n + 1, false);
	}

	int getroot(int x)
	{
		if(root[x] == -1) return x;
		else return root[x] = getroot(root[x]);
	}

	bool getcyclic(int x)
	{
		return iscyclic[getroot(x)];
	}

	void add(int x, int y)
	{
		x = getroot(x);
		y = getroot(y);
		if(x == y){
			iscyclic[x] = true;
			return;
		}
		if(x > y) swap(x, y);
		root[y] = x;
		iscyclic[x] = (iscyclic[x] || iscyclic[y]);
	}

};

int main()
{
	long long int n, m;
	cin >> n >> m;
	UF uf(n);
	vector<bool> isnoedge(n + 1, true);
	for(int i = 0; i < m; i++){
		int u, v;
		cin >> u >> v;
		uf.add(u, v);
		isnoedge[u] = false;
		isnoedge[v] = false;
	}
	long long int cyclic = 0, notcyclic = 0;
	long long int noedgenode = 0;
	for(int i = 1; i <= n; i++){
		if(isnoedge[i]){
			noedgenode++;
		} else if(uf.getroot(i) == i){
			if(uf.getcyclic(i)) cyclic++;
			else notcyclic++;
		}
	}
	unsigned long long int ans = cyclic * (cyclic + notcyclic);
	ans += notcyclic * (cyclic + 2 * notcyclic);
	ans += 2 * n * noedgenode - noedgenode * (noedgenode + 1) + noedgenode;
	cout << ans << endl;
	return 0;
}

