const int maxn = 1e5 + 5;
const int maxm = 2e5 + 5;

std::vector<int> G[maxn];
int par[maxn], c[maxn];
bool used[maxn];
int N, M;
int num;

void init(int n) {
    for (int i = 0; i <= n; i ++)
        par[i] = i;
}

int findpar(int x) {
    return par[x] = (par[x] == x ? x : findpar(par[x]));
}

void unite(int x, int y) {
    x = findpar(x), y = findpar(y);
    if (x == y) return;
    par[x] = y;
    num --;
}

bool bipartitite(int u) {
    for (int v : G[u]) {
        if (c[u] == c[v]) return false;
        if (!c[v]) {
            c[v] = 3 - c[u];
            if (!bipartitite(v)) return false;
        }
    }
    return true;
}

int main(int argc, char const *argv[]) {
    cin>>N>>M;

    init(N);
    memset(used, false, sizeof(used));
    num = N;
    for (int i = 0; i < M; i ++) {
        int u, v;
        scanf("%d%d", &u, &v);
        used[u] = used[v] = true;
        G[u].push_back(v);
        G[v].push_back(u);
        unite(u, v);
    }


    int I = 0, B = 0;
    for (int i = 1; i <= N; i ++) if (!used[i])
        I ++;

    for (int i = 1; i <= N; i ++) if (used[i] && !c[i]) {
        c[i] = 1;
        if (bipartitite(i)) B ++;
    }

    int P = num - I - B;

    long long ans = 0;
    ans += (ll)I * I + 2ll * I * (N - I);
    ans += (ll)P * P + 2ll * P * B + 2ll * B * B;

    cout<<ans<<endl;
    return 0;
}

