ll N, M;
ll bi = 0, od = 0, si = 0;

int is_bipartite(ll now, ll now_mark){
	if(mark[now]!=-1) return (mark[now]==now_mark);
	mark[now] = now_mark;
	bool flag = true;
	if(G[now].size() == 0) return -1;
	REP(i, G[now].size()){
		ll next = G[now][i];
		flag &= is_bipartite(next, 1-now_mark);
	}
	return (flag ? 1 : 0);
}

int main(){
    cin.tie(0);
