    }
    REP(i, N){
    	if(mark[i] == -1){
    		int tmp = is_bipartite(i, 0);
    		if(tmp == 1) bi++;
    		else if(tmp == 0) od++;
    		else si++;
    	}
    }
    ll res = 0;
    res += (N*N - (N-si)*(N-si));
    res += ((bi+od)*(bi+od) - bi*bi);
    res += (2*bi*bi);
