int dfs(int v) {
    int res = 1;
    used[v] = true;

    for (auto to : g[v])
        if (!used[to])
            res += dfs(to);

    return res;
}

int dfs1(int v) {
    int res = 1;
    used[v] = true;

    for (auto to : g1[v])
        if (!used[to])
            res += dfs1(to);

    return res;
}

bool bip(int v, int cur) {
    col[v] = cur;

    for (auto to : g[v])
        if (col[to] == 0) {
            if (!bip(to, -cur))
                return false;
        } else {
            if (col[to] == col[v])
                return false;
        }

    return true;
}

void solve() {
    fill(used, used + 2 * n, false);
    int kek, kok, lol;
    kek = kok = lol = 0;

    forn (i, n)
        if (!used[i]) {
            if (used[n + i])
                --lol;

            auto cur = dfs1(i);

            if (cur == 1)
                ++kok;
            else
                ++lol, ++kek;
        }

    ll ans = 1ll * n * n;
    fill(used, used + n, false);

    forn (i, n)
        if (!used[i]) {
            auto cur = dfs(i);

            if (cur == 1)
                continue;

            ans -= 1ll * cur * n;

            if (bip(i, 1)) {
                ans += 1ll * cur * kok + kek;
            } else {
                ans += 1ll * cur * kok + lol;
            }
        }

    cout << ans << endl;
}

