using namespace std;
void dfs (
	int crr
, int& cnt
, bool& is_binary
, vector<int>& col
, vector<vector<int>>& grh
) {
	cnt++;
	for (int nxt : grh[crr]) {
		if (col[nxt] ==  -1) {
			col[nxt] = col[crr] ^ 1;
			dfs(nxt, cnt, is_binary, col, grh);
		} else if (col[nxt] == col[crr]) {
			is_binary = false;
		}
	}
}
