	vector<int> col(n, -1);
	long long a(0), b(0), c(0);
	for (int i = 0; i < n; i++) {
		if (col[i] == -1) {
			col[i] = 1;
			dfs(i, cnt = 0, is_binary = true, col, grh);
			if (cnt > 1 && is_binary) a++;
			else if (cnt > 1 && not is_binary) b++;
			else c++;
		}
	}
