const int maxn = 1e5 + 5;
int n, m;
vi adj[maxn];
vii edge;
int f[maxn];
int g[maxn];
int sum[maxn];

int dj[maxn];
void init() {
    FOR(i, 0, n) dj[i] = i;
}
int find(int u) {
    return dj[u] == u ? dj[u] : dj[u] = find(dj[u]);
}
int join(int u, int v) {
    int p = find(u);
    int q = find(v);
    if (p != q) {
        dj[p] = q;
        return 1;
    }
    return 0;
}

void dfs(int u, int p, int x) {
    f[u] = x;
    sum[find(u)]++;
    for (int v : adj[u]) {
        if (v != p) {
            dfs(v, u, !x);
        }
    }
}

void solve() {
    cin >> n >> m;
    init();
    FOR(i, 0, m) {
        int u, v; cin >> u >> v; u--, v--;
        if (join(u, v)) {
            adj[u].pb(v);
            adj[v].pb(u);
        }
        else {
            edge.pb(mp(u, v));
        }
    }
    FOR(i, 0, n) if (dj[i] == i) {
        dfs(i, -1, 0);
    }
    for (pi p : edge) {
        int u = p.fi;
        int v = p.se;
        if (f[u] == f[v]) {
            g[find(u)] = 1;
        }
    }
    int tot[3] = {};
    FOR(i, 0, n) if (dj[i] == i) {
        if (sum[i] == 1) {
            tot[0]++;
        }
        else if (!g[i]) {
            tot[1]++;
        }
        else {
            tot[2]++;
        }
    }
    long long ans = 0;
    ans += (long long) tot[0] * n + (n - tot[0]) * tot[0];
    ans += (long long) tot[1] * tot[1] * 2;
    ans += (long long) tot[2] * tot[2];
    ans += (long long) tot[1] * tot[2];
    ans += (long long) tot[2] * tot[1];
    cout << ans << "\n";
}

