int used[maxn];

bool ok;

void dfs(int v) {
  for (int u : es[v]) {
    int ncol = (used[v] ^ 1);
    if (used[u] != -1) {
      if (used[u] != ncol) {
        ok = 0;
      }
      continue;
    }
    used[u] = ncol;
    dfs(u);
  }
}

void solve() {
  for (int i = 0; i < n; ++i) {
    used[i] = -1;
  }
  long long one = 0, two = 0, three = 0;
  for (int i = 0; i < n; ++i) {
    if (used[i] != -1) {
      continue;
    }
    if (sz(es[i]) == 0) {
      ++one;
      continue;
    }

    ok = 1;
    used[i] = 0;
    dfs(i);

    (ok ? two : three) += 1;
  }
  //eprintf("%lld %lld %lld\n", one, two, three);

  long long res = one * one + 2 * one * (n - one);
  res += (three + two) * (three + two);
  res += two * two;
  printf("%lld\n", res);
}

