bool dfs(const vector<vecint>& g, vecint& clr, int i, int c) {
  clr[i] = c;
  bool ok = true;
  for (auto&& to : g[i]) {
    if (clr[to] == c) ok = false;
    if (clr[to] >= 0) continue;
    if (!dfs(g, clr, to, 1-c)) ok = false;
  }
  return ok;
}

