    g[v].push_back(u);
  }
  vecint clr(n, -1);
  ll alone = 0;
  ll bipartite = 0;
  ll other = 0;
  REP(i,n) {
    if (clr[i] == -1) {
      if (g[i].empty()) ++alone;
      else if (dfs(g, clr, i, 0)) ++bipartite;
      else ++other;
    }
  }
  ll ans = 2 * n * alone - alone * alone;
  ll total = bipartite + other;
  ans += 2 * total * other - other * other;
  ans += 2 * bipartite * bipartite;
  cout<<ans<<endl;
  return 0;
}

