  UnionFind latte(N + N), malta(N);
  for(int i = 0; i < M; i++) {
    int x, y;
    cin >> x >> y;
    --x, --y;
    latte.unite(x + N, y);
    latte.unite(y + N, x);
    malta.unite(x, y);
  }

  int64 uku = 0, one = 0, two = 0;
  for(int i = 0; i < N; i++) {
    if(malta.find(i) != i) continue;
    if(malta.size(i) == 1) ++uku;
