		u--; v--;
		M[u].push_back(v);
		M[v].push_back(u);
		used[u] = used[v] = true;
	}

	ll single = 0, nibu = 0, ki = 0;
	for (i = 0; i < n; i++) {
		if (!used[i]) {
			single++;
		}
		else {
			if (color[i] == -1) {
				if (bipartite(i)) {
					nibu++;
				}
				else {
					ki++;
				}
			}
		}
	}
	ll ans = 0;
	for (i = 0; i < single; i++) {
		ans += 2 * (n - i) - 1;
	}
	ans += 2 * nibu + ki;
	ans += 2 * nibu*(nibu - 1) + 2 * nibu * ki + ki * (ki - 1);
	cout << ans << endl;

