constexpr int nax = 1e5, maxm = 2e5;

int n, m, col[nax + 1], cnt[3];
V< int > gr[nax + 1];

int dfs(const int v)
{
    if (not col[v]) col[v] = 1;
    for (int s : gr[v])
    {
        if (not col[s])
        {
            col[s] = 3 - col[v];
            if (dfs(s) == 1) return 1;
        }
        if (col[s] == col[v]) return 1;
    }
    return 2;
}

