    }

    for (int i = 1; i <= n; ++i)
        if (not col[i])
        {
            if (gr[i].empty()) ++cnt[0];
            else ++cnt[dfs(i)];
        }

    ll res = 0;
    res += 2 * (ll)cnt[0] * (n - cnt[0]);
    res += (ll)cnt[0] * cnt[0];

    res += 2 * (ll)(cnt[1]) * cnt[2];
