	int X=0,Y=0,x=find(gi(),X),y=find(gi(),Y);
	if(x!=y) fa[x]=y,v[x]=X^Y^1,w[y]|=w[x],sz[y]+=sz[x];
	else w[x]|=X^Y^1;
    }
    for(int i=1;i<=n;i++)
	if(fa[i]==i) {
	    if(sz[i]==1) ++A;
	    else if(w[i]) ++B;
	    else ++C;
	}
