struct Edge { int from, to; Edge(int from, int to) { this->from = from; this->to = to; } Edge() { } };
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

int n, m;
Graph g;
vector<Graph> gs;

void labeling() {
	static bool used[100000] = {false};
	static int num[100000];
	queue<int> que;
	int i, j, k;

	for (i = 0; i < n; i++) {
		if (used[i]) continue;

		vector<int> vs;

		used[i] = true; que.push(i); num[i] = 0; vs.push_back(i);

		while (!que.empty()) {
			int v = que.front(); que.pop();
			for (j = 0; j < g[v].size(); j++) {
				int nv = g[v][j].to;
				if (!used[nv]) {
					used[nv] = true;
					que.push(nv);
					num[nv] = vs.size();
					vs.push_back(nv);
				}
			}
		}

		//gs[-]の作成
		Graph gg;

		gg.resize(vs.size());
		for (j = 0; j < vs.size(); j++) {
			for (k = 0; k < g[vs[j]].size(); k++) {
				int to = g[vs[j]][k].to;
				gg[j].push_back(Edge(j, num[to]));
			}
		}
		gs.push_back(gg);
	}
}

//連結なグラフが与えられるので、2彩色できるか判定する。
bool isBinary(Graph &g) {
	vector<int> color(g.size());
	queue<int> que;
	int i;

	for (i = 0; i < g.size(); i++) color[i] = -1;
	que.push(0);
	color[0] = 0;

	while (!que.empty()) {
		int v = que.front(); que.pop();
		for (i = 0; i < g[v].size(); i++) {
			int nv = g[v][i].to;
			if (color[nv] == -1) {
				que.push(nv);
				color[nv] = !color[v];
			}
			else if (color[nv] == color[v]) {
				return false;
			}
		}
	}
	return true;
}

signed main() {
	int i;

	cin >> n >> m;
	g.resize(n);
	for (i = 0; i < m; i++) {
		int u, v;
		cin >> u >> v;
		u--; v--;
		g[u].push_back(Edge(u, v));
		g[v].push_back(Edge(v, u));
	}

	labeling();

	int x = 0, y = 0, z = 0;
	for (i = 0; i < gs.size(); i++) {
		if (gs[i].size() == 1) x++;
		else if (isBinary(gs[i])) y++;
		else z++;
	}

	//cout << x << " " << y << " " << z << endl;

	int ans = 2 * x * (n - x) + 1;

	ans += y * y * 2;
	ans += y * z * 1;

	ans += z * y * 1;
	ans += z * z * 1;
	cout << ans << endl;
	return 0;
}

