const int N = 100010;

struct edge{
	int next, to;
};

edge e[N << 2];
bool vis[N];
int first[N], n, m, e_cnt = 0, col[N];

void addedge(int u, int v){
	e[++ e_cnt] = {first[u], v};
	first[u] = e_cnt;
	e[++ e_cnt] = {first[v], u};
	first[v] = e_cnt;
}

bool dfs(int u){
	vis[u] = true;
	for (int i = first[u]; i; i = e[i].next){
		int v = e[i].to;
		if (vis[v]){
			if (col[v] == col[u]){
				return false;
			}
			continue;
		}
		col[v] = !col[u];
		if (!dfs(v)){
			return false;
		}
	}
	return true;	
}

int main(){
	scanf("%d%d", &n, &m);
	for (int i = 0, u, v; i < m; ++ i){
		scanf("%d%d", &u, &v);
		addedge(u, v);
	}
	int a = 0, n1 = 0, n2 = 0;
	for (int i = 1; i <= n; ++ i){
		if (!first[i]){
			++ a;
			continue;
		}
		if (vis[i]){
			continue;
		}
		dfs(i) ? ++ n1 : ++ n2;
	}
	ll ans = 1ll * n * n - 1ll * (n - a) * (n - a);
	ans += 2 * n1 + n2 + 2 * (1ll * n1 * (n1 - 1) + 1ll * n2 * (n2 - 1) / 2 + 1ll * n1 * n2);
	return printf("%lld\n", ans), 0;
}

/*
新图中(x, y)和(p, q)联通，当且仅当：存在一条长度为l的从x走到p的路径，和一条长度为l的从y走到q的路径
因为可以在一条边上来回走，所以只要判断是否存在两条长度奇偶性相同的从x走到p、从y走到q的路径 
(1)当a和b在一个是二分图的联通块中时，a到b所有路径长度奇偶性相同：进行二分图染色，同色点之间都是偶数、异色点之间都是奇数
(2)当a和b在一个存在奇环的联通块中时，a到b存在长度为奇数的路径、也存在长度为偶数的路径
(3)当(x, y)中有一个点是孤立点时，(x, y)单独成为一个联通块
根据(1)(2)(3)可以直接分类讨论计数
*/

