const int Max_N(100050);
const int Max_M(200050);

int N, M, Head[Max_N], Total, To[Max_M << 1], Next[Max_M << 1];

inline void Add_Edge(int s, int t)
{
	++Total, To[Total] = t, Next[Total] = Head[s], Head[s] = Total;
}

int color[Max_N], A, B, C, V;
LL Ans;

bool dfs(int u)
{
	++V;
	for (int i = Head[u], v;i;i = Next[i])
		if (!color[v = To[i]])
		{
			color[v] = 3 - color[u];
			if (dfs(v) == false)
				return false;
		}
		else
			if (color[v] == color[u])
				return false;
	return true;
}

int main()
{
	gi(N), gi(M);
	for (int u, v;M--;)
		gi(u), gi(v), Add_Edge(u, v), Add_Edge(v, u);
	for (int u = 1;u <= N;++u)
	{
		if (color[u])
			continue;
		if (color[u] = 1, V = 0, dfs(u))
			if (V > 1)
				Ans += (A * 2 + B) * 2 + 2, ++A;
			else
				++C;
		else
			Ans += (A + B) * 2 + 1, ++B;
	}
	print(Ans + C * 2LL * (N - C) + C * 1LL * C);
	return 0;
}

