			st.push(i);
			vtak[i].pb(0);
			while (!st.emp) {
				now = st.tp;
				st.pop();
				if (!vuse[now]) vvv.pb(now);
				vuse[now] = 1;
				ROR(adj[now], i) {
					if (!euse[i.fi]) {
						euse[i.fi] = 1;
						vtak[i.se].pb(vtak[now][0] + 1);
						st.push(i.se);
					}
				}
			}
			ll chk = 1;
			ROR(vvv, i) {
				if (vtak[i].sz >= 2) {
					REP(j, vtak[i].sz - 1) {
						if (abs(vtak[i][j + 1] - vtak[i][j]) % 2) {
							chk = 0;
						}
					}
				}
			}
			if (vvv.sz >= 2) {
				hei[uft.root(i)] = 1 + chk;
				maa += vvv.sz;
				roots.pb(uft.root(i));
			}
		}
	}
	ll ans = 0;
	maa = N - maa;
	ans += 2 * N*maa - maa * maa;
	ll ghe = 0;
	REP(i, roots.sz) {
		if (hei[roots[i]] == 2) ghe++;
	}
	ans += roots.sz*roots.sz;
	ans += ghe * ghe;
	sal(ans);
}

