using namespace std;

int main()
{
	int N, M;
	cin >> N >> M;
	vector<vector<int>> edges(N);
	for (int i = 0; i < M; i++)
	{
		int a, b;
		cin >> a >> b;
		edges[a - 1].push_back(b - 1);
		edges[b - 1].push_back(a - 1);
	}

	int V = 0, K1 = 0, K2 = 0;
	vector<bool> used(N, false);
	vector<int> mark(N, -1);
	vector<int> edge(N);
	for (int i = 0; i < N; i++)
	{
		if (used[i] == false)
		{
			stack<int> st;
			st.push(i);
			mark[i] = 0;
			bool cycle = false;
			int count = 0;
			while (!st.empty())
			{
				int u = st.top();
				if (edge[u] == edges[u].size())
				{
					used[u] = true;
					st.pop();
					count++;
					continue;
				}

				int v = edges[u][edge[u]++];
				if (mark[v] > -1)
				{
					if (((mark[u] + 1 - mark[v]) & 1) == 1)
						cycle = true;
				}
				else
				{
					mark[v] = mark[u] + 1;
					st.push(v);
				}
			}

			if (count == 1)
				V++;
			else if (cycle)
				K1++;
			else
				K2++;
		}
	}

	cout << K1*K1 + 2 * K1 * K2 + 2 * K2 * K2 + V*(2*N-V);
	return 0;
}

