#include <bits/stdc++.h>
using namespace std;

const int N = (int) 1e5;
vector<int> graph[N];
int lab[N], small[N];
bool visited[N][2];
int smallest[N][2];
int n, m;

int get(int u) {
	return lab[u] < 0 ? u : lab[u] = get(lab[u]);
}

void join(int u, int v) {
	u = get(u);
	v = get(v);
	if (u == v) return;
	if (lab[u] < lab[v]) swap(lab[u], lab[v]);
	lab[v] += lab[u];
	small[v] = min(small[v], small[u]);
	lab[u] = v;
}

void bfs() {
	for (int u = 0; u < n; ++u) if (small[get(u)] == u) {
		queue<tuple<int, int> > q;
		q.emplace(u, 0);
		visited[u][0] = true;
		while (!q.empty()) {
			int u, odd;
			tie (u, odd) = q.front();
			q.pop();
			for (auto v : graph[u]) {
				if (!visited[v][1 - odd]) {
					q.emplace(v, 1 - odd);
					visited[v][1 - odd] = true;
				}
			}
		}
	}
}

void dijkstra() {
	memset(smallest, 0x3f, sizeof smallest);
	priority_queue<tuple<int, int, int> > q;
	for (int u = 0; u < n; ++u) {
		q.emplace(-u, u, 0);
		smallest[u][0] = u;
	}
	while (!q.empty()) {
		int small, u, odd; tie (small, u, odd) = q.top(); small = -small; q.pop();
		if (small != smallest[u][odd]) continue;
		for (auto v : graph[u]) {
			if (small < smallest[v][1 - odd]) {
				smallest[v][1 - odd] = small;
				q.emplace(-small, v, 1 - odd);
			}
		}
	}
}

int main() {
	ios::sync_with_stdio(false);
	cin >> n >> m;
	for (int i = 0; i < n; ++i) lab[i] = -1, small[i] = i;
	for (int i = 0; i < m; ++i) {
		int x, y; cin >> x >> y; --x; --y;
		graph[x].push_back(y);
		graph[y].push_back(x);
		join(x, y);
	}

	bfs();
	dijkstra();

	long long res = 0;
	int degree0 = 0;
	int n0 = 0, n1 = 0, n01 = 0;
	for (int i = 0; i < n; ++i) if (graph[i].size() == 0) ++degree0;
	for (int i = 0; i < n; ++i) {
		if (smallest[i][0] >= i) ++n0;
		if (smallest[i][1] >= i) ++n1;
		if (smallest[i][0] >= i && smallest[i][1] >= i) ++n01;
	}
	for (int a = 0; a < n; ++a) {
		long long old = res;
		if (graph[a].size() == 0) {
			res += n;
		} else if (small[get(a)] < a) {
			res += degree0;
		} else {
			if (visited[a][0] && visited[a][1]) res += n01;
			else if (visited[a][0]) res += n0;
			else if (visited[a][1]) res += n1;
		}
		//cout << a << ' ' << small[get(a)] << ' ' << res - old << '\n';
	}
	cout << res << '\n';
	return 0;
}

