int main() {
	cin >> N >> M;
	rep(i, 0, M) {
		int u, v; scanf("%d%d", &u, &v);
		E[u].push_back(v); E[v].push_back(u);
		uf(u, v);
	}

	auto m = divide();
	int cnt[3] = { 0, 0, 0 };
	for (auto p : m) {
		auto v = p.second;
		if (v.size() == 1) {
			cnt[0]++;
			continue;
		}

		if (calc(v) == 1) cnt[1]++;
		else cnt[2]++;
	}

	ll ans = 1LL * N * N - 1LL * (N - cnt[0]) * (N - cnt[0]);
	ans += 1LL * (cnt[2] + cnt[1]) * (cnt[2] + cnt[1]);
	ans += 1LL * cnt[2] * cnt[2];

	cout << ans << endl;
}

