using P = pair<int, int>;
ll INF = 1e9;
int main()
{
    int n, m;
    cin >> n >> m;
    vector<set<int>> d(n);
    for(int i = 0; i < m; i++)
    {
        int u, v;
        cin >> u >> v;
        u--;v--;
        d[u].insert(v);
        d[v].insert(u);
    }
    vector<bool> was(n);
    function<P(int)> dfs = [&](int v)
    {
        int f = 0;
        if(!was[v])
        {
            f = 1;
            was[v] = true;
        }
        int s = 0;
        while(d[v].size())
        {
            int nx = *d[v].begin();
            d[v].erase(nx);
            d[nx].erase(v);
            P p = dfs(nx);
            f += p.first;
            s += p.second+1;
        }
        return P(f, s);
    };
    vector<ll> tree;
    vector<ll> ntree;
    for(int i = 0; i < n; i++)
    {
        if(!d[i].size()) continue;
        P p = dfs(i);
        if(p.first > p.second)
        {
            tree.push_back(p.first);
        }
        else ntree.push_back(p.first);
    }
    ll sum = n * n;
    ll ans = 0;
    int ts = tree.size();
    int nts = ntree.size();
    ll sumt = 0;
    ll sumnt = 0;
    // t
    for(int i = 0; i < ts; i++)
    {
        sum -= tree[i] * tree[i];
        ans += 2;
        sumt += tree[i];
    }
    // nt
    for(int i = 0; i < nts; i++)
    {
        sum -= ntree[i] * ntree[i];
        ans += 1;
        sumnt += ntree[i];
    }
    // t * t
    for(int i = 0; i < ts; i++)
    {
        ll tmp = sumt - tree[i];
        sum -= tree[i] * tmp;
        ans += 2 * (ts-1);
    }
    // nt * nt
    for(int i = 0; i < nts; i++)
    {
        ll tmp = sumnt - ntree[i];
        sum -= ntree[i] * tmp;
        ans += nts-1;
    }
    // t * nt
    sum -= sumt * sumnt * 2;
    ans += ts * nts * 2;
    cout << ans + sum << endl;
}

