struct UF{
    vector<int> par;
    vector<int> sz;
    vector<int> cnt;
    UF(){}
    UF(int n){
        par.resize(n);
        sz.resize(n, 1);
        cnt.resize(n, 0);
        rep(i, 0, n) par[i] = i;
    }
    int find(int x){
        if(x == par[x]) return x;
        return par[x] = find(par[x]);
    }
    void unite(int x, int y){
        x = find(x); y = find(y);
        if(x == y){
            cnt[x]++;
            return;
        }
        if(sz[x] < sz[y]) swap(x, y);
        sz[x] += sz[y];
        cnt[x] += cnt[y] + 1;
        par[y] = x;
    }
    bool same(int x, int y){
        return find(x) == find(y);
    }
};
