template <typename T>
struct UnionFind {
   private:
    vector<T> par;
    vector<T> rank;
    vector<T> sz;
    int n;

   public:
    // n要素で親を初期化、par[x]はxの親を表す
    UnionFind(int n) : n(n) {
        par.resize(n, 0);
        rank.resize(n, 0);
        sz.resize(n, 1);
        for(int i = 0; i < n; i++) {
            par[i] = i;
        }
    }

    //木の根を求める
    int root(int x) {
        if(par[x] == x)
            return x;
        else
            return par[x] = root(par[x]);
    }

    // xとyの属する集合を併合
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if(x == y) return;

        if(rank[x] < rank[y]) {
            swap(x, y);
        }

        par[y] = x;
        sz[x] += sz[y];
        if(rank[x] == rank[y]) rank[x]++;
    }

    // xとyが同じ集合に属するか否か
    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    // xが属する集合のサイズを返す
    int size(int x) {
        return sz[root(x)];
    }

    // 集合の数を返す
    int num_of_s() {
        vector<int> cnt(n);
        int ans = 0;
        for(int i = 0; i < n; i++) {
            if(!cnt[root(i)]) ans++, cnt[root(i)] = 1;
        }
        return ans;
    }
};

signed main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    ll n,m; cin >> n >> m;
    UnionFind<ll> uf(n * 2), par(n);
    rep(i,0,m){
        ll u,v; cin >> u >> v;
        u--;v--;
        uf.unite(u, v + n);
        uf.unite(v, u + n);
        par.unite(u, v);
    }

    ll x = 0, y = 0, z = 0;
    vector<ll> used(n);
    rep(i,0,n){
        ll p = par.root(i);
        if(used[p])continue;
        if(uf.size(i) == 1){
            x++;
            used[p] = 1;
            continue;
        }
        if(uf.issame(i , i + n)){
            z++;
            used[p] = 1;
        }
        else{
            y++;
            used[p] = 1;
        }
        debug(used);
    }
    debug(x, y, z);
    ll ans = x * n * 2 - x * x + y * y * 2 + y * z * 2 + z * z;
    cout << ans << endl;
}

