  rep(i,n) if(uf.par[i]<0){ // for root
    if(uf.size(i)==1) alone++;
    else if( uf.size(i)-1==cnt[i] || (uf.size(i)==cnt[i] &&  isgood[i] && uf.size(i)%2==0) ) good++;
    else bad++;
  }
//  dbg(alone),dbg(good),dbg(bad);

  long ans = alone*n*2L - alone*alone;
  ans += 2L*good*good;
  ans += bad*bad;
  ans += 2L*good*bad;

