class Solution {
public:
    void solve() {
        int n, m;
        cin >> n >> m;
        adjList.assign(n, vector<int>());
        int u, v;
        for (int i = 0; i < m; i++) {
            cin >> u >> v;
            adjList[u - 1].push_back(v - 1);
            adjList[v - 1].push_back(u - 1);
        }

        long iso = 0, bp = 0, other = 0;
        color.assign(n, 0);
        for (int i = 0; i < n; i++) {
            if (color[i]) continue;
            if (adjList[i].empty()) {
                color[i] = 1;
                iso++;
                continue;
            }
            if (dfs(i, 1)) {
                bp++;
            } else {
                other++;
            }
        }

        long res = (2 * n - 1) * iso;
        res += (bp + other) * (bp + other);
        res += bp * bp;
        cout << res << endl;
    }

private:
    vector<vector<int>> adjList;
    vector<int> color;

    bool dfs(int i, int c) {
        if (color[i]) {
            return color[i] == c;
        }
        color[i] = c;
        bool res = true;
        for (int v: adjList[i]) {
            if (!dfs(v, 3 - c)) {
                res = false;
            }
        }
        return res;
    }
};

