struct UnionFind{
    vector<int> par,dep;
    UnionFind(int n){
        dep.assign(n,1);
        par.assign(n,0);
        for(int i=0;i<n;i++)par[i]=i;
    }
    int find(int x){
        if(par[x]==x){
            return x;
        }else{
            return par[x]=find(par[x]);
        }
    }
    bool unite(int u,int v){
        u=find(u);
        v=find(v);
        if(u==v)return false;
        if(dep[u]>dep[v]){
            par[v]=u;
        }else if(dep[u]<=dep[v]){
            par[u]=v;
            if(dep[u]==dep[v]){
                dep[v]++;
            }
        }
        return true;
    }
};
int main(){
    ll n,m;cin>>n>>m;
    UnionFind uf(n);
    vector<int> f(n);
    for(int i=0;i<m;i++){
        int u,v;cin>>u>>v;--u;--v;
        if(!uf.unite(u,v)){
            f[u]=1;
            f[v]=1;
        }
    }
    vector<P> s(n,P(0LL,0));
    for(int i=0;i<n;i++){
        s[uf.find(i)].first++;
        s[uf.find(i)].second|=f[i];
    }
    ll ans=n*n;
    ll c1=0LL,c2=0LL,s1=0LL,s2=0LL;
    for(int i=0;i<n;i++){
        if(s[i].first>=2LL){
