            }else{
                ans-=s[i].first*s[i].first-2LL;
                ans-=((s1*s[i].first-c1)+(s2*s[i].first-c2*2LL))*2LL;
                s2+=s[i].first;
                c2+=1LL;
            }
        }
    }
    cout<<ans<<endl;
}

