void dfs(int node){
    comp[node] = cur;
    ++sz[cur];
    for(int next : v[node]){
        if(comp[next]){
            if(col[next] == col[node]){
                rekt[cur] = 1;
            }
        }
        else{
            col[next] = col[node] ^ 1;
            dfs(next);
        }
    }
}
int main(){
    scanf("%d %d" , &n , &m);
    for(int i = 1 ; i <= m ; ++i){
        scanf("%d %d" , a + i , b + i);
        v[a[i]].emplace_back(b[i]);
        v[b[i]].emplace_back(a[i]);
    }
    for(int i = 1 ; i <= n ; ++i){
        rekt[i] = 0;
        col[i] = -1;
        comp[i] = 0;
        sz[i] = 0;
    }
    cur = 0;
    ans = 0;
    int big = 0;
    int bip = 0;
    for(int i = 1 ; i <= n ; ++i){
        if(!comp[i]){
            col[i] = 0;
            ++cur;
            dfs(i);
            if(sz[cur] > 1){
                ++big;
                if(!rekt[cur]){
                    ++bip;
                }
            }
        }
    }
    for(int i = 1 ; i <= cur ; ++i){
        if(sz[i] == 1){
            ans += n + n - 1;
        }
        else if(rekt[i]){
            ans += big;
        }
        else{
            ans += big + bip;
        }
    }
    printf("%lld\n" , ans);
}

