void add_edge(int u,int v,int w)
{
    e[++esum].to=v;
    e[esum].capa=w;
    e[esum].next=h[u];
    h[u]=esum;
}

void dijkstra()
{
    memset(dis,0x3f,sizeof(dis));
    q.push(MP(0,1));dis[1]=0;
    while(!q.empty())
    {
        pii tmp=q.top();q.pop();
        int u=tmp.SE,w=-tmp.FR;
        if(vis[u]) continue;
        vis[u]=1;
        for(pii pr : G[u])
            if(w+pr.SE<dis[pr.FR])
            {
                dis[pr.FR]=w+pr.SE;
                q.push(MP(-dis[pr.FR],pr.FR));
            }
    }
}

void find(int u,int fa)
{
    sz[u]=1;mxsz[u]=0;
    for(int t=h[u];t;t=e[t].next)
    {
        int v=e[t].to;
        if(v==fa||vis[v]) continue;
        find(v,u);sz[u]+=sz[v];
        mxsz[u]=max(mxsz[u],sz[v]);
    }
    mxsz[u]=max(mxsz[u],sum-sz[u]);
    if(mxsz[u]<mxsz[root]) root=u;
}

void dfs(int u,int fa)
{
    now[++tot]=d[u];
    for(int t=h[u];t;t=e[t].next)
    {
        int v=e[t].to;
        if(v==fa||vis[v]) continue;
        d[v].SE=d[u].SE+e[t].capa;
        d[v].FR=d[u].FR+1;dfs(v,u);
    }
}

void gao(int u,int w)
{
    d[u].FR=1;d[u].SE=w;
