bool dfs(int cur, int st){
	vis[cur] = st;
	bool ret = false;
	for(auto &next : adj[cur]){
		if(vis[next] != -1){
			if(vis[next] == vis[cur])	ret |= 1;
		}
		else{
			ret |= dfs(next, st ^ 1);
		}
	}
	return ret;
}

