        if (used[to]) {
          if (nod != od[to]) {
            //fprintf(stderr, "odd at %d -> %d\n", fm + 1, to + 1);
            odd = true;
          }
        } else {
          ++card;
          q.push(to);
          od[to] = nod;
          used[to] = true;
        }
      }
    }
    if (odd) {
      o.push_back(card);
    } else {
      e.push_back(card);
    }
  }

  li total = len(e) + len(o);
  printf("%lld\n", sqr(single) + single * (n - single) * 2 + len(e) * 2 + len(o) + total * (total - 1));
  return 0;
}

