/*-----8<-----template-----8<-----*/
pair<ll,bool> isBipartiteGraph(vector<vector<ll>> &g, ll v, vector<ll> &seen) {
	ll s=0;
	auto dfs = [&](auto&& dfs, vector<vector<ll>> &g, ll v, vector<ll> &seen, bool &isBipartite) -> bool {
		s++;
		for(ll nextv:g[v]){
			if(seen[nextv]){
				if(seen[nextv]==seen[v])isBipartite=false;
				continue;
			}
			seen[nextv]=-1*seen[v];
			dfs(dfs, g, nextv, seen, isBipartite);
		}
		return true;
	};
	seen[v]=1;
	bool isBipartite=true;
	dfs(dfs, g, v, seen, isBipartite);
	return {s,isBipartite};
}

