			UL a, b; cin >> a >> b; a--; b--;
			E[a].push_back(b);
			E[b].push_back(a);
		}
		vector<int> F(N);
		ULL z, b, u; z = b = u = 0;
		rep(s, N) {
			if (F[s]) continue;
			F[s] = s + 1;
			if (E[s].size() == 0) {
				z++; F[s] = s + 1; continue;
			}
			queue<UL> Q; Q.push(s);
			bool bok = true;
			while (Q.size()) {
