int sz[N], C[2][N], cycle[N];
vi adj[N];

int t[2], tn;
pii tc;

void add(int x) {
	if (!cycle[x]) {
		for (int j = 0; j < 2; j++) {
			t[j] += C[j][x];
		}
		tn++;
	}	else {
		tc.F += sz[x];
		tc.S++;
	}
}

void del(int x) {
	if (!cycle[x]) {
		for (int j = 0; j < 2; j++) {
			t[j] -= C[j][x];
		}
		tn--;
	}	else {
		tc.F -= sz[x];
		tc.S--;
	}
}

void dfs(int v, int p) {
	used[v] = 1;
	C[h[v]][cnt]++;
	sz[cnt]++;
	for (int to : adj[v]) {
		if (to == p) {
			continue;
		}
		if (used[to] == 1) {
			if (h[to] ^ h[v] ^ 1) {
				cycle[cnt] = 1;
			}
		}
		if (used[to] == 0) {
			h[to] = h[v] ^ 1;
			dfs(to, v);
		}
	}
	used[v] = 2;
}

