		}
		del(i);
		if (!cycle[i]) {
			res += (ll)C[0][i] * C[0][i] + (ll)C[1][i] * C[1][i] - 1;
			res += (ll)C[0][i] * C[1][i] + C[1][i] * C[0][i] - 1;

