		gnxt[2*i+1]=ghead[b]; ghead[b]=2*i+1; gto[2*i+1]=a;
	}
	memset(state,0,sizeof(state));
	REP(i,n) if(state[i]==0) {
		qhead=qtail=0;
		state[i]=1,comp[i]=ncomp++,q[qhead++]=i;
		while(qtail<qhead) {
			int at=q[qtail++];
			for(int x=ghead[at];x!=-1;x=gnxt[x]) {
				int to=gto[x];
				int nval=3-state[at];
				if((state[to]|nval)==state[to]) continue;
				state[to]|=nval,comp[to]=comp[i],q[qhead++]=to;
