	REP(i,ncomp) cnt[i]=0,bip[i]=true; REP(i,n) ++cnt[comp[i]]; REP(i,n) if(state[i]==3) bip[comp[i]]=false;
	int nsingle=0,nbip=0; REP(i,n) if(cnt[i]==1) ++nsingle; else if(bip[i]) ++nbip;
