bool dfs(int v) {
    bool ret = false;

    for (int sv : path[v]) {
        if (d[sv] < 0) {
            d[sv] = d[v] + 1;
            ret = ret || dfs(sv);
        } else if ((d[v] - d[sv]) % 2 == 0) {
            ret = true;
        }
    }

    return ret;
}

