int bfs(vector<vector<ll>> &g , ll st,vector<ll> &see,vector<ll> &dist){
  ll rt=1;
  queue<ll> q;
  see[st]=1;
  q.push(st);
  while(!q.empty()){
    auto p=q.front();
    see[p]=1;
    q.pop();
    for(auto r:g[p]){
      if(see[r]!=0){
        if(dist[r]%2==dist[p]%2)rt=2;
        continue;
      }
      dist[r]=dist[p]+1;
      q.push(r);
    }
  }
  return rt;
}
