struct SegT {
private:
	int n; vector<ll> node, lazy;
	const ll init_c = 0;
public:
	SegT(int sz) {
		n = 1;
		while (n < sz)n <<= 1;
		node.resize(2 * n - 1, 0);
		lazy.resize(2 * n - 1, 0);
	}
	ll f(ll a, ll b) {
		return max(a, b);
	}
	void eval(int k, int l, int r) {
		node[k] += lazy[k];
		if (r - l > 1) {
			lazy[2 * k + 1] += lazy[k];
			lazy[2 * k + 2] += lazy[k];
		}
		lazy[k] = 0;
	}
	void add(ll x, int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		eval(k, l, r);
		if (r <= a || b <= l)return;
		if (a <= l && r <= b) {
			lazy[k] += x; eval(k, l, r);
		}
		else {
			add(x, a, b, k * 2 + 1, l, (l + r) / 2);
			add(x, a, b, k * 2 + 2, (l + r) / 2, r);
			node[k] = f(node[k * 2 + 1], node[k * 2 + 2]);
		}
	}
	ll query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0)r = n;
		eval(k, l, r);
		if (r <= a || b <= l)return init_c;
		if (a <= l && r <= b)return node[k];
		else {
			ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
			ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return f(vl, vr);
		}
	}
};

ll used[101010];
bool dfs(Graph& g, ll v, ll col,ll& cnt,ll &w) {
	bool ret = false;
	used[v] = col;
	if (col == 1)w++;
	cnt++;
	REP(i, g[v].size()) {
		ll to = g[v][i].to;
		if (used[to] == 0)ret |= dfs(g, to, col * -1, cnt, w);
		else if (used[to] == col)ret = true;
	}
	return ret;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	ll n, m;
	cin >> n >> m;
	Graph g(n);
	REP(i, m) {
		ll u, v;
		cin >> u >> v;
		u--; v--;
		add_edge(g, u, v, 1, true, 1);
	}
	ll ans = n * n;
	P bi = { 0,0 };
	ll W = 0, B = 0, N = 0;
	REP(i, n) {
		if (used[i] == 0) {
			ll cnt = 0;
			ll w = 0;
			if (dfs(g, i, 1, cnt,w) == true) {
				if (cnt != 1) {
					ans -= 2 * (bi.first * cnt - bi.second);
					ans -= 2 * ((W + B) * cnt - N);
					ans -= cnt * cnt - 1;
					bi.second++;
					bi.first += cnt;
				}
			}
			else {
				if (cnt != 1) {
					ans -= 2 *( bi.first * cnt - bi.second);
					ans -= 2 * ((W * w + B * (cnt - w)) - N);
					ans -= 2 * ((W * (cnt - w) + B * w) - N);
					ans -= w * w + (cnt - w) * (cnt - w) - 1;
					ans -= 2 * w * (cnt - w) - 1;
					N++;
					W += w;
					B += cnt - w;
				}
			}
		}
	}
	cout << ans << endl;

	return 0;
}

