//Union-Find
class UnionFind {
private:
	std::vector<int> parent;
	std::vector<int> height;
	std::vector<int> m_size;

public:
	UnionFind(int size_) : parent(size_), height(size_, 0), m_size(size_, 1) {
		REP(i, size_) {
			parent[i] = i;
		}
	}
	void init(int size_) {
		parent.resize(size_);
		height.resize(size_, 0);
		m_size.resize(size_, 0);
		REP(i, size_) {
			parent[i] = i;
		}
	}
	int find(int x) {
		if (parent[x] == x) {
			return x;
		}
		return parent[x] = find(parent[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		int t = size(x) + size(y);
		m_size[x] = m_size[y] = t;
		if (height[x] < height[y]) parent[x] = y;
		else parent[y] = x;
		if (height[x] == height[y]) ++height[x];
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		if (parent[x] == x) {
			return m_size[x];
		}
		return size(parent[x] = find(parent[x]));
	}
};

signed main() {
	INIT;
	VAR(int, n, m);
	VEC_ROW(int, m, u, v);
	std::vector<std::vector<int>> g(n);
	UnionFind uf(n);
	REP(i, m) {
		--u[i]; --v[i];
		g[u[i]].emplace_back(v[i]);
		g[v[i]].emplace_back(u[i]);
		uf.unite(u[i], v[i]);
	}
	std::set<int> set;
	REP(i, n) set.insert(uf.find(i));
	int a = 0, b = 0, c = 0;
	std::vector<int> col(n, -1);
	for (auto x : set) {
		if (uf.size(x) == 1) ++c;
		else {
			std::queue<int> que;
			que.push(x);
			col[x] = 0;
			bool bi = true;
			while (!que.empty()) {
				int now = que.front(); que.pop();
				for (auto to : g[now]) {
					if (col[to] == -1) {
						col[to] = col[now] ^ 1;
						que.push(to);
					}
					else if (col[to] == col[now]) {
						bi = false;
						break;
					}
				}
				if (!bi) break;
			}
			if (bi) ++a;
			else ++b;
		}
	}
	int ans = (a + b) * (a + b) + a * a + 2 * n * c - c * c;
	OUT(ans)BR;
	return 0;
}

