#pragma region unionfind
class unionfind{
    int *tree;
    size_t length;
public:
    size_t root(size_t v){
        if(tree[v] < 0) return v;
        else return tree[v] = root(tree[v]);
    }
    unionfind(size_t n): length(n){
        tree = new int[n];
        for(size_t i=0;i<n;++i) tree[i] = -1;
    }
    size_t count(size_t v){
        return -tree[root(v)];
    }
    bool is_same(size_t u, size_t v){
        return root(u) == root(v);
    }
    bool merge(size_t u, size_t v){
        u = root(u); v = root(v);
        if(u == v) return false;
        if(u > v) std::swap(u, v);
        tree[u] += tree[v];
        tree[v] = u;
        return true;
    }
};
#pragma endregion

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n, m;
    static vector<int> edges[100000];
    cin >> n >> m;
    unionfind uf{n};
    for(int i=0;i<m;++i){
        int u, v;
        cin >> u >> v;
        --u; --v;
        edges[u].push_back(v);
        edges[v].push_back(u);
        uf.merge(u, v);
    }
    int64_t conn = 0, isol = 0, nodd = 0;
    vector<int> ps;
    for(int i=0;i<n;++i){
        if(uf.root(i) != i) continue;
        if(uf.count(i) == 1) ++isol;
        else{ ++conn; ps.emplace_back(i); }
    }
    int64_t ans = isol * n * 2 - isol * isol;
    static int col[100000];
    nodd = conn;
    for(int p: ps){
        queue<pair<int, int>> q;
        col[p] = 1;
        q.emplace(p, 1);
        while(!q.empty()){
            auto t = q.front();
            q.pop();
            for(int to: edges[t.first]){
                if(col[to] == 0){ col[to] = -t.second; q.emplace(to, -t.second); }
                else if(col[to] == t.second){ --nodd; goto l_nx; }
            }
        }
        l_nx:;
    }
    ans += conn * conn + nodd * nodd;
    cout << ans << endl;

    return 0;
}

