bool looped;
void dfs(vector<vector<ll>> &g, ll v, ll p, vector<bool> &seen, ll &s) {
	s++;
	seen[v] = true;
	for(ll nextv : g[v]){
		if(nextv==p)continue;
		if(seen[nextv]) {looped=true; continue;}
		dfs(g, nextv, v, seen, s);
	}

}

