	rep(i,M){
		ll a,b;
		cin>>a>>b;
		a--;b--;
		g[a].push_back(b);
		g[b].push_back(a);
	}

	ll ans=0;
	vector<bool> seen(N,false);
	ll amari=0;
	ll c=0;
	rep(i,N){
		if(!seen[i]){
			ll s=0;
			looped=false;
			dfs(g,i,-1,seen,s);
			debug(i,s);
			if(s>1){
				c++;
				if(looped) ans++;
				else ans+=2;
			}else{
				amari++;
			}
		}
	}

	debug(ans,amari);
	//(x,?)
	ans+=amari*(N*2-1);

	ans+=c*(c-1);
	p(ans);
}

