using i64=int64_t;

class union_find{
	private:
	vector<int> parent,rank,gs;
    int size;
	public:
    int count_group;
    union_find()=default;
    union_find(int n){ init(n); }
    void init(int n){
		size=n;
		count_group=n;
		parent.resize(size);
		rank.assign(size,0);
        gs.assign(size,1);
		for(int i=0; i<size; ++i) parent[i]=i;
	}
	int find(int x){
		if(parent[x]==x) return x;
		else return parent[x]=find(parent[x]);
	}
	void unite(int x,int y){
		x=find(x);
		y=find(y);
		if(x==y) return;
		if(rank[x]<rank[y]){
			parent[x]=y;
            gs[y]+=gs[x];
		} else {
			parent[y]=x;
            gs[x]+=gs[y];
			if(rank[x]==rank[y]) ++rank[x];
		}
		--count_group;
	}
	bool is_same_group(int x,int y){
		return find(x)==find(y);
	}
    int group_size(int x){
        return gs[find(x)];
    };
};

void solve(){
    i64 n,m;
    cin >> n >> m;
    union_find uf(n);
    vector<vector<int>> graph(n);
    vector<int> color(n);
    rep(i,0,m){
        int a,b;
        cin >> a >> b;
        --a;
        --b;
        uf.unite(a,b);
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    function<bool(int ,int )> dfs=[&](int v,int c){
        color[v]=c;
        rep(i,0,graph[v].size()){
            if(color[graph[v][i]]==c) return false;
            if(color[graph[v][i]]==0 and !dfs(graph[v][i],-c)) return false;
        }
        return true;
    };

    i64 s1=0,s2=0,t=0;
    rep(i,0,n){
        if(color[i]!=0) continue;
        int x=uf.find(i);
        if(uf.group_size(x)==1){
            ++t;
            continue;
        }
        if(dfs(i,1)) ++s1;
