VV<ll> edges;

pair<ll, bool> dfs(ll now, V<ll> &depth, ll d) {
    PLL ret(1, true);
    depth[now] = d;
    for(ll nxt : edges[now]) {
        if(depth[nxt] != -1) {
            ll d1 = depth[nxt];
            ll d2 = depth[now];
            if((d1 % 2) == (d2 % 2)) ret.second = false;
        } else {
            auto tmp = dfs(nxt, depth, d + 1);
            ll t1;
            bool t2;
            tie(t1, t2) = tmp;
            ret.first += t1;
            ret.second &= t2;
        }
    }
    return ret;
}

