            visited[t] = c, cnt++;
            for (int n : G[t]) {
                if (visited[n] == 0) S.emplace(n, 3-c);
                if (visited[n] == c) able = false;
            }
        }
        if (cnt) A.emplace_back(cnt, able);
    }
    Int single = 0, able = 0, unable = 0;
    for (auto& a : A) {
        if (a.first == 1) single++;
        else if (a.second) able++;
        else unable++;
    }
    Int ans = 0;
    ans += single * single + single * (N - single) * 2;
    ans += able * able * 2;
    ans += able * unable;
    ans += unable * able;
    ans += unable * unable;
    cout << ans << endl;
    return 0;
}

