pair<ll, ll> get(ll u, ll v) {
	if (dsu[u][v] == make_pair(u, v)) return { u, v };
	else return dsu[u][v] = get(dsu[u][v].first, dsu[u][v].second);
}

void uni(pair<ll, ll> u, pair<ll, ll> v) {
	u = get(u.first, u.second);
	v = get(v.first, v.second);
	if (u != v) {
		dsu[u.first][u.second] = v;
	}
}

