ll cur = 0;
bool fl = false;
vector<bool> used;
vector<ll> col;

void dfs(int v) {
	used[v] = 1;

	cur++;
	for (auto to : gr[v]) {
		if (!used[to]) {
			col[to] = !col[v];
			dfs(to);
		}
		else if (col[to] == col[v]) fl = true;
	}
}
ll sol() {
	used.clear();
	used.resize(n);
	col.clear();
	col.resize(n);

	ll ans = 0, t = 0, t2 = 0, ns = 0, vis = 0;
	for (int i = 0; i < n; i++) {
		if (!used[i]) {
			fl = false;
			cur = 0;
			dfs(i);
			if (cur == 1) {
				ans += vis * 2 + 1;
				ns++;
			}
			else {
				ll vl = 0;
				if (fl) {
					vl += 2 * t;
				}
				else {
					vl += (4 * t2) + (t - t2) * 2 + ns * 2 * cur;
				}
				ans += vl + (1 + !fl);

				t += 1;
				if (!fl) t2++;
			}
			vis += cur;
		}
	}

	return ans;
}

