const ll INF = static_cast<ll>(1e9) + 7;
const int MAXN = static_cast<int>(1e6) + 17;

int n, m;
vector<int> g[MAXN], g1[MAXN];
bool used[MAXN];
int col[MAXN];

bool read() {
    if (!(cin >> n >> m))
        return false;

    forn (i, m) {
        int u, v;
        cin >> u >> v;
        g[u - 1].push_back(v - 1);
        g[v - 1].push_back(u - 1);
        g1[v - 1].push_back(n + u - 1);
        g1[n + u - 1].push_back(v - 1);
        g1[u - 1].push_back(n + v - 1);
        g1[n + v - 1].push_back(u - 1);
    }

    return true;
}

int dfs(int v) {
    int res = 1;
    used[v] = true;

    for (auto to : g[v])
        if (!used[to])
            res += dfs(to);

    return res;
}

int dfs1(int v) {
    int res = 1;
    used[v] = true;

    for (auto to : g1[v])
        if (!used[to])
            res += dfs1(to);

    return res;
}

bool bip(int v, int cur) {
    col[v] = cur;

    for (auto to : g[v])
        if (col[to] == 0) {
            if (!bip(to, -cur))
                return false;
        } else {
            if (col[to] == col[v])
                return false;
        }

    return true;
}

void solve() {
    fill(used, used + 2 * n, false);
    int kek, kok, lol;
    kek = kok = lol = 0;

    forn (i, n)
        if (!used[i]) {
            if (used[n + i])
                --lol;

            auto cur = dfs1(i);

            if (cur == 1)
                ++kok;
            else
                ++lol, ++kek;
        }

    ll ans = n * n;
    fill(used, used + n, false);

    forn (i, n)
        if (!used[i]) {
            auto cur = dfs(i);

            if (cur == 1)
                continue;

            ans -= 1ll * cur * n;

            if (bip(i, 1)) {
                ans += 1ll * cur * kok + kek;
            } else {
                ans += 1ll * cur * kok + lol;
            }
        }

    cout << ans << endl;
}

int main() {
    cin.tie(nullptr);
    std::ios_base::sync_with_stdio(false);
    std::mt19937 rand('S' + 'E' + 'R' + 'E' + 'Z' + 'H' + 'K' + 'A');

    while (read())
        solve();

    return 0;
}

