class UnionFind {
public:
	vector<int> s, p, es;
	map<int, int>sizemp;

	UnionFind() {}
	UnionFind(int size) {
		s.resize(size, 0);
		p.resize(size, 0);
		es.resize(size, 0);
		sizemp[1] = size;
		rep(i, 0, size)makeSet(i);
	}

	void makeSet(int x) {
		p[x] = x;
		s[x] = 1;
		es[x] = 0;
	}

	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}

	void unite(int x, int y) {
		x = findSet(x);
		y = findSet(y);
		es[x]++;
		if (x == y)return;
		if (s[x] < s[y])swap(x, y);
		int szx = size(x);
		int szy = size(y);
		sizemp[szx]--;
		sizemp[szy]--;
		sizemp[szx + szy]++;
		if (sizemp[szx] == 0)sizemp.erase(szx);
		if (sizemp[szy] == 0)sizemp.erase(szy);
		p[y] = x;
		s[x] += s[y];
		es[x] += es[y];
	}


	int findSet(int x) {
		if (x == p[x]) {
			return x;
		}
		else {
			return p[x] = findSet(p[x]);
		}
	}

	int size(int x) {
		return s[findSet(x)];
	}
	int esize(int x) {
		return es[findSet(x)];
	}
	int minsz() {
		auto beg = sizemp.begin();
		return beg->first;
	}
};

vector<int>E[101010];
int col[101010];
int dfs(int now){
	fore(x, E[now]) {
		if (col[x] == -1) {
			col[x] = 1 - col[now];
			int fl = dfs(x);
			if (fl == 0)return 0;
		}
		if (col[x] == col[now])return 0;
	}
	return 1;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int N, M;
	cin >> N >> M;
	UnionFind un = UnionFind(N);
	for (int i = 0; i < M; i++) {
		int u, v;
		cin >> u >> v;
		u--, v--;
		un.unite(u, v);
		E[u].pb(v);
		E[v].pb(u);
	}

	for (int i = 0; i < N; i++)col[i] = -1;

	ll ans = N * N;
	ll all = N;
	ll bigraph = 0;
	ll other = 0;
	for (int i = 0; i < N; i++) {
		if (un.size(i) == 1) { all--; continue; }
		if (col[i] != -1)continue;
		col[i] = 0;
		int fl = dfs(i);
		if (fl)bigraph++;
		else other++;
	}
	ans -= all * all;
	ans += (bigraph + other)*(bigraph + other) + bigraph*bigraph;
	puts(ans);


	return 0;
}

