class UnionFind {
    using vec = vector<ll>;
    public:
        vec rank;
        vec parent;
        V<bool> is_tree;
        V<ll> ssize;

        UnionFind(ll N) {
            rank = vec(N, 0);
            parent = vec(N);
            iota(parent.begin(), parent.end(), 0ll);
            is_tree = V<bool>(N, true);
            ssize = V<ll>(N, 1);
        }

        ~UnionFind() {
        }

        ll find(ll child) {
            return (child == parent[child] ? child : parent[child] = find(parent[child]));
        }

        void unit(ll x, ll y) {
            ll px = find(x);
            ll py = find(y);
            if(px == py) {
                is_tree[px] = false;
                return;
            }
            if(rank[px] < rank[py]) {
                swap(px, py);
            }
            parent[py] = px;
            is_tree[px] = is_tree[px] | is_tree[py];
            ssize[px] += ssize[py];
            rank[px] += (rank[px] == rank[py]);
        }

        bool same(ll x, ll y) {
            return (find(x) == find(y));
        }

        ll size(ll i) { return ssize[find(i)]; }
        bool tree(ll i) { return is_tree[find(i)]; }

};

int main() {
    ll N, M;
    cin >> N >> M;

    UnionFind uf(N);
    for(ll i = 0; i < M; i++) {
        ll a, b;
