    }

    V<pair<ll, bool>> subg;
    ll tcnt = 0, lcnt = 0, ocnt = 0;
    for(ll i = 0; i < N; i++) {
        if(uf.find(i) != i) continue;
        bool tree = uf.tree(i);
        ll s = uf.size(i);
        if(s == 1) {
            ocnt++;
        } else {
            subg.emplace_back(s, tree);
            (tree ? tcnt : lcnt)++;
        }
    }

    ll ans = 0;
    for(const auto &ele : subg) {
        ll n;
        bool t;
        tie(n, t) = ele;
        ans += tcnt + lcnt;
        ans += (ll)(t) * tcnt;
        ans += n * ocnt;
    }

    DEBUG(ans);

