bool mat[105][105];
pii dad[105][105];
int rnk[105][105];

pii find(pii p) {
	return dad[p.first][p.second] == p ? p : dad[p.first][p.second] = find(dad[p.first][p.second]);
}

void join(pii x, pii y) {
	x = find(x);
	y = find(y);
	if (x == y)
		return;
	if (rnk[x.first][x.second] > rnk[y.first][y.second])
		swap(x, y);
	dad[x.first][x.second] = y;
	rnk[y.first][y.second] += rnk[x.first][x.second] == rnk[y.first][y.second];
}

ll brute() {
	for (int i = 1; i <= N; i++)
		for (auto it : E[i])
			mat[i][it] = true;

	for (int i = 1; i <= N; i++)
		for (int j = 1; j <= N; j++)
			dad[i][j] = {i, j};

	for (int i = 1; i <= N; i++)
		for (int j = 1; j <= N; j++)
			for (int k = 1; k <= N; k++)
				for (int l = 1; l <= N; l++)
					if (mat[i][k] && mat[j][l])
						join({i, j}, {k, l});

	ll sol = 0;
	for (int i = 1; i <= N; i++)
		for (int j = 1; j <= N; j++)
			sol += find({i, j}) == pii(i, j);

	return sol;
}

