// ここまでテンプレート


VV G; // グラフ
V cl; // 頂点の色分け (二部グラフ判定に使う)

// 二部グラフ判定 (true なら二部グラフ)
bool dfs(int u, int x = 0) {
  if (cl[u] == x) return true;      // 頂点 u を訪問済みかつ，今の色が前回訪問時につけた色と同じならば，true
  if (cl[u] == (x^1)) return false; // 頂点 u を訪問済みかつ，今の色が前回訪問時につけた色と異なるならば，false
  cl[u] = x; //  頂点 u に初めて色をつける

  for (auto v : G[u]) {
    // 頂点 u に隣接する各頂点 v を訪問する．色は切り替える
    if (!dfs(v, x^1)) return false;
  }

  // 全ての頂点に矛盾なく色がつけられたら，true
  return true;
}


int main() {
  ll n, m; cin >> n >> m;

  G.assign(n, V());
  cl.assign(n, -1); // 全頂点の色を -1 で初期化

  // グラフの入力
  rep(i, m) {
    int u, v; cin >> u >> v;
    --u; --v;
    G[u].push_back(v);
    G[v].push_back(u);
  }

  Vll cnt(3);
  // cnt[0]: 孤立点でなく，二部グラフでない連結成分の数
  // cnt[1]: 孤立点でなく，二部グラフである連結成分の数
  // cnt[2]: 孤立点の数

  rep(i, n) {
    if (cl[i] != -1) continue; // 既に探索済みの連結成分は無視
    if (sz(G[i]) == 0) { // 頂点 i が孤立点の場合，特別扱い
      ++cnt[2];
      continue;
    }
    int p = dfs(i);
    // p == 0: 頂点 i を含む連結成分は二部グラフでない
    // p == 1: 頂点 i を含む連結成分は二部グラフ
    ++cnt[p];
  }

  ll ans = 0;

  // 連結成分の組を選ぶ．選び方のパターンについて，3通りの場合分けをする
  ans += n*n - (n-cnt[2]) * (n-cnt[2]);     // 少なくとも一方が孤立点であるようなパターン
  ans += (cnt[0]+cnt[1]) * (cnt[0]+cnt[1]); // 両方とも孤立点でない各パターンについて，まず 1 を足す
  ans += cnt[1] * cnt[1];                   // 両方とも「孤立点ではない二部グラフ」の各パターンについて，さらに 1 を足す

  // 答えの出力
  cout << ans << '\n';
  return 0;
}

