const int MAX_N = 100005;

vector<int> G[MAX_N];
int used[MAX_N];

bool dfs(int u, int cri, ll& sz){
    bool nbi = false;
    used[u] = cri;
    sz++;
    each(v, G[u]){
        if(used[v] == 0){
            nbi |= dfs(v, 3-cri, sz);
        }else if(used[v] == cri){
            nbi = true;
        }
    }
    return nbi;
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    rep(i,m){
        int a, b;
        cin >> a >> b;
        --a, --b;
        G[a].pb(b), G[b].pb(a);
    }
    ll bi = 0, al = 0;
    vector<pll> vec;
    rep(i,n){
        if(!used[i]){
            ll sz = 0;
            if(dfs(i, 1, sz)){
                vec.pb(pll(sz, 0));
            }else{
                if(sz == 1) continue;
                vec.pb(pll(sz, 1));
                bi++;
            }
            al += sz;
        }
    }
    ll ans = (ll)n*n;
    rep(i,len(vec)){
        ans -= vec[i].fi*al-len(vec);
        if(vec[i].se){
            ans += bi;
        }
    }
    cout << ans << "\n";
    return 0;
}

