const int N = 1e5 + 7;

int n, m;
vector<int> adj[N];
long long ans;
bool odd;
int color[N], visit[N], cnt = 0;

void dfs(int u, int c) {
	++cnt;
	color[u] = c;
	visit[u] = true;
	for (auto v : adj[u]) {
		if (!visit[v]) {
			dfs(v, c ^ 1);
		} else {
			if (color[v] == color[u]) {
				odd = true;
			}
		}
	}
}

int main() {
	scanf("%d %d", &n, &m);
	for (int i = 0; i < m; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
		adj[u].push_back(v);
		adj[v].push_back(u);
	}
	vector<pair<int, int>> vec;
	for (int i = 1; i <= n; i++) {
		if (!visit[i]) {
			odd = false;
			cnt = 0;
			dfs(i, 0);
			vec.push_back({cnt, odd});
		}
	}
	ans = 0;
	long long c1 = 0, evencnt = 0, oddcnt = 0;
	for (auto v : vec) {
		if (v.first == 1) {
			++c1;
			continue;
		}
		if (v.second) {
			ans ++;
			oddcnt++;
		} else {
			ans += 2;
			evencnt ++;
		}
	}
	ans += 1LL * c1 * c1 + 2LL * c1 * (n - c1);
	ans += 1LL * oddcnt * (oddcnt - 1);
	ans += 4LL * evencnt * (evencnt - 1);
	ans += 2LL * evencnt * oddcnt;
	cout << ans << endl;
	return 0;
}

