V<ll> path[100010];
ll d[100010];

// evenならtrue
bool dfs(ll v, ll t) {
    if (d[v] >= 0) {
        return t != d[v];
    }

    d[v] = t;
    bool ret = false;
    for (ll sv : path[v]) {
        ret |= dfs(sv, 1 - t);
    }

    return ret;
}

void solve() {
    ll N, M;
    cin >> N >> M;

    FOR(i, 0, M) {
        ll a, b;
        cin >> a >> b;
        --a;
        --b;
        path[a].push_back(b);
        path[b].push_back(a);
    }

    fill(d, d + N, -1);

    ll odd = 0, even = 0, one = 0;

    FOR(v, 0, N) {
        if (d[v] >= 0) continue;
        if (path[v].empty()) {
            ++one;
            continue;
        }

        if (dfs(v, 0)) {
            ++even;
        } else {
            ++odd;
        }
    }

    // cout << odd << ":" << even << ":" << one << endl;

    cout << sq(N) - sq(N - one) + sq(odd + even) + sq(odd) << endl;
    return;
}


