  rep(i,m) u[i]--,v[i]--;
  rep(i,m) uf.unite(u[i]+n, v[i]), uf.unite(u[i], v[i]+n);

  long alone=0;
  long bad=0;
  long good=0;
  rep(i,n) if(uf.par[i]<0){ // for root
    if(uf.size(i)==1) alone++;
    else if(! uf.same(i, i+n)) good++;
    else bad++;
  }
//  dbg(alone),dbg(good),dbg(bad);

  long ans = alone*n*2L - alone*alone;
  ans += 2L*good*good;
  ans += bad*bad;
  ans += 2L*good*bad;

  cout << ans << endl;

  return 0;
}

