ll dfs(int cur,int info){
	if(number[cur]!=0){
		if(info!=number[cur])	flag=true;
		return 0;
	}
	number[cur]=info;
	ll ret=1;
	for(int i=0;i<edge[cur].size();i++){
		ret+=dfs(edge[cur][i],info^3);
	}
	return ret;
}

