    for(long i = 1; i <= n; ++i) {
      long t = dfs(i);
      if( t == 1 ) continue;
      vs.push_back(t);
    }
    long res = n * n;
    long sum = std::accumulate(vs.begin(), vs.end(), (long)0);
    dumpl((long)vs.size());
    dumpl(sum);
    res -= sum * sum;
    if( (long)vs.size() != 1 ) res += (long)vs.size() * (long)vs.size();
    for(int i = 0; i < (int)vs.size(); ++i) {
      if( vs[i] == 2 ) res += 1;
