    Node(){
        this->v = 0;
        this->p = -1;
    }
};

int main(){
    LL N, M;
    cin >> N >> M;
    vector<int> V;
    vector<vector<int> > G(N, vector<int>());
    REP(i, M){
        int u, v;
        cin >> u >> v;
        u--,v--;
        V.push_back(u);
        V.push_back(v);
        G[u].push_back(v);
        G[v].push_back(u);
    }
    LL res = N*N;

    sort(ALL(V));
    V.erase(unique(ALL(V)), V.end());

    res -= ((LL)V.size()) * ((LL)V.size());

    LL cycle = 0;
    LL tree = 0;
    vector<int> used(N);
    REP(i, N){
        if(G[i].size()==0)continue;
        if(used[i])continue;
        stack<Node> st;
        st.push(Node(i, -1));
        bool is_cycle = false;
        while(!st.empty()){
            Node n = st.top();st.pop();
            if(used[n.v]){
                is_cycle = true;
                break;
            }
            used[n.v] = true;
            REP(i, G[n.v].size()){
                if(G[n.v][i]==n.p)continue;
                st.push(Node(G[n.v][i], n.v));
            }
        }
        if(is_cycle)cycle++;
        else tree++;
    }

    res += 2LL * tree * tree;
    res += 1LL * (cycle * cycle + 2LL * cycle * tree);
    //cerr << tree << " " << cycle << endl;

    cout << res << endl;

    return 0;
}

