		u[i]--;
		v[i]--;
		uf.Union(u[i], v[i]);
		G[u[i]].push_back(v[i]);
		G[v[i]].push_back(u[i]);
	}

	int cnt1 = 0, cnt2 = n;
	for (int i = 0; i < n; i++) {
		if (uf.Find(i) == i) {
			if (uf.size(i) > 1) cnt1++;
			else cnt2--;
		}
	}

	int cnt3 = cnt1;
	for (int i = 0; i < n; i++) {
		if (uf.Find(i) != i) continue;
		vector<bool> used(n, false);
		cnt3 -= dfs(i, -1, 0, used);
	}

	cout << (ll)n * n - (ll)cnt2 * cnt2 + (ll)cnt1 * cnt1 + (ll)cnt3 * cnt3 << endl;
