class UF {
public:
	int par[100000];
	UF() { for (int i = 0; i < 100000; i++) par[i] = i; }
	int root(int x) { if (x == par[x]) return x; return (par[x] = root(par[x])); }
	void marge(int x, int y) {
		x = root(x);
		y = root(y);
		par[x] = y;
	}
	bool is_same(int x, int y) {
		return root(x) == root(y);
	}
}uf;

int n, m;
vector<int> et[100000];
vector<int> vs[100000];

signed main() {
	int i;

	cin >> n >> m;
	for (i = 0; i < m; i++) {
		int u, v;
		cin >> u >> v;
		u--; v--;
		et[u].push_back(v);
		et[v].push_back(u);
		uf.marge(u, v);
	}

	for (i = 0; i < n; i++) {
		vs[uf.root(i)].push_back(i);
	}

	int x = 0;
	int y = 0;

	for (i = 0; i < n; i++) {
		if (vs[i].size() <= 1) { continue; }

		int esum = 0;
		for (int j = 0; j < vs[i].size(); j++) {
			esum += et[vs[i][j]].size();
		}

		int kakutyo;
		if (esum / 2 >= vs[i].size()) {
			kakutyo = 2;
		}
		else {
			kakutyo = 1;
		}

		x += (int)vs[i].size() * (int)vs[i].size() - (int)kakutyo;
		y++;
	}

	cout << n * n - (x + (y - 1)) << endl;
	return 0;
}

