  }

  for (int i = 1, u, v; i <= M; ++i) {
    scanf("%d%d", &u, &v);
    merge2(u, v);
    if (u == v || find(u, fa2) == find(v, fa2) || find(u + N, fa2) == find(v + N, fa2)) {
      ok[find(u, fa1)] = 0;
    } else {
      merge1(u, v + N);
      merge1(u + N, v);
    }
  }

