  vector<int> u(m),v(m);
  rep(i,m) cin>>u[i]>>v[i];

  UnionFind uf(n);
  rep(i,m) uf.unite(--u[i], --v[i]);
  vector<int> cnt(n,0);
  rep(i,m) cnt[uf.find(u[i])]++;
