struct UnionFind {
    vector<int> rank, parent, size;

    // +1 for 1-indexed nodes
    UnionFind(int n) : rank(n + 1, 0), parent(n + 1), size(n + 1, 1) {
        iota(parent.begin(), parent.end(), 0); // parent is itself
    }
    int root(int x) {
        if (x != parent[x]) {
            parent[x] = root(parent[x]);
        }
        return parent[x];
    }
    bool isSame(int x, int y) { return root(x) == root(y); }
    bool unite(int x, int y) { return link(root(x), root(y)); }
    bool link(int x, int y) {
        if (x == y)
            return false;
        if (rank[x] > rank[y]) {
            parent[y] = x;
            size[x] += size[y];
        } else {
            parent[x] = y;
            size[y] += size[x];
            if (rank[x] == rank[y]) {
                rank[y]++;
            }
        }
        return true;
    }
    int getSize(int x) { return size[root(x)]; }
};

int main() {
    int n, m;
    cin >> n >> m;
    vector<pii> edges;
    UnionFind uf(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        edges.emplace_back(a, b);
        uf.unite(a, b);
    }
    vector<int> ne(100001, 0);
    for (int i = 0; i < m; ++i) {
        ne[uf.root(edges[i].first)]++;
    }
    vector<bool> used(100001, false);
    ll twoes  = 0;
    ll num    = 0;
    ll single = n;
    for (int i = 0; i < n; ++i) {
        int r = uf.root(i);
        if (used[r])
            continue;
        int s   = uf.getSize(r);
        used[r] = true;
        if (s != 1) {
            num++;
            single -= s;
            if ((s % 2 == 0 || s == 3) && s - 1 == ne[r]) {
                twoes++;
            }
        }
    }
    ll ret = num * num;
    ret += twoes * twoes;
    ret += 2 * n * single - single * single;
    cout << ret << "\n";
    return 0;
}

