int dfs1(int u) {
  color[u] = -1;
  int sz = 1;
  for (int i = 0; i < (int)g[u].size(); ++i) {
    int v = g[u][i];
    if (!color[v]) {
      sz += dfs1(v);
    }
  }
  return sz;
}

bool dfs2(int u) {
  for (int i = 0; i < (int)g[u].size(); ++i) {
    int v = g[u][i];
    if (color[v] == -1) {
      color[v] = 3 - color[u];
      if (!dfs2(v)) {
        return false;
      }
    } else if (color[v] == color[u]) {
      return false;
    }
  }
  return true;
}

int main(void) {
  scanf("%d%d", &n, &m);
  for (int i = 0; i < m; ++i) {
