    scanf("%d%d", &u, &v);
    --u; --v;
    g[u].push_back(v);
    g[v].push_back(u);
  }
  ll ans = 0;
  ll bi = 0, nbi = 0, one = 0;
  for (int i = 0; i < n; ++i) {
    if (!color[i]) {
      int sz = dfs1(i);
      color[i] = 1;
      if (sz == 1) {
        ++one;
        ans += 1;
      } else if (dfs2(i)) {
        ++bi;
        ans += 2;
      } else {
        ++nbi;
        ans += 1;
      }
    }
  }
  ans = one * (n - one) * 2 + one * one + bi * bi * 2 + nbi * bi * 2 + nbi * nbi;
  printf("%lld\n", ans);
