bool vis[MAXN];
int c[MAXN];
vector <int> q[2];

void dfs(int i) {
    if (vis[i])
        return;
    vis[i] = true;
    for (int j : adj[i])
        dfs(j);
}

int is_bipartite(int i) {
    q[0].clear();
    q[1].clear();

    q[0].push_back(i);
    int cur = 0;
    int cnt = 0;
    while (q[cur].size() > 0) {
        for (int u : q[cur]) {
            c[u] = cur;
            cnt++;
            for (int v : adj[u]) {
                if (c[v] == c[u])
                    return 0;
                if (c[v] == -1)
                    q[cur ^ 1].push_back(v);
            }
        }
        q[cur].clear();
        cur ^= 1;
    }
    return cnt;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
