        adj[v].push_back(u);
    }

    for (int i = 0; i < n; i++)
        c[i] = -1;

    int64_t acnt = 0, bcnt = 0, scnt = 0;
    for (int i = 0; i < n; i++) {
        if (!vis[i]) {
            dfs(i);
            int cnt = is_bipartite(i);
