const int N = 100000;

vector<int> G[N];
int color[N];

int go(int x, int c)
{
	int res = 0;
	color[x] = c;
	for (int i = 0; i < G[x].size(); ++i)
	{
		int to = G[x][i];
		if (color[to] == -1)
			res |= go(to, c ^ 1);
		if (color[to] == color[x])
			res = 1;
	}
	return res;
}

int main()
{
	int n, m;
	cin >> n >> m;
	for (int i = 0; i < m; ++i)
	{
