		u--, v--;
		G[u].push_back(v);
		G[v].push_back(u);
	}

	fill(color, color + n, -1);

	int even = 0;
	int odd = 0;
	int alone = 0;
	for (int i = 0; i < n; ++i)
	{
		if (color[i] != -1)
			continue;
		if (go(i, 0))
			odd++;
		else
		{
			if (G[i].size() == 0)
				alone++;
			else
				even++;
		}
	}
	LL res = (LL)alone * alone + (LL)2 * alone * (n - alone);
	res += 2 * even + odd;
	res += (LL)even * (even - 1);
	res += (LL)even * odd;
	res += (LL)odd * odd;
	cout << res << endl;
	return 0;
}

