class DisjointUnionSets {
private:
  std::vector<int> parent;
  std::vector<int> rank;
  int num;
public:
  DisjointUnionSets(unsigned int n) {
    num = n;
    parent = std::vector<int>(n);
    for (unsigned int i = 0; i < n; ++i) {
      parent[i] = i;
    }
    rank = std::vector<int>(n);
  }

  int find(int i) {
    int res;
    if (parent[i] == i) {
      res = i;
    } else {
      res = find(parent[i]);
      parent[i] = res;
    }
    return res;
  }

  void unite(int i, int j) {
    int irep, jrep, irank, jrank;
    irep = find(i);
    jrep = find(j);
    if (jrep != irep) {
      --num;
      irank = rank[irep];
      jrank = rank[jrep];
      if (irank < jrank) {
        parent[irep] = jrep;
      } else {
        parent[jrep] = irep;
        if (irank == jrank) {
          ++rank[irep];
        }
      }
    }
  }

  int size() const{
    return num;
  }
};


