bool isBipartiteGraph(vector<vector<ll>> &g, ll v, vector<ll> &seen) {
	auto dfs = [](auto&& dfs, vector<vector<ll>> &g, ll v, vector<ll> &seen) -> bool {
		for(ll nextv:g[v]){
			if(seen[nextv]){
				if(seen[nextv]==seen[v])return false;
				else continue;
			}
			seen[nextv]=-1*seen[v];
			bool b=dfs(dfs, g, nextv, seen);
			if(!b)return false;
		}
		return true;
	};
	seen[v]=1;
	return dfs(dfs, g, v, seen);
}
