    REP(i, n) if(Should[i] == -1){
        Should[i] = 0;
        if(Edge[i].size() != 0){
            bool freeChange = false;
            int cnt = 0;
            std::queue<int> nxt; nxt.push(i);
            while(not nxt.empty()){
                int k = nxt.front(); nxt.pop();
                vREP(ele, Edge[k]){
                    // まだ訪れていない
                    if(Should[ele] == -1){
                        Should[ele] = 1 - Should[k];
                        nxt.push(ele);
                    }
                    // 訪れたが, 偶奇を好きに切り替えられる場合
                    else if(Should[ele] == Should[k]) freeChange = true;
                }
                cnt++;
            }
            tops++; if(not freeChange) odd_even_Bob++;
            nonSoles += cnt;
        }
    }
    lli T = tops; T *= tops;
    lli OE = odd_even_Bob; OE *= odd_even_Bob;
    lli NS = nonSoles; NS *= nonSoles;
    lli res = n; res *= n; res -= NS; res += T; res += OE;
    printf("%lld\n", res);
    return 0;
}

