void make_edgelist(const V<t2> &srclist, V<ll> edgelist[])
{
    for (auto src : srclist) {
        ll a = get<0>(src);
        ll b = get<1>(src);
        edgelist[a].pb(b);
        edgelist[b].pb(a);
    }
}

ll groups[100005];

bool judge(const V<ll> edgelist[], ll root)
{
    queue<ll> q;
    q.push(root);
    groups[root] = 1;

    while (q.size()) {
        ll v = q.front(); q.pop();
        ll ng = (groups[v] & 1LL) + 1LL;
        for (auto nv : edgelist[v]) {
            if (groups[nv]) {
                if (ng != groups[nv]) return true;
            }
            else {
                q.push(nv);
                groups[nv] = ng;
            }
        }
    }

    return false;
}

void _main()
{
    ll n; llin(n);
    ll m; llin(m);
    S V<t2> uvlist; llinl2(uvlist, m);

    S UnionFind uf(n+1);

    for (auto uv : uvlist) {
        ll u = get<0>(uv);
        ll v = get<1>(uv);
        uf.unite(u, v);
    }

    set<ll> roots;
    srep (v, 1, n+1) roots.insert(uf.root(v));

    S V<ll> edgelist[100005];
    make_edgelist(uvlist, edgelist);

    ll cnts_one = 0;
    ll cnts_normal = 0;
    ll cnts_bin = 0;
    memset(groups, 0, sizeof(groups));

    ll vcnts[100005] = {};
    srep (v, 1, n+1) vcnts[uf.root(v)]++;

    for (auto root : roots) {
        if (vcnts[root] == 1) cnts_one++;
        else if (judge(edgelist, root)) cnts_normal++;
        else cnts_bin++;
    }

    debug_printf("cnts_one=%lld\n", cnts_one);
    debug_printf("cnts_normal=%lld\n", cnts_normal);
    debug_printf("cnts_bin=%lld\n", cnts_bin);

    ll ans = 0;

    ans += cnts_one * cnts_one;
    ans += cnts_one * (n - cnts_one);
    ans += (n - cnts_one) * cnts_one;

