using namespace std;

int main() {
	int n, m;
	cin >> n >> m;
	vector<vector<int>> g(n);
	long long iso = 0;
	for (int i = 0; i < m; i++) {
		int u, v;
		scanf("%d %d", &u, &v);
		u--;
		v--;
		g[u].push_back(v);
		g[v].push_back(u);
	}
	for (int i = 0; i < n; i++) {
		if (g[i].size() == 0) {
			iso++;
		}
	}
	vector<int> root(n, -1);
	function<void(int, int)> dfs = [&](int u, int r) {
		if (root[u] != -1) {
			return 0;
		}
		root[u] = r;
		for (int v : g[u]) {
			 dfs(v, r);
		}
	};
	long long ans = 0;
	for (int i = 0; i < n; i++) {
		if (g[i].size() == 0) {
			continue;
		}
		if (root[i] != -1) {
			continue;
		}
		dfs(i, i);
		ans++;
	}
	ans *= ans;
	ans += iso * n * 2 - iso * iso;
	vector<int> color(n, -1);
	function<bool(int)> dfs2 = [&](int u) {
		for (int v : g[u]) {
			if (color[v] != -1) {
				if (color[v] != (color[u] ^ 1)) {
					return false;
				}
			} else {
				color[v] = color[u] ^ 1;
				if (!dfs2(v)) {
					return false;
				}
			}
		}
		return true;
	};
	long long b = 0;
	for (int i = 0; i < n; i++) {
		if (root[i] == i) {
			color[i] = 0;
			if (dfs2(i)) {
				ans++;
				b++;
			}
		}
	}
	ans += b * b;

	cout << ans - 1 << endl;
}

#include<bits/stdc++.h>
#define MAXN 1000000+10 
using namespace std;
int n,m,I,P,Q;
int cnt,head[MAXN],to[MAXN],nxt[MAXN],linker[MAXN];
bool f,vis[MAXN];
void add(int x,int y){
	cnt++;
	to[cnt]=y;
	nxt[cnt]=head[x];
	head[x]=cnt;
}
void dfs(int x,int fa){
	vis[x]=true;
	linker[x]=linker[fa]^1;
	for(int i=head[x];i;i=nxt[i]){
		int y=to[i];
		if(y!=fa){
			if(vis[y])
				if(linker[x]==linker[y])f=true;
			else dfs(y,x);
		}
	}
}
int main(){
	scanf("%d%d",&n,&m);
	int x,y;
	for(int i=0;i<m;i++){
		cin>>x>>y;
		add(x,y);
		add(y,x);
	}
	for(int i=1;i<=n;i++)
		if(!vis[i]){
			if(!head[i]){
				I++;
				vis[i]=true;
				continue;
			}
			f=false;
			dfs(i,0);
			if(f)P++;
			else Q++;
		}
	long long ans=2LL*I*n-1LL*I*I+1LL*P*P+2LL*P*Q+2LL*Q*Q;
	printf("%lld\n",ans);
    return 0;
}

