void solve (int n)
{
    vvi g(n);
    int m;
    cin >> m;
    forn (i, m)
    {
        int u, v;
        cin >> u >> v;
        --u, --v;
        g[u].pb(v);
        g[v].pb(u);
    }

    int cnt1 = 0, cntodd = 0, cntev = 0;
    vi color(n, -1);
    forn (i, n) if (color[i] == -1)
    {
        vi comp;
        color[i] = 0;
        dfs(i, g, color, comp);

        if (sz(comp) == 1)
            cnt1++;
        else
        {
            bool ok = true;
            for (int x : comp) for (int dest : g[x])
                ok &= (color[x] != color[dest]);
