void dfs(int v,vector<vector<int>>& edge,vector<int> &visited,vector<int> &c){
  if(visited[v]) return;
  visited[v]=true;
  c.push_back(v);
  for(int j=0;j<edge[v].size();j++){
    dfs(edge[v][j],edge,visited,c);
  }
  return;
}

int main(){
  long long int n;
  long long int m;
  cin>>n>>m;
  vector<vector<int>> edge(n);
  for(int i=0;i<m;i++){
    int u,v;
    cin>>u>>v;
    u--,v--;
    edge[u].push_back(v);
    edge[v].push_back(u);
  }
  vector<int> visited(n,0);
  vector<long long int> circle;
  vector<long long int> tree;
  for(int i=0;i<n;i++){
    if(!visited[i]){
      vector<int> c;
      dfs(i,edge,visited,c);
      if(c.size()==1) continue;
      long long int edgecnt=0;
      for(int j=0;j<c.size();j++){
	edgecnt+=edge[c[j]].size();
      }
      if(edgecnt/2==c.size()-1){
	tree.push_back(c.size());	
      }
      else{
	circle.push_back(c.size());
      }
    }
  }

  long long int trees=accumulate(tree.begin(),tree.end(),0LL);
  trees+=accumulate(circle.begin(),circle.end(),0LL);
  long long int tred=trees*trees;
  for(int i=0;i<tree.size();i++){tred-=tree[i]*tree[i];}
  for(int i=0;i<circle.size();i++){tred-=circle[i]*circle[i];}
  long long int sum=circle.size()+tree.size();
  tred-=sum*(sum-1)-(tree.size())*(tree.size()-1);

  for(int i=0;i<tree.size();i++)tred+=tree[i]*tree[i]-2;

  for(int i=0;i<circle.size();i++) tred+=circle[i]*circle[i]-1;


  return 0;
}

