            if (color[i]) continue;
            if (adjList[i].empty()) {
                color[i] = 1;
                iso++;
                continue;
            }
            if (dfs(i, 1)) {
                bp++;
            } else {
                other++;
            }
        }

        ll res = (2 * (ll)n - 1) * iso;
