void dfs(int par, int curr, int& flag, int cnt[2])
{
    int currval=vis[curr];
    assert(currval == 1 || currval == 2);
    int i;
    for (i = 0; i < (int)g[curr].size(); i++) {
        int next = g[curr][i];
        if (next == par) continue;

        if (vis[next]) {
            if (vis[next] != 3 - currval) {
                flag = 1;
            }
        }
        else {
            vis[next] = 3 - currval;
            cnt[vis[next] - 1]++;
            dfs(curr, next, flag, cnt);
        }
    }   

    return;
}

void solve()
{
    int n,m;
    scanf("%d%d", &n, &m);

    g.resize(n);
    int i;
    for (i = 0; i < m; i++) {
        int a, b;
        scanf("%d%d", &a, &b); a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vis.resize(n);
    vector<ll> v0;
    vector<pair<ll, ll> > v1;
    for (i = 0; i < n; i++) {
        if (!vis[i]) {
            vis[i] = 1;
            int flag = 0;
            int cnt[2] = { 1, 0 };
            dfs(-1, i, flag, cnt);
            if (0) {
                printf("%d cnt(%d,%d)\n", flag, cnt[0], cnt[1]);
            }
            if (flag) {
                v0.push_back((ll)(cnt[0] + cnt[1])*(cnt[0]+cnt[1]));
            }
            else {
                v1.push_back(make_pair((ll)cnt[0]*cnt[0]+(ll)cnt[1]*cnt[1], (ll)2*cnt[0]*cnt[1]));
            }
        }
    }

    ll ans = 0;

    ll sum = 0, sum0 = 0, sum1 = 0, sum02 = 0, sum12 = 0;
    for (i = 0; i < (int)v1.size(); i++) {
        if (v1[i].first && v1[i].second) {
            ll ans0 = v1[i].first - 1 + v1[i].second - 1;
            ans += ans0;
            sum += 2;
            sum0 += v1[i].first;
            sum02 += v1[i].first*v1[i].first;
            sum1 += v1[i].second;
            sum12 += v1[i].second*v1[i].second;
        }
    }

    int siz = (int)v1.size();
    for (i = 0; i < (int)v1.size(); i++) {
        ll ans0 = sum0 * sum0 - sum02;
        ll ans1 = sum1 * sum1 - sum12;
        ll ans2 = sum0 * sum1 * 2;
        ans += ans0 + ans1 + ans2 - (ll)4*siz*(siz-1);
    }

    for (i = 0; i < (int)v0.size(); i++) {
        if (v0[i] > 1) {
            ll ans0 = v0[i] - 1;
            ans += ans0;

            ll ans1 = sum * ans0;
            ans += ans1;
        }
    }
    ans = (ll)n*n - ans;
    printf("%lld\n", ans);

    return;
}


