int solve(int P){
  D[P]=0;
  if(X[P].size()==0) return 0;
  queue<int> Q;
  Q.push(P);
  int F=1;
  while(!Q.empty()){
    int tmp=Q.front();
    Q.pop();
    rep(i,X[tmp].size()){
      if(D[X[tmp][i]]==-1){
        D[X[tmp][i]]=(D[tmp]+1)%2;
        Q.push(X[tmp][i]);
      }else if(X[tmp][i]!=(D[tmp]+1)%2) F=0;
    }
  }
  if(F) return 1;
  return 2;
}

