		long long u, v;
		cin >> u >> v;
		u--;v--;
		tree[u].push_back(v);
		tree[v].push_back(u);
		uf.unite(u, v);
	}

	set<long long> single;
	for(long long i = 0; i < N; i++){
		if(uf.size(i) == 1){
			single.insert(i);
		}
	}

	long long nibunum = 0;
	long long nonnibunum = 0;

	set<long long> done;
	for(long long i = 0; i < N; i++){
		if(single.count(i) != 0){
			continue;
		}
		if(done.count(uf.find(i)) != 0){
			continue;
		}

		done.insert(uf.find(i));
		if(nibu(i) == true){
			nibunum++;
		}else{
			nonnibunum++;
		}
	}
	long long ans = 0;
	//single vs single
	//single vs nibu
	//single vs nonnibu
	ans += single.size() * N;

	//nibu vs single
	//nonnibu vs single
	//single vs single
	ans += N * single.size();

	ans -= single.size();


	//nibu vs nibu
	ans += nibunum * nibunum * 2;
	//nibu vs nonnibu
	ans += nibunum * nonnibunum;
	//nonnibu vs nibu
	ans += nonnibunum * nibunum;
	//nonnibu vs nonnibu
	ans += nonnibunum * nonnibunum;
	cout << ans << endl;
}

