#define N 100010
vi par(N); //親
vi ran(N); //木の深さ
vi num(N); //要素数
vector<bool> graph(N);

		   //n要素で初期化
void init(int n) {
	int i;
	for (i = 0; i < n; i++) {
		par[i] = i;
		ran[i] = 0;
		num[i] = 1;
		graph[i] = false;
	}
}

//木の根を求める
int find(int x) {
	if (par[x] == x) {
		return x;
	}
	else {
		return par[x] = find(par[x]);
	}
}

//xとyの属する集合を併合
void unite(int x, int y) {
	x = find(x);
	y = find(y);
	int numsum = num[x] + num[y];
	bool isgraph = graph[x] | graph[y];
	if (x == y) {
		graph[x] = true;
		return;
	}
	if (ran[x]<ran[y]) {
		par[x] = y;
	}
	else {
		par[y] = x;
		if (ran[x] == ran[y]) {
			ran[x]++;
		}
	}
	num[x] = num[y] = numsum;
	graph[x] = graph[y] = isgraph;
}

//xとyが同じ集合に属するか否か
bool same(int x, int y) {
	return find(x) == find(y);
}

int main() {
	int n, m, i, j;
