	init(n);
	for (i = 0; i < m; i++) {
		int u, v;
		cin >> u >> v;
		u--; v--;
		unite(u, v);
	}

	set<int> root;
	ll graphnum = 0, treenum = 0, singlenum = 0;
	for (i = 0; i < n; i++) {
		int temp = find(i);
		if (!root.count(temp)) {
			if (num[temp] == 1) {
				singlenum++;
			}
			else {
				if (graph[temp]) {
					graphnum++;
				}
				else {
					treenum++;
				}
			}
			root.insert(temp);
		}
	}
	ll ans = 0;
	for (i = 0; i < singlenum; i++) {
		ans += 2 * n - 1 - 2 * i;
	}
	ans += 2 * treenum + graphnum;
	ans += 2 * treenum*(treenum - 1) + 2*treenum*graphnum + graphnum*(graphnum - 1);
	cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
struct node {
	int to, next;
} edge[MAXN*4];
int head[MAXN], top = 0;
auto push = [](int i, int j)
{ edge[++top] = (node) {j, head[i]}, head[i] = top;  };
int n, m, u, v;

int vis[MAXN], siz[MAXN];

bool dfs(int nd)
{ 
	bool ans = true;
	siz[nd] = 1;
	for (int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (vis[to] == -1) vis[to] = vis[nd]^1, ans = (dfs(to)&&ans), siz[nd] += siz[to];
		else if (vis[to] == vis[nd]) ans = false;
	}
	return ans;

}

int main()
{
	ios::sync_with_stdio(false);
	cin >> n >> m;
	fill(vis+1, vis+n+1, -1);
	for (int i = 1; i <= m; i++) {
	        cin >> u >> v;
		push(u, v), push(v, u);
	}
	int odd = 0, even = 0, single = 0;
	long long ans = 0;
	for (int i = 1; i <= n; i++)
		if (vis[i] == -1) {
			vis[i] = 0;
			int ans = dfs(i);
			if (siz[i] == 1) single++;
			else if (ans) even++;
			else odd++;
		}
	ans = 1ll*odd*odd+2ll*odd*even+2ll*even*even+1ll*single*single+2ll*single*(n-single);
	cout << ans << endl;
	return 0;
}

