using namespace std;

struct Node{
    int v, p;
    Node(int v, int p){
        this->v = v;
        this->p = p;
    }
    Node(){
        this->v = 0;
        this->p = -1;
    }
};

int main(){
    LL N, M;
    cin >> N >> M;
    vector<int> V;
    vector<vector<int> > G(N, vector<int>());
    REP(i, M){
        int u, v;
        cin >> u >> v;
        u--,v--;
        V.push_back(u);
        V.push_back(v);
        G[u].push_back(v);
        G[v].push_back(u);
    }
    LL res = N*N;

    sort(ALL(V));
    V.erase(unique(ALL(V)), V.end());

    res -= ((LL)V.size()) * ((LL)V.size());

    LL bipartite = 0;
    LL not_bipartite = 0;
    vector<int> color(N+1, -1);
    color[N] = 0;
    REP(i, N){
        if(G[i].size()==0)continue;
        if(color[i]!=-1)continue;
        stack<Node> st;
        st.push(Node(i, N));
        bool is_bipertite = true;
        while(!st.empty()){
            Node n = st.top();st.pop();
            if(color[n.v]!=-1 && color[n.v]==color[n.p]){
                is_bipertite = false;
                break;
            }
            color[n.v] = 1 - color[n.p];
            REP(i, G[n.v].size()){
                if(color[G[n.v][i]]!=-1)continue;
                st.push(Node(G[n.v][i], n.v));
            }
        }
        if(is_bipertite)bipartite++;
        else not_bipartite++;
    }

    res += 2LL * bipartite * bipartite;
    res += 1LL * (not_bipartite * not_bipartite + 2LL * not_bipartite * bipartite);
    //cerr << tree << " " << cycle << endl;

    cout << res << endl;

    return 0;
}

