int find(int x) {
  if (U[x] == x) return x;
  return U[x] = find(U[x]);
}

void unite(int x, int y) {
  x = find(x), y = find(y);
  if (x == y) return;
  if (R[x] < R[y]) swap(x, y);
  U[y] = x;
  R[x] += R[y];
  R[y] = 0;
}

bool same(int x, int y) {
  return find(x) == find(y);
}

int dfs(int x, int p, int l) {
  if (V[x] != -1) return V[x] ^ l;
  V[x] = l;

  int s = -1;
  for (int t : G[x]) {
    if (t == p) continue;
    s = max(s, dfs(t, x, l^1));
  }
  return s;
}

