{
	if(x==setfa[x])
		return x;
	return setfa[x]=Findfa(setfa[x]);
}
void Union(int x,int y)
{
	int fx=Findfa(x),fy=Findfa(y);
	if(fx==fy)
		return;
	setfa[fx]=fy;
}
void DFS(int u)
{
	for(int i=0;i<(int)G[u].size();i++)
	{
		int v=G[u][i].v;
		if(dist[v]!=0)
		{
			int cirlen=dist[u]-dist[v]+1;
			if(cirlen%2==1)
				setsp[Findfa(u)]=true;
			continue;
		}
		dist[v]=dist[u]+1;
		DFS(v);
	}
}
