	{
		scanf("%d %d",&u,&v);
		G[u].push_back(edge(u,v));
		G[v].push_back(edge(v,u));
		edges.push_back(edge(u,v));
		d[u]++,d[v]++;
		Union(u,v);
	}
	for(int i=1;i<=n;i++)
		if(dist[i]==0)
		{
			dist[i]=1;
			DFS(i);
		}
	LL ans=0,num=0,num2=0;
	for(int i=1;i<=n;i++)
		if(vis[Findfa(i)]==false)
		{
			vis[Findfa(i)]=true;
			if(d[i]==0)
				continue;
			num++;
			if(setsp[Findfa(i)]==true)
				num2++;
			else
				num2+=2;
		}
	memset(vis,0,sizeof(vis));
	LL cnt=0;
	for(int i=1;i<=n;i++)
		if(vis[Findfa(i)]==false)
		{
			vis[Findfa(i)]=true;
			if(d[i]==0)
			{
				ans+=1LL*n;
				cnt+=1LL;
				continue;
			}
			if(setsp[Findfa(i)]==true)
				ans+=1LL*num;
			else
				ans+=1LL*num2;
		}
	ans+=cnt*(n-cnt);
	printf("%lld\n",ans);
	return 0;
}

