  bool ret = false;
  color[v] = c;
  REP(i, G[v].size()) {
    int u = G[v][i];
    if (color[u] == 0) {
      ret |= dfs(u, 3 - c);
    } else if (color[u] == c) {
      ret = true;
    }
  }
  return ret;
}

void build_graph() {
  REP(i, M) {
    G[u[i] - 1].push_back(v[i] - 1);
    G[v[i] - 1].push_back(u[i] - 1);
  }
}

