        si++;
      } else {
        ret ? ot++ : bi++;
      }
    }
  }
  int ans = 0;
  ans += si * N * 2 - si * si;
  ans += (bi + ot) * (bi + ot);
  ans += bi * bi;
  printf("%d\n", ans);
}

