}
bool dfs(UnWeightedGraph& g,vector<int>& color, int v, int p = -1){
    bool flag = false;
    for(auto nv: g[v]){
        if(p == nv) continue;
        if(color[nv] != -1){
            if(color[nv] == color[v]) flag = true;
        }else{
            color[nv] = 1 - color[v];
            flag |= dfs(g, color, nv, v);
        }
    }
    // cerr << v << " " << flag << endl;
    return flag;
}
