bool dfs(int u){
    bool flag = true;
    for(auto v : G[u]){
        if(col[v] == col[u]) return false;
        if(col[v] == -1){
            col[v] = 1 ^ col[u];
            flag &= dfs(v);
        }
    }
    return flag;
