struct UnionFind{
    vector<int> par; //par: -1*elements(root) number of par(not root)
    UnionFind(int n){
        par = vector<int>(n,-1);
    }
    int root(int x){
        return par[x]<0?x:(par[x]=root(par[x]));
    }
    void unite(int x,int y){
        x=root(x);
        y=root(y);
        if(x!=y){
            if(par[x]<par[y]) swap(x,y);
            par[y] += par[x];
            par[x] = y;
        }
        return;
    }
    bool same(int x,int y){
        return root(x) == root(y);
    }
    int size(int x){
        return -par[root(x)];
    }
};

struct Problem{
    LL n,m;
    vector<vector<int>> g;
    UnionFind uf;
    Problem(LL n, LL m):n(n),m(m),g(n),uf(n){};
    bool oddloop(int s){
        vector<int> vis(n);
        queue<int> Q;
        Q.push(s);
        while(!Q.empty()){
            int cur=Q.front();Q.pop();
            for(int v : g[cur]){
                if(vis[v]==0){
                    vis[v]=2-vis[cur];
                    Q.push(v);
                }else{
                    if(vis[cur]==vis[v])return true;
                }
            }
        }
        return false;
    }

    void solve(){
        for(int i=0; i<m; ++i){
            int a,b;
            cin >> a >> b;
            --a;--b;
            g[a].push_back(b);
            g[b].push_back(a);
