        for(int i=0; i<n; ++i){
            if(uf.par[i]<-1){
                if(!oddloop(i))ev++;
                conn+=uf.size(i);
                cnt++;
            }
            DBG(cnt,conn,ev)
        }
        cout << n*n-conn*conn+cnt*cnt+ev*ev <<"\n";

    }
};

