using namespace std;
typedef long long int ll;
typedef pair <int, int> P;

const ll MOD=1000000007;
const int MAX_N=100000;
struct UF{
    int par[MAX_N];
    int sizes[MAX_N];
    void init (int n){
        for (int i=0;i<n;i++){
            par[i]=i;
            sizes[i]=1;
        }
    }
    int find (int x){
        if (par[x]==x){
            return x;
        }
        else{
            return par[x] = find(par[x]);
        }
    }
    void unite (int x, int y){
        x=find(x);
        y=find(y);
        if (x==y) return;
        if (sizes[x] < sizes[y]) swap(x,y);
        par[y]=x;
        sizes[x]+=sizes[y];
    }
    bool same (int x, int y){
        return find(x) == find(y);
    }
    int size(int x){
        return sizes[find(x)];
    }
};
UF uf;
ll N,M;
bool t[100000];
bool used[100000];
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin>>N>>M;
    uf.init(N);
    vector<int> vec;
    rep(i,0,M){
        int u,v;
        cin>>u>>v;
        u--;
        v--;
        if(uf.same(u, v)) vec.pb(u);
        uf.unite(u, v);
    }
    rep(i,0,sz(vec)) t[uf.find(vec[i])]=1;
    ll s=0, u=0,k=0;
    rep(i,0,N){
        if(uf.size(i)>1) used[uf.find(i)]=1;
    }
    rep(i,0,N){
        if(used[i]) u++;
        if(uf.size(i)==1) k++;
        if(used[i]==1&&uf.size(i)>1&&t[uf.find(i)]==0) s++;
    }
    cout <<N*N-(N-k)*(N-k)+u*u+s<<"\n";
}

