vec<vec<int>> edge;
vec<int> dp;
vec<int> score;

int dfs(int start)
{
	int ret = 1;
	dp[start] = 1;
	rep(i, edge[start].size()) {
		if (dp[edge[start][i]]) continue;
		ret += dfs(edge[start][i]);
	}
	return ret;
}

int odd(int start)
{
	int flag = 0;
	rep(i, edge[start].size()) {
		if (score[edge[start][i]]) {
			if ((score[start] - score[edge[start][i]]) % 2) continue;
			flag = 1;
			break;
		}
		score[edge[start][i]] = score[start] + 1;
		if (odd(edge[start][i])) {
			flag = 1;
			break;
		}
	}
	return flag;
}


int main(void)
{
	int n, m;
	cin >> n >> m;
	edge.resize(n);
	dp.resize(n);
	score.resize(n);
	rep(i, n) dp[i] = 0;
	rep(i, m) {
		int l, r;
		cin >> l >> r;
		l--;
		r--;
		edge[l].pb(r);
		edge[r].pb(l);
	}

	ll ans = (ll)n * (ll)n;
	vec<pair<ll, int>> keep; // first: size, second: odd
	while(1) {
		int next = - 1;
		rep(i, n) {
			if (!dp[i]) {
				next = i;
				break;
			}
		}
		if (next < 0) break;

		int N = dfs(next);
		if (N == 1) continue;
		rep(i, n) score[i] = 0;
		score[next] = 1;
		int flag = odd(next);
		if (flag) ans -= (ll)N * (ll)N - (ll)1;
		else ans -= (ll)N * (ll)N - (ll)2;
		keep.pb(mp((ll)N, flag));
	}
	rep(i, keep.size()) {
		for (int j = i + 1; j < (int)keep.size(); j++) {
			ans -= keep[i].first * keep[j].first * 2;
			if (keep[i].second || keep[j].second) ans += 2;
			else ans += 4;
		}
	}
	cout << ans << endl;
	return 0;
}

