	{
		if (color[u])
			continue;
		if (color[u] = 1, V = 0, dfs(u))
			if (V > 1)
				Ans += (A * 2 + B) * 2 + 2, ++A;
			else
				++C;
		else
			Ans += (A + B) * 2 + 1, ++B;
