	for (int i = 1; i <= n; ++i) if (d[i] == -1) {
		bipartite = false; d[i] = 0; c[0] = 1; c[1] = 0; cnt = 0; dfs(i);
		++m; a[m] = bipartite; b[m] = c[0] + c[1]; t[m] = cnt;
	}

	int full0 = 0, full1 = 0, full = 0, cnt_invalid = 0; 
	for (int i = 1; i <= m; ++i) {
		full1 += (b[i] == 2 ? 1 : 0);
