#define int long long

struct UnionFind
{
  vector< int > data;

  UnionFind(int sz)
  {
    data.assign(sz, -1);
  }

  bool unite(int x, int y)
  {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k)
  {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k)
  {
    return (-data[find(k)]);
  }
};

signed main()
{
  int N, M, U[100000], V[100000];

  cin >> N >> M;
  for(int i = 0; i < M; i++) {
    cin >> U[i] >> V[i];
  }

  UnionFind tree2(N + N), tree3(N);
  for(int i = 0; i < M; i++) {
    tree2.unite(U[i] + N, V[i]);
    tree2.unite(V[i] + N, U[i]);
    tree3.unite(U[i], V[i]);
  }

  int connect = 0, other = 0;
  for(int i = 0; i < N; i++) {
    if(tree3.find(i) != i) continue;
    if(tree3.size(i) == 1) ++other;
    else ++connect;
  }

  int latte = other * N * 2 - other;
  int one = 0, two = 0;
  for(int i = 0; i < N; i++) {
    if(tree3.find(i) != i) continue;
    if(tree3.size(i) == 1) continue;
    bool f = tree2.find(i) != tree2.find(i + N);
    if(f) ++two;
    else ++one;
  }

  for(int i = 0; i < N; i++) {
    if(tree3.find(i) != i) continue;
    if(tree3.size(i) == 1) continue;
    bool f = tree2.find(i) != tree2.find(i + N);
    if(f) latte += 2, latte += one + two - 1;
    else latte++, latte += (one + two - 1);
  }
  cout << latte << endl;
}

