	while (!q.empty()) q.pop();
	q.push(x);
	rec[x] = 1;
	while (!q.empty()){
		int u = q.front(); q.pop();
		cnt++;
		for (int i = 0; i < G[u].size(); i++){
			int v = G[u][i];
			if (!rec[v]){
				q.push(v);
				rec[v] = 3 - rec[u];
			}
			else if (rec[v] != 3 - rec[u]){
				flag = 0;
				break;
			}
		}
		if (!flag) break;
	}
	if (!flag) cnt3++;
	else if (cnt == 1) cnt1++;
	else cnt2++;
	while (!q.empty()) q.pop();
	q.push(x);
	used[x] = 1;
	while (!q.empty()){
		int u = q.front(); q.pop();
		for (int i = 0; i < G[u].size(); i++){
			int v = G[u][i];
			if (!used[v]){
				q.push(v);
				used[v] = 1;
			}
		}
	}
}

