bool dfs(int v, int c) {
  bool is_bipartite = true;
  if (color[v] != 0) {
    return (color[v] == c);
  }
  color[v] = c;
  for (int e = 0; e < (int)G[v].size(); e++) {
    is_bipartite = dfs(G[v][e], -color[v]) && is_bipartite;
  }
  return is_bipartite;
}

int main() {

  int u, v;
  ll a, b, c;

  scanf("%d%d", &N, &M);
  for (int j = 0; j < M; j++) {
