    G[u - 1].push_back(v - 1);
    G[v - 1].push_back(u - 1);
  }
  memset(color, 0, sizeof(color));

  a = b = c = 0;
  for (int i = 0; i < N; i++) {
    if (color[i] != 0) {
      continue;
    }
    if (G[i].empty()) {
      c++;
      color[i] = 1;
    } else {
      if (dfs(i, 1)) {
        a++;
      } else {
        b++;
      }
    }
  }
  ans = (a + b) * (a + b) + a * a + 2 * N * c - c * c;
  printf("%lld\n", ans);

  return 0;

}

