			}
			cout << endl;
		}
		cout << endl;
	}

	bool directedFlag;// 有向グラフかどうか
	int N, M;
	int* weight;// ノードの重み
	vector<edgeClass>* next;// 各ノードにおける辺
	vector<edgeClass> edge;// エッジ
};


int* num;
void bfs(graphClass& G, int root) {// 幅優先探索
	int N = G.N;
	bool* visited = new bool[N];
	for (int i = 0; i < N; i++) {
		visited[i] = (i == root);
	}

	queue<int> q; q.push(root);

	while (q.size() > 0) {
		int n = q.front(); q.pop();
		visited[n] = true;

		// ここに各ノードで行う処理を書く

		for (auto itr = G.next[n].begin(); itr != G.next[n].end(); itr++) {

			// ここに各エッジで行う処理を書く

			if (visited[itr->y] == false) {// まだ訪れていなかったら
				num[itr->y] = 1 - num[n];
				q.push(itr->y);
			}
		}
	}

	delete[] visited;
}

int main() {
	int N, M; cin >> N >> M;
	vector<pair<int, int>> edge;

	UnionFindClass uf;
	uf.activate(N);
	graphClass G;
	G.activate(N);

	for (int i = 0; i < M; i++) {
		int u, v; cin >> u >> v;
		u--; v--;
		edge.push_back({ u,v });
		uf.connect(u, v);
		G.addEdge(u, v);
	}

	bool* flag = new bool[N];
	num = new int[N];
	for (int i = 0; i < N; i++) { num[i] = 0; flag[i] = true; }

	ll k = 0, k1 = 0;
	for (int i = 0; i < N; i++) {
		if (uf.getParent(i) == i) {
			bfs(G, i);
			k++;
			if (uf.size[i] == 1) {
				k1++;
			}
		}
	}

	for (int i = 0; i < M; i++) {
		if ((num[edge[i].first] + num[edge[i].second]) % 2 == 0) {
			flag[uf.getParent(edge[i].first)] = false;
		}
	}

	ll ans = k1 * (N * 2 - k1);
	ans += (k - k1) * (k - k1);

	k = 0;
	for (int i = 0; i < N; i++) {
		if (uf.parent[i] == -1) {
			if (uf.size[i] > 1 && flag[i] == true) { k++; }
		}
	}
	ans += k * k;

	cout << ans << endl;

	return 0;
}

