void sch(int now, int prev, int nowcol, int id, const vvi &g) {
  sz[id]++;
  col[now] = nowcol;
  for(auto &nxt: g[now]) {
    if(nxt == prev) continue;
    if(col[nxt] == nowcol) {
      notnibu[id] = true;
      return;
    } else if(col[nxt] == -1) {
      sch(nxt, now, !nowcol, id, g);
      if (notnibu[id]) return;
    }
  }
}

