bool dfs(auto nd)
{
	bool ans = true;
	siz[nd] = 1;
	for (int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (vis[to] == -1) vis[to] = vis[nd]^1, ans = (ans&&dfs(to)), siz[nd] += siz[to];
		else if (vis[to] == vis[nd]) ans = false;
	}
	return ans;

}

