signed main() {
	INIT;
	VAR(int, n, m);
	VEC_ROW(int, m, u, v);
	std::vector<std::vector<int>> g(n);
	REP(i, m) {
		--u[i]; --v[i];
		g[u[i]].emplace_back(v[i]);
		g[v[i]].emplace_back(u[i]);
	}

	std::vector<bool> visited(n, false);
	std::vector<int> depth(n, 0);
	int one = 0, bi = 0, etc = 0;
	REP(i, n) {
		if (visited[i]) continue;
		visited[i] = true;
		if (g[i].size() == 0) {
			++one;
			continue;
		}
		bool bif = true;
		[&] {
			std::queue<int> que;
			que.push(i);
			while (!que.empty()) {
				int now = que.front(); que.pop();
				for (auto to : g[now]) {
					if (visited[to]) {
						if (depth[to] == depth[now]) {
							bif = false;
						}
					}
					else {
						visited[to] = true;
						depth[to] = !depth[now];
						que.push(to);
					}
				}
			}
		}();
		if (bif) {
			++bi;
		}
		else {
			++etc;
		}
	}

	int ans = 0;
	ans += one * n * 2 - one * one;
	ans += bi * bi;
	ans += (bi + etc) * (bi + etc);
	OUT(ans)BR;
	return 0;
}

