bool f,vis[MAXN];
void add(int x,int y){
	cnt++;
	to[cnt]=y;
	nxt[cnt]=head[x];
	head[x]=cnt;
}
void dfs(int x,int fa){
	vis[x]=true;
	linker[x]=linker[fa]^1;
	for(int i=head[x];i;i=nxt[i]){
		int y=to[i];
		if(y!=fa){
			if(vis[y])
				if(linker[x]==linker[y])f=true;
