int N, M;
vi G[MAX_N];
bool used[MAX_N];
int bi[MAX_N];
int cnt[MAX_N];

bool loop(int v, int p, int k) {
	used[v] = true;
	bi[v] = k;
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(n == p) continue;
		if(!used[n]) {
			if(!loop(n, v, k ^ 1)) return false;
		}
		else {
			if(bi[v] == bi[n]) return false;
		}
	}
	return true;
}

void solve() {
	cin >> N >> M;
	rep(i, 0, M) {
		int a, b;
		cin >> a >> b; a--; b--;
		G[a].pb(b); G[b].pb(a);
		cnt[a]++; cnt[b]++;
	}
	ll even = 0, odd = 0, single = 0;
	rep(i, 0, N) {
		if(cnt[i] == 0) {
			single++;
		}
		else {
			if(!used[i]) {
				if(loop(i, -1, 0)) {
					even++;
				}
				else odd++;
			}
		}
	}
	// debug(even, odd, single);
	cout << even * 2 + odd * 1 + (even * (even - 1) / 2) * 4 + (odd * (odd - 1) / 2) * 2
