	}

	for (int u = 1; u <= n; ++u)
		if (!col[u])
		{
			valid = true, total = 0;
			dfs(u, 2);

			num[0] += total == 1;
			num[1] += !valid;
			num[2] += valid && total > 1;
		}

	s64 a = num[0], b = num[1], c = num[2];
	s64 p = n * a * 2ll - a * a;
	s64 q = b * b + 2ll * b * c + 2ll * c * c;
