    rep (root, 100005) {
        if (rootv[root].empty()) continue;
        if (rootv[root].size() == 1LL) {
            isolated++;
            continue;
        }

        bool is_full = false;
        q.push(root);
        colors[root] = 1LL;

        while (!q.empty()) {
            ll v = q.front(); q.pop();
            ll color = colors[v];
            ll ncolor = (colors[v] & 1LL) + 1LL;
            for (auto nv : linklist[v]) {
                if (colors[nv]) {
                    if (colors[nv] != ncolor) is_full = true;
                    continue;
