// vを含む連結成分に奇数長の閉路が含まれるか
bool dfs(int v) {
    bool ret = false;

    for (int sv : path[v]) {
        if (d[sv] < 0) {
            d[sv] = d[v] + 1;
            ret = ret || dfs(sv);
        } else if ((d[v] - d[sv]) % 2 == 0) {
            // 奇数長閉路判定
            ret = true;
        }
    }

    return ret;
}

int main() {
    ll N, M;
    cin >> N >> M;

    for (int i = 0; i < M; ++i) {
        int u, v;
