struct UnionFind {
  UnionFind(size_t size) : v(size, -1) {}
  vector<int> v;

  int root(int x) {
    return (v[x] < 0 ? x : v[x] = root(v[x]));
  }

  bool is_root(int x) {
    return root(x) == x;
  }

  bool same(int x, int y) {
    return root(x) == root(y);
  }

  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (v[x] > v[y]) swap(x, y);
      v[x] += v[y];
      v[y] = x;
    }
  }

  int size(int x) {
    return -v[root(x)];
  }
};

signed main(int argc, char *argv[]) {
  int n = in(), m = in();

  UnionFind uf(n);
  vector<int> a(m), b(m);
  vector<vector<int>> G(n);
  for (int i = 0; i < m; ++i) {
    a[i] = in() - 1, b[i] = in() - 1;
    uf.unite(a[i], b[i]);
    G[a[i]].pb(b[i]);
    G[b[i]].pb(a[i]);
  }

  vector<int64_t> edge(n);
  for (int i = 0; i < m; ++i) {
    edge[uf.root(a[i])]++;
  }

  vector<int> color(n, -1);
  function<bool(int, int, int)> f = [&](int v, int pre, int col) {
    if (color[v] != -1) return col == color[v];
    color[v] = col;

    for (auto to : G[v]) {
      if (pre == to) continue;
      if (f(to, v, !col)) continue;
      return false;
    }

    return true;
  };

  int64_t ans = 0, cnt = 0;
  for (int i = 0; i < n; ++i) {
    if (!uf.is_root(i)) continue;

    int64_t sz = uf.size(i);
    if (sz == 1)
      ans += 2 * n - 1;
    else if (!f(i, -1, 1))
      ans++;
    else
      ans += 2;

    cnt += (sz != 1);
  }

  ans += cnt * (cnt - 1);

  cout << ans << endl;
}

