struct SCCD    //StronglyConnectedComponentsDecomposition
{
    vector<vector<int>> g;
    vector<vector<int>> rg;
    int n;
    vector<bool> used;
    vector<int> cmp;
    vector<int> vs;

    SCCD(Graph &g_){
        n = g_.n;
        g.resize(n);
        rg.resize(n);
        for(int u = 0; u < n; u++) for(int v : g_.g[u]){
            g[u].push_back(v);
            rg[v].push_back(u);
        }
        used.resize(n);
        cmp.resize(n);
    }

    void dfs(int u){
        used[u] = true;
        for(int v : g[u]){
            if(!used[v]) dfs(v);
        }
        vs.push_back(u);
    }

    void rdfs(int u, int k){
        used[u] = true;
        cmp[u] = k;
        for(int v : rg[u]){
            if(!used[v]) rdfs(v, k);
        }
    }

    int decomposition(){
        fill(used.begin(), used.end(), false);
        for(int i = 0; i < n; i++){
            if(!used[i]) dfs(i);
        }
        fill(used.begin(), used.end(), false);
        int k = 0;
        for(int i = n - 1; i >= 0; i--){
            if(!used[vs[i]]){
                rdfs(vs[i], k);
                k++;
            }
        }
        return k;
    }
};

