bool BipartiteGraph(Graph &g, int i){
    queue<int> que;
    b[i] = 1;
    que.push(i);
    while(que.size()){
        int u = que.front();
        que.pop();
        for(int v : g.g[u]){
            if(b[u] == b[v]){
                return false;
            }
            if(b[v] == 0){
                b[v] = 3 - b[u];
                que.push(v);
            }
        }
    }
    return true;
}

