int f(int x) {
  if(par[x] == x) return x;
  return par[x] = f(par[x]);
}

void unija(int x, int y) {
  x = f(x); y = f(y);
  if(x == y) return;

  sz[y] += sz[x];
  par[x] = y;
}

vector<int> ee, e[MAXN];

int c[MAXN];

bool bipartite(int x, int y) {
  if(c[x]) {
    if(c[x] != y) return false;
    return true;
  }

  c[x] = y;

  bool ret = true;
  for(auto w: e[x]) {
    ret &= bipartite(w, 3 - y);
  }

  return ret;
}

