            rep(j, path[idx].size()){
                ll to = path[idx][j];
                if(flg[to][v ^ 1])continue;
                flg[to][v ^ 1] = 1;
                Q.push(P(to, v ^ 1));
            }
        }
        if(flg[i][1])B++;
        else A++;
    }
    rep1(i, N){
        if(flg[i][0] && flg[i][1])A_cnt++;
        else if(flg[i][0] || flg[i][1])B_cnt++;
    }

    cout << B * B + 2 * A * B + 2 * A * A + 2 * B_cnt * C + 2 * A_cnt * C + C * C << endl;

    return 0;
}

