        cin >> a >> b;
        --a;
        --b;
        uf.unite(a,b);
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    function<bool(int ,int )> dfs=[&](int v,int c){
        color[v]=c;
        rep(i,0,graph[v].size()){
            if(color[graph[v][i]]==c) return false;
            if(color[graph[v][i]]==0 and !dfs(graph[v][i],-c)) return false;
        }
        return true;
    };

    i64 s1=0,s2=0,t=0;
    set<int> done;
    rep(i,0,n){
        if(color[i]!=0) continue;
        int x=uf.find(i);
        if(done.find(x)!=done.end()) continue;
        done.insert(x);
        if(uf.group_size(x)==1){
            ++t;
            continue;
        }
        if(dfs(i,1)) ++s1;
        else ++s2;
    }
    cout << 2*s1*(s1-1)+2*s1+s2*s2+2*s1*s2+2*t*(t-1)+2*t*(n-t)+t << endl; 
}

