int isBipartite(vector<vector<int>>&g) {
	vector<int>color;
	color.resize(g.size(), 0);
	int o = 0, p = 0, q = 0;
	rep(i, 0, g.size()) {
		if (color[i] == 0) {
			bool f = isBipartite_proc(i, 1, color, g);
			if (g[i].size() == 0)o++;
			else if (f)q++;
			else p++;
		}
	}
	int n = g.size();
	return o*n * 2 - o * o + p * p + p * q * 2 + q * q * 2;
}

