class disjoint_set {
    vector<ll> p;
public:
    ll count;
    disjoint_set(ll n) : p(n, -1), count(0) {}
    ll root(ll i) { return p[i] >= 0 ? p[i] = root(p[i]) : i; }
    bool same(ll i, ll j) { return root(i) == root(j); }
    ll size(ll i) { return -p[root(i)]; }
    void merge(ll i, ll j) {
        count++;
        i = root(i), j = root(j);
        if (i == j) return;
        if (p[i] > p[j]) swap(i, j);
        p[i] += p[j], p[j] = i;
    }
    ll size(ll i, ll j) {
        if(same(i,j)) return size(i);
        else return size(i) + size(j);
    }
};

