		int p=uft1.Find_Par(i);
		if(!b[p]){
			if(uft1.Find_Size(p)==1){
				N++;
				b[p]--;
			}
			else{
				num0+=(uft2.Same(i,i+n)?1:2);
				num1++;
				b[p]++;
			}
		}
	}
	ll ans=N*n*2-N*N;
	for(int i=0;i<n;i++){
