	void add(int x,int y,bool k=1)
	{
		to[++e]=y;
		next[e]=begin[x];
		begin[x]=e;
		if(k)add(y,x,0);
	}
	int col[N];
	bool dfs(int p,int x)
	{
		if(col[p])return col[p]==x;
		col[p]=x;

		bool ret=1;
		for(int i=begin[p],q;i;i=next[i])
			if(!dfs(q=to[i],3-x))ret=0;
		return ret;
	}
	void initialize()
	{
