struct UnionFind{
    int num;
    vector<int> par,rank;
    UnionFind(int n):num(n),par(n),rank(n,1){
        iota(all(par),0);
    }
    int root(int x){
        if (par[x]==x) return x;
        return par[x]=root(par[x]);
    }
    bool merge(int x, int y){
        x=root(x),y=root(y);
        if (x==y) return false;
        if (rank[x]<rank[y]) swap(x,y);
        par[y]=x;
        rank[x]+=rank[y];
        --num;
        return true;
    }
    bool same(int x, int y){
        return root(x)==root(y);
    }
    int size(int x){
        return rank[root(x)];
    }
    int count(){
        return num;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N,M; cin >> N >> M;
    UnionFind uf(2*N);
    vector<Pii> G(M);
    rep(i,M){
        int u,v; cin >> u >> v;
        G[i]={--u,--v};
        uf.merge(u,v+N),uf.merge(u+N,v);
    }
    ll side1=0,side2=2*N-uf.count(),ans=N*N,dec=0;
    set<int> pars;
    rep(i,N) if (uf.size(i)>1){
        ++side1;
        int p=uf.root(i),q=uf.root(i+N);
        if (!pars.count(p)&&p!=q) ++dec;
        pars.insert(p),pars.insert(q);
    }
    vector<bool> used(N,false);
    UnionFind uf2(2*N);
    for (auto p:G){
        int u=p.first,v=p.second;
        if (!(used[u]||used[v])) ans-=side2;
        else if (!(used[u]&&used[v])) ans-=side1;
        bool ok=false;
        if (used[u]&&!uf2.same(u,u+N)&&used[v]&&!uf2.same(v,v+N)) ok=true;
        used[u]=used[v]=true;
        uf2.merge(u,v+N),uf2.merge(u+N,v);
        if (ok&&uf.same(u,u+N)&&uf2.same(v,v+N)) ans-=dec;
    }
    cout << ans << endl;
}

