bool Dfs(int v, int col, int* sz) {
  used[v] = true;
  colors[v] = col;
  (*sz)++;
  bool ans = false;
  for (const auto& to : graph[v]) {
    if (!used[to]) {
      if (Dfs(to, 1 - col, sz)) {
        ans = true;
      }
    } else {
      if (colors[to] == col) {
        ans = true;
      }
    }
  }
  return ans;
}

