    {
      int u, v; scanf("%d%d", &u, &v);
      adj[u].push_back(v);
      adj[v].push_back(u);
    }
    cout << solve() << endl;
    // cerr << bf() << endl;
    for (int i = 1; i <= n; ++i) adj[i].clear();
  }
  return 0;
}

