    vector<int> es;
    UnionFind(int N) : par(N,-1),es(N,0) {}

    //初期化
    void init(int N){
        par.assign(N,-1);
        es.assign(N,0);
    }
    //rootを探す
    int find(int x){
        if(par[x]<0) return x;
        else return par[x]=find(par[x]);
    }
    //集合の要素数
    int usize(int x) {return -par[find(x)];}
    //集合の辺の数
    int esize(int x) {return es[find(x)];}
    //xとyが繋がっていたらfalseを返す
    bool unite(int x,int y){
        x=find(x);
        y=find(y);
        es[x]++;
        if(x==y) return false;

        if(usize(x)<usize(y)) swap(x,y);
        par[x]+=par[y];
        es[x]+=es[y];
        par[y]=x;
        return true;
    }

    bool same(int x,int y) {return find(x)==find(y);}

};

template<typename G>
bool bipartite(const G &g,int idx){
    map<int,int> color;
    stack<pii> st;
    st.push({idx,0});
    while(!st.empty()){
        int idx,nc;
        tie(idx,nc)=st.top();
        st.pop();
        for(auto next:g[idx]){
            if(color.find(next)==color.end()){
				color[next]=nc^1;
                st.push({next,nc^1});  //++++++++++++++++++++
            }else{
                if(color.find(next)!=color.end() && color[next]!=nc^1) return false;  //+++++++++++
            }
        }
    }
    return true;
}



