// paint(v,1)で呼び出す
int paint(int v, int c) {
    if (G[v].size() == 0) return 0;
    if (color[v] != 0) {
        if (color[v] != c) return -1;
        return 1;
    }

    color[v] = c;

    for (auto e : G[v]) {
        if (paint(e, -c) == -1) {
            return -1;
        }
    }

    return 1;


}

