  function<int(int, int, int, int)> dfs = [&](int cur, int pre, int depth, int idx) {
    //out(cur, pre, depth, idx);
    int ret = 1;
    forr(nex, E[cur]) if (nex != pre) {
      if (D[nex] != -1) {
        if (D[nex] <= D[cur]) {
          loop[idx] = 1;
        }
      }
      else {
        D[nex] = D[cur] + 1;
        ret += dfs(nex, cur, depth+1, idx);
      }
    }
    return ret;
  };

  vpii sizes;

  rep(i, n) if (D[i] == -1) {
    D[i] = 0;
