ll ans;

inline bool dfs(int u) {
	vis[u] = true, size++;
	bool res = false;
	int i;
	for(i = st[u]; i; i = nxt[i]) {
		int v = to[i];
		if(vis[v]) {
			if(col[v] == col[u]) res = true;
			continue;
		}
		col[v] = col[u]^1, res |= dfs(v);
	}
	return res;
}

int main() {
