uint64_t N, M;
map<uint64_t, set<uint64_t>> sides;

bool friends(const P &p) {
  static set<P> ps;

  if (!ps.insert(p).second)
    return false;

  list<P> news = {p};
  for (const auto &p_ : news) {
    auto u = p_.first;
    auto v = p_.second;

    for (auto u_ : sides[u]) {
      for (auto v_ : sides[v]) {
        if (ps.emplace(u_, v_).second)
          news.emplace_back(u_, v_);
      }
    }
  }

  return true;
}

uint64_t count() {
  uint64_t ret = 0;

  for (uint64_t i = 1; i <= N; ++i) {
    for (uint64_t j = 1; j <= N; ++j) {
      ret += friends(make_pair(i, j));
    }
  }

  return ret;
}

