const int MAX_V = 100010;

class UnionFind {
public:
    // コンストラクタ
    explicit UnionFind(int N) : V_NUM(N) {
        for (int i = 0; i < V_NUM; ++i) {
            par[i] = i;
        }
        fill(rank, rank + V_NUM, 0);
        fill(num, num + V_NUM, 1);
    }

    // xの親を返す+更新
    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    // xとyを含むグループを統合する
    void unite(int x, int y) {
        x = find(x);
        y = find(y);

        if (x == y) return;

        // rank[x] >= rank[y]にする
        if (rank[x] < rank[y]) swap(x, y);

        // rankの大きい方、つまりxにyをくっつける
        num[x] += num[y];
        par[y] = x;
        if (rank[x] == rank[y]) ++rank[x];
    }

    // xとyが同じグループに属するか判定
    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return num[find(x)];
    }

    const int INF = 1 << 25;
    int V_NUM;
    int par[MAX_V], rank[MAX_V], num[MAX_V];
};


vector<ll> path[100010];
int d[100010];

// vを含む連結成分に奇数長の閉路が含まれるか
bool dfs(int v) {
    bool ret = false;

    for (int sv : path[v]) {
        if (d[sv] < 0) {
            d[sv] = d[v] + 1;
            ret = ret || dfs(sv);
        } else if ((d[v] - d[sv]) % 2 == 0) {
            ret = true;
        }
    }

    return ret;
}

int main() {
    int N, M;
    cin >> N >> M;

    UnionFind uf(N);

    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u, --v;
        path[u].push_back(v);
        path[v].push_back(u);
        uf.unite(u, v);
    }

    ll single = 0, even = 0, odd = 0;
    // single = 頂点数1の連結成分(孤立点)の数
    // odd = 奇数長の閉路をもつ連結成分の数
    // even = それ以外の連結成分の数

    fill(d, d + N, -1);

    for (int v = 0; v < N; ++v) {
        if (uf.find(v) != v) continue;
        d[v] = 0;
        if (uf.size(v) == 1) {
            ++single;
        } else {
            if (dfs(v)) {
                ++odd;
            } else {
                ++even;
            }
        }
    }

    cout << sq(N) - sq(N - single) + sq(even + odd) + sq(even) << endl;
    return 0;
}

