const int MAXN = 1e5 + 5;
const int MAXM = 4e5 + 5;

struct Edge {
    int v, next;
    Edge() { }
    Edge(int v_, int next_): v(v_), next(next_) { }
};

int N, M;
int tote, head[MAXN];
Edge edge[MAXM];

inline void addEdge(int u, int v)
{
    edge[++tote] = Edge(v, head[u]);
    head[u] = tote;
}

void input()
{
    read(N); read(M);
    tote = 1;
    for (int i = 1; i <= M; ++i) {
        int u, v;
        read(u); read(v);
        addEdge(u, v);
        addEdge(v, u);
    }
}

bool vis[MAXN];
int color[MAXN];

void dfs1(int u)
{
    if (vis[u])
        return;
    vis[u] = true;
    for (int i = head[u]; i; i = edge[i].next) {
        int v = edge[i].v;
        dfs1(v);
    }
}

bool dfs2(int u)
{
    for (int i = head[u]; i; i = edge[i].next) {
        int v = edge[i].v;
        if (color[v]) {
            if (color[u] == color[v])
                return false;
        } else {
            color[v] = 3 - color[u];
            if (!dfs2(v))
                return false;
        }
    }
    return true;
}

void solve()
{
    LL totv = N, tot1 = 0, tot2 = 0;
    LL ans = 0;
    for (int i = 1; i <= N; ++i) {
        if (vis[i])
            continue;
        if (!head[i]) {
            ans += 2 * totv - 1;
            --totv;
            continue;
        }
        dfs1(i);
        color[i] = 1;
        if (dfs2(i))
            ++tot2;
        else
            ++tot1;
    }

    ans += tot2 * tot2 * 2 + tot2 * tot1 + tot1 * tot2 + tot1 * tot1;

    printf("%lld\n", ans);
}

