struct UF {
    int gn;
    V<int> p, sz;
    V<int> e;
    UF(int n) : gn(n), p(n, -1), sz(n, 1), e(n, 0) {}
    bool merge(int x, int y) {
        x = group(x);
        y = group(y);
        if (x == y) {
            e[y]++;
            return false;
        }
        gn--;
        if (sz[x] > sz[y]) swap(x, y);
        p[x] = y;
        sz[y] += sz[x];
        e[y] += e[x] + 1;
        return true;
    }
    int group(int a) {
        if (p[a] == -1) return a;
        return p[a] = group(p[a]);
    }
    bool same(int a, int b) { return group(a) == group(b); }
};

int n, m;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << setprecision(20) << fixed;

    cin >> n >> m;
    UF r(n), two(2 * n), three(3 * n);
    for (int i = 0; i < m; i++) {
        int x, y;
        cin >> x >> y; x--; y--;
        r.merge(x, y);
        two.merge(x, y + n);
        two.merge(y, x + n);
        three.merge(x, y + n);
        three.merge(y, x + n);
        three.merge(x + n, y + 2 * n);
        three.merge(y + n, x + 2 * n);
    }

    ll ans = 0;
    for (int i = 0; i < n; i++) {
        int g = r.group(i);
        if (i == g) {
            if (r.sz[g] == 1) ans += n;
            else if (r.sz[g] == 3 && r.e[g] == 2) ans += three.gn;
            else ans += two.gn;
        }
    }
    cout << ans << "\n";

    return 0;
}

