struct UnionFind
{
  vector< int > data;

  UnionFind(int sz)
  {
    data.assign(sz, -1);
  }

  bool unite(int x, int y)
  {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k)
  {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k)
  {
    return (-data[find(k)]);
  }
};

int main()
{
  int N, M;

  cin >> N >> M;
  UnionFind tree(N + N);
  while(M--) {
    int U, V;
    cin >> U >> V;
    --U, --V;
    tree.unite(U + N, V);
    tree.unite(V + N, U);
  }

  int other = 0, one = 0, two = 0;
  for(int i = 0; i < N; i++) {
    if(tree.find(i) == i) {
      if(tree.size(i) == 1) ++other;
      else if(tree.find(i) != tree.find(i + N)) ++two;
      else ++one;
    }
  }

  int latte = other * N * 2 - other * other;
  cout << latte + two * two * 2 + one * one + two * one * 2 << endl;
}

