      scanf("%d %d", &u, &v);
      u -= 1;
      v -= 1;
      g[u].push_back(v);
      g[v].push_back(u);
      uf.unite(u, v);
    }
  }
  rep (i, n) {
    roots.insert(uf.root(i));
  }
  ll bocchi = 0;
  ll bipartite = 0;
  ll other = 0;
  for (int u : roots) {
    if (uf.size(u) == 1) {
      bocchi += 1;
