const int MAXN = 100000;
int parent[MAXN], sz[MAXN];
bool hasCycle[MAXN];


int FindSet(int v)
{
	if (v == parent[v])
		return v;
	return parent[v] = FindSet(parent[v]);
}

void UnionSets(int a, int b)
{
	a = FindSet(a);
	b = FindSet(b);
	if (a != b)
	{
		if (sz[a] > sz[b])
		{
			parent[b] = a;
			sz[a] += sz[b];
			hasCycle[a] |= hasCycle[b];
		}
		else
		{
			parent[a] = b;
			sz[b] += sz[a];
			hasCycle[b] |= hasCycle[a];
		}
	}
}

