	}

	for (int m = rint(); m > 0; m--)
	{
		int u = rint() - 1;
		int v = rint() - 1;
		if (FindSet(u) != FindSet(v))
			UnionSets(u, v);
		else
			hasCycle[FindSet(u)] = true;
	}

	int os = 0, oc = 0, es = 0, ec = 0;
	for (int i = 0; i < n; i++)
		if (FindSet(i) == i && sz[i] > 1)
