bool DFS(int v, int previous_v = -1){
    if(visited[v] == true) return true;
    visited[v] = true;

    bool flag = false;
    for(int adjacent_v : graph[v]){
        if(adjacent_v == previous_v) continue;

        flag |= DFS(adjacent_v, v);
    }
    return flag;
}

