        int u, v;
        cin >> u >> v;
        u -= 1;
        v -= 1;

        graph[u].push_back(v);
        graph[v].push_back(u);
        degree[u] += 1;
        degree[v] += 1;
    }

    long long int ans = 0;
    long long int a = 0, b = 0, c = 0;
    for(int i=0; i<n; i++){
        if(degree[i] == 0){
            c += 1;
            ans += 2*n;
        }
