            bool cycle = DFS(i);
            if(cycle == false) a += 1;
            if(cycle == true)  b += 1;
        }
    }
    ans -= c * c;

    ans += 2 * a * a + 1 * ((a+b) * (a+b) - a * a);
    cout << ans << endl;
