	int sum = 0;

	FOR(i, 1, n) if (find(i) == i) {
		sum += sz[i];
		if (is[i]) szj++;
		else if (sz[i] == 1) sz1++;
		else szo++;
	}

	LL ans = 0;
	ans += 1ll * sz1 * (sum - sz1) * 2 + 1ll * sz1 * sz1;
	ans += 1ll * szj * szo * 2 + 1ll * szj * szj;
	ans += 1ll * szo * szo * 2;

	printf("%lld\n", ans);

	return 0;
}

