using namespace std;

typedef long long ll;

struct Union_Find {
    //各要素が属する集合の代表(根)を管理する
    //もし、要素xが根であればdata[x]は負の値を取り、-data[x]はxが属する集合の大きさに等しい
    vector<int> data;

    Union_Find(int size) : data(size, -1) {}
    bool Union(int x, int y) {
        x = Find(x);
        y = Find(y);
        bool is_union = (x != y);
        if (is_union) {
            if (data[x] > data[y]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return is_union;
    }
    int Find(int x) {
        if (data[x] < 0) { //要素xが根である
            return x;
        } else {
            data[x] = Find(data[x]); //data[x]がxの属する集合の根でない場合、根になるよう更新される
            return data[x];
        }
    }
    bool same(int x, int y) {
        return Find(x) == Find(y);
    }
    int size(int x) {
        return -data[Find(x)];
    }
};


int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int n, m;
	cin >> n >> m;
	vector<int> u(m), v(m);
	Union_Find uf(n);
	for (int i = 0; i < m; i++) {
		cin >> u[i] >> v[i];
		u[i]--;
		v[i]--;
		uf.Union(u[i], v[i]);
	}

	int cnt1 = 0, cnt2 = n;
	for (int i = 0; i < n; i++) {
		if (uf.Find(i) == i) {
			if (uf.size(i) > 1) cnt1++;
			else cnt2--;
		}
	}

	vector<int> memo(n, 0);
	Union_Find uf2(n);
	for (int i = 0; i < m; i++) {
		if (uf2.same(u[i], v[i])) {
			memo[uf.Find(u[i])] = 1;
		} else {
			uf2.Union(u[i], v[i]);
		}
	}
	int cnt3 = accumulate(memo.begin(), memo.end(), 0);
	cout << (ll)n * n - (ll)cnt2 * cnt2 + cnt1 * 2 + cnt3 << endl;
	return 0;
}

