typedef long long i64;

const int N = 100000 + 10;

int n, m;

int anc[N], col[N], size[N];
bool flag[N];

int find(int x) {
  if (anc[x] == x) return x;
  int y = find(anc[x]);
  col[x] ^= col[anc[x]];
  return anc[x] = y;
}

void meld(int x, int y) {
  int a = find(x), b = find(y);
  if (a == b) {
    flag[a] |= (col[x] == col[y]);
    return;
  }
  size[b] += size[a];
  anc[a] = b;
  col[a] ^= (col[x] == col[y]);
  flag[b] |= flag[a];
}

int main() {
  scanf("%d%d", &n, &m);
  for (int i = 1; i <= n; ++i) size[anc[i] = i] = 1;
  while (m--) {
    int a, b;
    scanf("%d%d", &a, &b);
    meld(a, b);
  }
  int x = 0, y = 0, z = 0;
  for (int i = 1; i <= n; ++i) {
    if (find(i) == i) {
      if (size[i] == 1) ++x; else if (flag[i]) ++z; else ++y;
    }
  }
  i64 ans = 2LL * x * n - (i64)x * x;
  ans += 2LL * y * y;
  ans += 2LL * y * z;
  ans += (i64)z * z;
  printf("%lld\n", ans);
  return 0;
}

