    vector<int> vis(N, -1);
    for(int i=0; i<N; i++){
        if(vis[i] >= 0) continue;
        if(graph[i].size()==0) w++;
        else if(isBipartite(graph, vis, i, -1)) u++;
        else v++;
    }

    cout << u*u + (u+v)*(u+v) + w*(2*N-w) << endl;
}

