using namespace std;

typedef long long LL;
const int MAX_N = 2e5 +6;

struct DisjointSet {
	int p[MAX_N];
	void init(int n) {
		for (int i=0;n>=i;i++) {
			p[i]=i;
		}
	}
	int Find(int x) {
		return x==p[x]?x:p[x]=Find(p[x]);
	}
	void Union(int x,int y) {
		p[Find(x)] = Find(y);
	}
} djs;

int main () {
	int n,m;
	while (scanf("%d %d",&n,&m) != EOF) {
		djs.init(n);
		LL ans = LL(n)*LL (n-1);
		for (int i=1;m>=i;i++) {
			int a,b;
			scanf("%d %d",&a,&b);
			djs.Union(a,b);
			ans--;
		}
		for (int i=1;n>=i;i++) {
			ans += (djs.Find(i)==i);
		}
		printf("%lld\n",ans);
	}
}

