// ぼっちなら0
// 二部グラフなら1
// 二部グラフじゃないなら-1
// paint(v,1)で呼び出す
int paint(int v, int c) {
    if (G[v].size() == 0) return 0;
    if (color[v] != 0) {
        if (color[v] != c) return -1;
        return 1;
    }

    color[v] = c;

    for (auto e : G[v]) {
        if (paint(e, -c) == -1) {
            return -1;
        }
    }

    return 1;


}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> M;
    G.resize(N);
    color.resize(N);


    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    // x 二部じゃない y 二部 z ぼっち
    //(x + y) ^ 2 + y * y + 2 * z * N - 1が答え
    ll x = 0ll, y = 0ll, z = 0ll;

    for (int i = 0; i < N; ++i) {
        if (color[i] == 0) {
            int val = paint(i, 1);
            if (val == 0) z++;
            if (val == 1) y++;
            if (val == -1) x++;
        }
    }

//    ll ans = (x + y) * (x + y) + y * y + 2 * z * N - 1;
    ll ans = 1ll * N * N - 1ll * (N - z) * (N - z) + (x + y) * (x + y) + y * y;
    cout << ans << endl;

    return 0;
}

