typedef long long ll;
const int N = 1e5 + 100;

ll n, m, ans, c[N];
vector<int> nei[N];

bool dfs(int v) {
	for (int u: nei[v])
		if (c[u] == 0) {
			c[u] = 3 - c[v];
			if (dfs(u))
				return true;
		}
		else if (c[u] == c[v])
			return true;
	return false;
}

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	cin >> n >> m;
	if (m == 0) {
		cout << n * n;
		return 0;
	}
	while (m--) {
		int u, v;
		cin >> u >> v;
		nei[--u].push_back(--v);
		nei[v].push_back(u);
	}
	for (int i = 0; i < n; i++)
		if (nei[i].empty())
			ans++;
	ans = n * n - (n - ans) * (n - ans);
	ll f = 0, z = 0;
	for (int i = 0; i < n; i++)
		if (nei[i].size() && c[i] == 0) {
			c[i] = 1;
			if (dfs(i))
				f++;
			else
				z++;
		}
	ans += z * z * 2;
	ans += f * f * 1;
	ans += f * z;
	ans += z * f;
