int dfs(int v, int& flag) {
	used[v] = 1;
	int sz = 1;
	for(auto& u: g[v]) if(!used[u]) {
		color[u] = color[v] ^ 1;
		sz += dfs(u, flag);
	}
	for(auto& u: g[v]) if(color[v] == color[u]) {
		flag = 0;
		break;	
	}
	return sz;
}
