bool is_bipertite(int n, int color) {
    if (graph[n].color == color) {
        return true;
    } else if (graph[n].color == -color) {
        return false;
    }

    graph[n].color = color;

    for (int e : graph[n].edge) {
        if (!is_bipertite(e, -color)) {
            return false;
        }
    }
    return true;
}

int main(int argc, char **argv) {
