// 二部グラフなら1、辺がなければ-1、それ以外は0を返す
int dfs(int v, int sign) {
	int i, single_flag = 1, res = 1;

	used[v] = sign;
	for (i = 1; i <= N; i++) {
		if (edge[v][i] == 1) {
			if (used[i] == sign)
				res = 0;
			else if (used[i] == 0)
				res = dfs(i, -sign);
			single_flag = 0;
		}
	}

	if (single_flag)
		return -1;
	else
		return res;
}

