public class Main {
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    int N = sc.nextInt();
    int M = sc.nextInt();
    int[] from = new int[M];
    int[] to = new int[M];

    UnionFind uf = new UnionFind(N);
    for (int i = 0; i < M; i++) {
      from[i] = sc.nextInt() - 1;
      to[i] = sc.nextInt() - 1;
      uf.union(from[i], to[i]);
    }

    Set<Integer> roots = new HashSet<>();
    for (int i = 0; i < N; i++) {
      int root = uf.find(i);
      roots.add(root);
    }
    List<Integer> rootArray = new ArrayList<>(roots);

    int[][] g = packU(N, from, to);


    long c1 = 0;
    for (int root : rootArray) {
      if (g[root].length == 0) {
        c1 ++;
        roots.remove(root);
      }
    }

    color = new int[N];

    long ret = c1 * c1;

    long c2 = 0;
    long c3 = 0;
    for (int root : roots) {
      if (dfs(root, -1, g)) {
        c2 ++;
      } else {
        c3 ++;
      }
      ret += uf.count(root) * c1 * 2;
    }

    ret += c2 * c2 * 2 + c2 * c3 * 2 + c3 * c3;
    System.out.println(ret);

  }

  private static int[] color;
  private static boolean dfs(int now, int pre, int[][] g) {
    color[now] = pre < 0 ? 1 : -color[pre];
    for (int next : g[now]) {
      if (color[next] == 0) {
        if (!dfs(next, now, g)) {
          return false;
        }
      } else if (color[next] != -color[now]) {
        return false;
      }
    }
    return true;
  }

  public static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }
}


class UnionFind {
  private int[] table;
  private int[] rank;
  private int[] count;

  public UnionFind(int size) {
    this.table = new int[size];
    this.rank = new int[size];
    this.count = new int[size];
    for (int i = 0; i < size; i++) {
      this.table[i] = i;
      this.rank[i] = 1;
      this.count[i] = 1;
    }
  }

  public boolean isSame(int node1, int node2) {
    return find(node1) == find(node2);
  }

  public int find(int node) {
    if (table[node] == node) {
      return node;
    } else {
      return table[node] = find(table[node]);
    }
  }

  public int count(int node) {
    return count[find(node)];
  }

  public void union(int node1, int node2) {
    int root1 = find(node1);
    int root2 = find(node2);

    if (rank[root1] < rank[root2]) {
      table[root1] = root2;
      count[root2] += count[root1];
    } else if (rank[root1] > rank[root2]) {
      table[root2] = root1;
      count[root1] += count[root2];
    } else if (root1 != root2) {
      table[root2] = root1;
      count[root1] += count[root2];
      rank[root1]++;
    }
  }
}


