import java.util.List;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskC solver = new TaskC();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskC {
		boolean twoCol;
		int size;

		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int m = in.nextInt();
			List<Integer>[] adj = new List[n];
			for (int i = 0; i < n; i++) {
				adj[i] = new ArrayList();
			}
			for (int i = 0; i < m; i++) {
				int a = in.nextInt() - 1;
				int b = in.nextInt() - 1;
				adj[a].add(b);
				adj[b].add(a);
			}
			int[] col = new int[n];
			long numNonTwoCol = 0;
			long numTwoCol = 0;
			long numSizeOne = 0;
			List<Integer> sizes = new ArrayList<>();
			List<Boolean> twoC = new ArrayList<>();
			for (int i = 0; i < n; i++) {
				if (col[i] == 0) {
					twoCol = true;
					size = 0;
					dfs(i, 1, col, adj);
					sizes.add(size);
					twoC.add(twoCol);
					if (size == 1) {
						++numSizeOne;
					} else if (twoCol) {
						++numTwoCol;
					} else {
						++numNonTwoCol;
					}
				}
			}
			long ans = 0;
			for (int i = 0; i < sizes.size(); i++) {
				int size = sizes.get(i);
				boolean tc = twoC.get(i);
				if (size == 1) {
					ans += n;
					continue;
				}
				if (tc) {
					ans += numNonTwoCol + numSizeOne * size + 2 * numTwoCol;
				} else {
					ans += numNonTwoCol + numSizeOne * size + numTwoCol;
				}
			}
			out.println(ans);
		}

		private void dfs(int v, int c, int[] col, List<Integer>[] adj) {
			col[v] = c;
			++size;
			for (int u : adj[v]) {
				if (col[u] == 0) {
					dfs(u, 3 - c, col, adj);
				} else if (col[u] != 3 - c) {
					twoCol = false;
				}
			}
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.NoSuchElementException;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		FastScanner sc = new FastScanner();
		int N = sc.nextInt();
		int M = sc.nextInt();
		int[] u = new int[M];
		int[] v = new int[M];
		ArrayList<Integer>[] g = new ArrayList[N];
		for (int i = 0; i < N; ++i) {
			g[i] = new ArrayList<>();
		}
		for (int i = 0; i < M; ++i) {
			u[i] = sc.nextInt();
			v[i] = sc.nextInt();
			--u[i];
			--v[i];
			g[u[i]].add(v[i]);
			g[v[i]].add(u[i]);
		}
		solver(N, M, u, v, g);

	}

	void solver(int N, int M, int[] u, int[] v, ArrayList<Integer>[] g) {
		DJSet ds = new DJSet(N);
		for (int i = 0; i < M; ++i) {
			ds.setUniont(u[i], v[i]);
		}
		boolean[] vis = new boolean[N];
		long[] cnt = new long[3];
		long sz = 0;
		int[] color = new int[N];
		Arrays.fill(color, -1);
		for (int i = 0; i < N; ++i) {
			if (vis[ds.root(i)])
				continue;
			int t = type(ds.root(i), g, color);
			vis[ds.root(i)] = true;
			++cnt[t];
			if (t != 0)
				sz += ds.size(i);
		}
		long ans = 0;
		ans += cnt[0] * sz;
		ans += sz * cnt[0];
		ans += cnt[0] * cnt[0];
		ans += cnt[1] * cnt[1] * 2;
		ans += cnt[2] * cnt[2];
		ans += cnt[1] * cnt[2];
		ans += cnt[2] * cnt[1];
		System.out.println(ans);

	}

	// 0:頂点一つ
	// 1:二部グラフ
	// 2:非二部グラフ
	int type(int rep, ArrayList<Integer>[] g, int[] color) {
		if (g[rep].size() == 0)
			return 0;
		if (isBipartite(rep, color, 0, g)) {
			return 1;
		} else
			return 2;
	}

	boolean isBipartite(int cur, int[] color, int curColor, ArrayList<Integer>[] g) {
		color[cur] = curColor;
		for (int dst : g[cur]) {
			if (color[dst] != -1) {
				if (color[dst] == curColor)
					return false;
				continue;
			}
			if (!isBipartite(dst, color, curColor ^ 1, g)) {
				return false;
			}
		}
		return true;
	}

	class DJSet {
		int n;
		int[] upper;

		public DJSet(int n) {
			this.n = n;
			upper = new int[n];
			Arrays.fill(upper, -1);
		}

		int root(int x) {
