class Main {
	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();
		int[] u = new int[M];
		int[] v = new int[M];
		for (int i = 0; i < M; i++) {
			u[i] = sc.nextInt() - 1;
			v[i] = sc.nextInt() - 1;
		}

		Map<Pair, List<Pair>> graph = new HashMap<>();
		for (int i = 0; i < M; i++) {
			for (int j = 0; j < M; j++) {
				Pair[][] pair = new Pair[4][];
				pair[0] = new Pair[] { new Pair(u[i], v[j]), new Pair(v[i], u[j]) };
				pair[1] = new Pair[] { new Pair(v[i], u[j]), new Pair(u[i], v[j]) };
				pair[2] = new Pair[] { new Pair(u[i], u[j]), new Pair(v[i], v[j]) };
				pair[3] = new Pair[] { new Pair(v[i], v[j]), new Pair(u[i], u[j]) };

				for (Pair[] p : pair) {
					List<Pair> list = graph.get(p[0]);
					if (list != null) {
						list.add(p[1]);
					} else {
						list = new ArrayList<>();
						list.add(p[1]);
						graph.put(p[0], list);
					}
				}
			}
		}

		Set<Pair> used = new HashSet<>();
		int count = 0;
		for (int i = 0; i < N; i++) {
			for (int j = 0; j < N; j++) {
				Pair start = new Pair(i, j);
				if (!used.contains(start)) {
					count++;

					Deque<Pair> queue = new ArrayDeque<>();
					queue.add(start);
					while (!queue.isEmpty()) {
						Pair current = queue.pop();
						if (used.contains(current)) {
							continue;
						}
						used.add(current);

						List<Pair> list = graph.get(current);
						if (list != null) {
							queue.addAll(list);
						}
					}
				}
			}
		}

		System.out.println(count);
	}

	public static class Pair {
		private int u;
		private int v;

		public Pair(int u, int v) {
			super();
			this.u = u;
			this.v = v;
		}

		public int getU() {
			return u;
		}

		public int getV() {
			return v;
		}

		@Override
		public int hashCode() {
			final int prime = 31;
			int result = 1;
			result = prime * result + u;
			result = prime * result + v;
			return result;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (getClass() != obj.getClass())
				return false;
			Pair other = (Pair) obj;
			if (u != other.u)
				return false;
			if (v != other.v)
				return false;
			return true;
		}

		@Override
