public class Main{

	int N, M;
	UnionFind uf;
	boolean[] tree;
	boolean[] reach;
	public void solve(){
		N = nextInt();
		M = nextInt();
		uf = new UnionFind(N);
		for(int i = 0; i < M; i++){
			int u = nextInt() - 1;
			int v = nextInt() - 1;
			uf.union(u, v);
		}
		reach = new boolean[N];
		long ans = (long)N * (long)N;
		long sumt = 0;
		long sumn = 0;
		for(int i = 0; i < N; i++){
			int idx = uf.root(i);
			if(!reach[idx]){
				reach[idx] = true;
				long size = uf.size(idx);
				if(size > 1){
					ans -= size * size;
					if(uf.isMulti(idx)){
						ans += 1;
						if(sumt > 0) ans -= (sumt * size - 1) * 2;
						if(sumn > 0) ans -= (sumn * size - 1) * 2;
						sumt += size;
					}else{
						ans += 2;
						if(sumt > 0) ans -= (sumt * size - 1) * 2;
						if(sumn > 0) ans -= (sumn * size - 2) * 2;
						sumn += size;
					}
				}
			}
		}
		out.println(ans);
	}


	class UnionFind{
		int[] tree;
		boolean[] multi;
		public UnionFind(int n){
			tree = new int[n];
			multi = new boolean[n];
			for(int i = 0; i < n; i++){
				tree[i] = -1;
			}
		}

		public int root(int x){
			if(tree[x] < 0) return x;
			else return tree[x] = root(tree[x]);
		}

		public boolean find(int x, int y){
			return root(x) == root(y);
		}

		public int union(int x, int y){
			x = root(x);
			y = root(y);
			if(x != y){
				if(tree[x] < tree[y]){
					tree[y] += tree[x];
					tree[x] = y;
					multi[y] = multi[x] | multi[y];
					return -tree[y];
				}else{
					tree[x] += tree[y];
					tree[y] = x;
					multi[x] = multi[x] | multi[y];
					return -tree[x];
				}
			}else{
				multi[x] = true;
			}
			return -tree[x];
		}

		public int size(int x){
			return -tree[root(x)];
		}
		public boolean isMulti(int x){
			return multi[root(x)];
		}
	}


