public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        graph = buildGraph(in, n, m);
        color = new int[n];

        long single = 0;
        long biparate = 0;
        long other = 0;

        for (int i = 0; i < n ; i++) {
            if (color[i] != 0) {
                continue;
            }
            int type = findType(i);
            if (type == 1) {
                single++;
            } else if (type == 2) {
                biparate++;
            } else {
                other++;
            }
        }

        long ans = single * single + 2 * single * (n - single) + other * other + 2 * other * biparate + 2 * biparate * biparate;
        out.println(ans);
        out.flush();
    }

    static int findType(int now) {
        cnt = 0;
        valid = true;
        dfs(now, -1, 1);

        if (cnt == 1) {
            return 1;
        } else if (valid) {
            return 2;
        }
        return 3;
    }

    static int cnt;
    static boolean valid;

    static void dfs(int now, int par, int col) {
        if (color[now] != 0) {
            valid &= color[now] == col;
            return;
        }
        cnt++;
        color[now] = col;
        for (int to : graph[now]) {
            if (to == par) {
                continue;
            }
            dfs(to, now, -col);
        }
    }

    static int[][] graph;

    static int[] color;

    static int[][] buildGraph(InputReader in, int n, int m) {
        int[][] edges = new int[m][];
        int[][] graph = new int[n][];
        int[] deg = new int[n];
        for (int i = 0 ; i < m ; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            deg[a]++;
            deg[b]++;
            edges[i] = new int[]{a, b};
        }
        for (int i = 0 ; i < n ; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0 ; i < m ; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }
        return graph;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

