        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        UnionFindTree t = new UnionFindTree(n);
        IntArrayList[] g = new IntArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new IntArrayList();
        }
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            t.unite(u, v);
            g[u].add(v);
            g[v].add(u);
        }
        int[] col = new int[n];
        IntDeque dq = new IntDeque(n);
        long x = 0, y = 0, z = 0;
        F:for (int i = 0; i < n; i++) {
            if (!t.isRoot(i)) continue;
            if (t.size(i) == 1) {
                z++;
                continue;
            }
            dq.addLast(i);
            col[i] = 1;
            while (dq.size() > 0) {
                int u = dq.removeFirst();
                for (var it = g[u].iterator(); it.hasNext();) {
                    int v = it.nextInt();
                    if (col[v] == 0) {
                        col[v] = -col[u];
                        dq.addLast(v);
                    } else if (col[v] == col[u]) {
                        x++;
                        dq.clear();
                        continue F;
                    }
                }
            }
            y++;
        }
        long ans = x * x + 2 * x * y + 2 * y * y + 2* n * z - z * z;
        out.writeln(ans);
    }
}


/**
