public class Main {
  private static void solve() {
    int n = ni();
    int m = ni();
    int[] from = new int[m];
    int[] to = new int[m];
    DJSet ds = new DJSet(n);
    for (int i = 0; i < m; i++) {
      int u = ni() - 1;
      int v = ni() - 1;
      ds.union(u, v);
      from[i] = u;
      to[i] = v;
    }
    int[][] g = packU(n, from, to);

    long ret = 0;
    int[][] buc = ds.toBucket();
    long size = 0;
    boolean[] bi = new boolean[n];

    long bicnt = 0;

    int[] eo = new int[n];
    for (int i = 0; i < n; i++) {
      if (buc[i] != null && buc[i].length > 1) {
        size++;
        bi[i] = dfs(i, g, eo, true);
        if (bi[i]) {
          bicnt++;
        }
      }
    }

    long notbicnt = size - bicnt;

    for (int i = 0; i < n; i++) {
      if (buc[i] == null)
        continue;

      long x = buc[i].length;
      if (x == 1) {
        ret += n * 2 - 1;
      } else if (bi[i]) {
        ret += 2;

        ret += 2 * (bicnt - 1);
        ret += notbicnt;
      } else {
        ret += 1;

        ret += 2 * bicnt;
        ret += (notbicnt - 1);
      }
    }


    System.out.println(ret);
  }

  static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
      p[f]++;
    for (int t : to)
      p[t]++;
    for (int i = 0; i < n; i++)
      g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
      g[from[i]][--p[from[i]]] = to[i];
      g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

  private static boolean dfs(int now, int[][] g, int[] eo, boolean first) {
    if (first && eo[now] == 0) {
      eo[now] = 1;
    }

    for (int nex : g[now]) {
      if (eo[nex] != 0) {
        if (eo[nex] == eo[now]) {
          return false;
        }
      } else {
        eo[nex] = -eo[now];
        if (!dfs(nex, g, eo, false)) {
          return false;
        }
      }
    }
    return true;
  }


  public static class DJSet {
    public int[] upper;

    public DJSet(int n) {
      upper = new int[n];
      Arrays.fill(upper, -1);
    }

    public int root(int x) {
      return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
    }

    public boolean equiv(int x, int y) {
      return root(x) == root(y);
    }

    public boolean union(int x, int y) {
      x = root(x);
      y = root(y);
      if (x != y) {
        if (upper[y] < upper[x]) {
          int d = x;
          x = y;
          y = d;
        }
        upper[x] += upper[y];
        upper[y] = x;
      }
      return x == y;
    }

    public int[][] toBucket() {
      int n = upper.length;
      int[][] ret = new int[n][];
      int[] rp = new int[n];
      for (int i = 0; i < n; i++) {
        if (upper[i] < 0)
          ret[i] = new int[-upper[i]];
      }
      for (int i = 0; i < n; i++) {
        int r = root(i);
        ret[r][rp[r]++] = i;
      }
      return ret;
    }
  }

