class Solver
{
    public Scanner sc;
    public void Solve()
    {
        int N, M;
        sc.Make(out N, out M);
        var g = Create(N, () => new List<int>());
        var uf = new UnionFind(N);
        for (var i = 0; i < M; i++)
        {
            int a, b;
            sc.Make(out a, out b);
            a--; b--;
            uf.Union(a, b);
            g[a].Add(b);
            g[b].Add(a);
        }
        long now = N;
        var col = new int[N];
        var cn = 0;var use = new bool[N];
        int one = 0, bi = 0, nb = 0;
        void dfs(int i,int p,ref bool bip)
        {
            use[i] = true;cn++;
            foreach (var e in g[i])
            {
                if (col[e] != 0)
                {
                    bip &= (col[i] ^ col[e]) == 3;
                    continue;
                }
                col[e] = col[i] ^ 3;
                dfs(e, i, ref bip);
            }
        }
        var res = 0L;var C = new int[N];var B = new bool[N];
        for (int i = 0; i < N; i++)
        {
            if (use[i]) continue;
            bool bip = true;
            col[i] = 1;
            dfs(i, -1, ref bip);
            C[uf[i]] = cn;
            B[uf[i]] = bip;
            res++;
            res += ToInt32(bip && cn > 1);
            if (cn == 1) one++;
            else if (bip) bi++;
            else nb++;
            cn = 0;
        }
        use = new bool[N];
        for (int i = 0; i < N; i++)
        {
            if (use[uf[i]]) continue;
            now -= C[uf[i]];
            use[uf[i]] = true;
            if (C[uf[i]] == 1)
            {
                one--;
                res += now * 2;

            }else if (B[uf[i]])
            {
                bi--;
                res += 2L * one * C[uf[i]] + 4L * bi + 2L * nb;
            }
            else
            {
                nb--;
                res += 2L * one * C[uf[i]] + 2L * (bi + nb);
            }
        }
        use = new bool[N];
        Console.WriteLine(res);
    }
}

public class UnionFind
{
    public int GroupCount { get; private set; }
    protected int[] data;
    public virtual int this[int i] => Find(i);
    public UnionFind(int size)
    {
        data = Create(size, () => -1);
        GroupCount = size;
    }
    protected int Find(int i) => data[i] < 0 ? i : (data[i] = Find(data[i]));
    public int Size(int i) => -data[Find(i)];
    public virtual bool Union(int u, int v)
    {
        u = Find(u); v = Find(v);
        if (u == v) return false;
        if (data[u] > data[v]) swap(ref u, ref v);
        GroupCount--;
        data[u] += data[v];
        data[v] = u;
        return true;
    }
}
