using System;
using System.Collections.Generic;
using CompLib.Util;

public class Program
{
    private int N;
    private int M;
    private List<int>[] E;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        E = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            E[i] = new List<int>();
        }

        for (int i = 0; i < M; i++)
        {
            int u = sc.NextInt() - 1;
            int v = sc.NextInt() - 1;
            E[u].Add(v);
            E[v].Add(u);
        }

        // 自己辺が無い
        // (a,b)-(a,b'), (a,b)-(a',b)は無い
        // 
        // 辺の個数 2M^2

        // 連結グラフ A,Bがある
        // Cを同じルールで構成するとき、連結成分の個数

        // Aにおいてa-a' Bに b-b'に長さ一致パスがある
        // Cに(a,b)-(a'b')のパスがある

        // 遠回りすると長さ2増やせるのでパリティが一致してれば良い

        // A,B 
        // 片方の頂点1つ辺0個
        // Cに辺作れない 連結成分A,Bの頂点の積

        // 片方が二部グラフじゃない
        // Bが二部グラフじゃないとする
        // Bの奇数長サイクル
        // a'-b'
        // a'->奇数長サイクル->b' 
        // a'-b'のパスは偶奇両方できる
        // 連結成分1個

        // 両方二部グラフ
        // Aのa-b,Bのa'-b'の偶奇が一致してる頂点で連結成分作れる
        // 連結成分2個


        // 頂点数1個連結成分
        long g1 = 0;
        // 二部グラフ連結成分
        long g2 = 0;
        // それ以外連結成分
        long g3 = 0;

        var q = new Queue<int>();
        int[] parity = new int[N];
        for (int i = 0; i < N; i++)
        {
            if (parity[i] != 0) continue;
            parity[i] = 1;
            if (E[i].Count == 0)
            {
                g1++;
                continue;
            }

            // 二部グラフか? 
            bool f2 = true;
            q.Enqueue(i);
            while (q.Count > 0)
            {
                var d = q.Dequeue();
                foreach (int to in E[d])
                {
                    if (parity[to] == 0)
                    {
                        parity[to] = -parity[d];
                        q.Enqueue(to);
                    }
                    else
                    {
                        f2 &= parity[to] == -parity[d];
                    }
                }
            }

            if (f2) g2++;
            else g3++;
        }

        long ans = 0;
        // g1
        ans += g1 * N + (N - g1) * g1;
        // g2 
        ans += g2 * g2 * 2;
        // g3 とg2,g3
        ans += g3 * (g2 + g3) + g2 * g3;

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

