            if (a != b)
            {
                if (size[a] > size[b])
                {
                    parent[b] = a;
                    size[a] += size[b];
                    hasCycle[a] |= hasCycle[b];
                }
                else
                {
                    parent[a] = b;
                    size[b] += size[a];
                    hasCycle[b] |= hasCycle[a];
                }
            }
        }
    }

    public void Solve()
    {
        int n = ReadInt();

        var dsu = new Dsu(n);
        for (int m = ReadInt(); m > 0; m--)
        {
            int u = ReadInt() - 1;
            int v = ReadInt() - 1;
            if (dsu.FindSet(u) != dsu.FindSet(v))
                dsu.UnionSets(u, v);
            else
                dsu.hasCycle[dsu.FindSet(u)] = true;
        }

        int os = 0, oc = 0, es = 0, ec = 0, c1 = 0;
        for (int i = 0; i < n; i++)
            if (dsu.FindSet(i) == i)
            {
                if (dsu.size[i] == 1)
                    c1++;
                else if (dsu.hasCycle[i])
                {
                    es += dsu.size[i];
                    ec++;
                }
                else
                {
                    os += dsu.size[i];
                    oc++;
                }
            }

        Write(2L * n * c1 - 1L * c1 * c1 + 2L * oc * oc + 2L * oc * ec + 1L * ec * ec);
    }

