public class Solver
{
    class Dsu
    {
        public int[] parent, size;
        public bool[] hasCycle;

        public Dsu(int n)
        {
            parent = Enumerable.Range(0, n).ToArray();
            size = Enumerable.Repeat(1, n).ToArray();
            hasCycle = new bool[n];
        }

        public int FindSet(int v)
        {
            if (v == parent[v])
                return v;
            return parent[v] = FindSet(parent[v]);
        }

        public void UnionSets(int a, int b)
        {
            a = FindSet(a);
            b = FindSet(b);
            if (a != b)
            {
                if (size[a] > size[b])
                {
                    parent[b] = a;
                    size[a] += size[b];
                    hasCycle[a] |= hasCycle[b];
                }
                else
                {
                    parent[a] = b;
                    size[b] += size[a];
                    hasCycle[b] |= hasCycle[a];
                }
            }
        }
    }

    public void Solve()
    {
        int n = ReadInt();

        var dsu = new Dsu(n);
        for (int m = ReadInt(); m > 0; m--)
        {
            int u = ReadInt() - 1;
            int v = ReadInt() - 1;
            if (dsu.FindSet(u) != dsu.FindSet(v))
                dsu.UnionSets(u, v);
            else
                dsu.hasCycle[dsu.FindSet(u)] = true;
        }

        int os = 0, oc = 0, es = 0, ec = 0;
        for (int i = 0; i < n; i++)
            if (dsu.FindSet(i) == i && dsu.size[i] > 1)
            {
                if (dsu.hasCycle[i])
                {
                    es += dsu.size[i];
                    ec++;
                }
                else
                {
                    os += dsu.size[i];
                    oc++;
                }
            }

        Write(1L * n * n - 1L * os * os + 2L * oc * oc - 1L * es * es + 1L * ec * ec - 2L * os * es + 2L * oc * ec);
    }

