namespace AtCoder.AGC011
{
    static class SquaredGrapth
    {
        static public void Main()
        {
            /*
            5 4
            1 2
            2 3
            3 1
            4 5

            */
            var nm = ReadLine().Trim().Split(' ').Select(i => int.Parse(i)).ToArray();
            var n = nm[0]; var m = nm[1];
            var nodes = new Node[n];
            for (var i = 0; i < nodes.Length; ++i)
                nodes[i] = new Node(i);
            for (int[] edge; m > 0; --m)
            {
                edge = ReadLine().Trim().Split(' ').Select(i => int.Parse(i) - 1).ToArray();
                nodes[edge[0]].Join(nodes[edge[1]]);
            }
            int single = 0; int even = 0; int odd = 0;
            UnionFindTree calcurated = new UnionFindTree();
            foreach (var node in nodes)
            {
                if (!node.ConnectionID.IsSameUnion(calcurated)) {
                    if (node.IsSingleNode()) ++single;
                    else if (node.HasOddHeiro()) ++odd;
                    else ++even;
                    node.ConnectionID.Join(calcurated);
                }
            }
            var SingleConnectedGraph = 2 * single * n - single * single;
            var OddConnectedGraph = odd * odd + 2 * even * odd;
            var EvenConnectedGraph = 2 * even * even;
            //WriteLine(SingleConnectedGraph);
            //WriteLine(OddConnectedGraph);
            //WriteLine(EvenConnectedGraph);
            WriteLine(SingleConnectedGraph + OddConnectedGraph + EvenConnectedGraph);
        }
        static bool IsSingleNode(this Node node)
        {
            return node.Edges.Count == 0;
        }
        static bool HasOddHeiro(this Node node)
        {
            var rank = new Dictionary<int, int>();
            return SubHasOddHeiro(node, 0, rank);
        }
        static bool SubHasOddHeiro(Node node, int depth, Dictionary<int, int> rank)
        {
            if (rank.ContainsKey(node.NodeID))
                if ((depth - rank[node.NodeID]) % 2 == 1) return true;
                else return false;
            rank[node.NodeID] = depth;
            foreach (var n in node.Edges)
                if (SubHasOddHeiro(n, depth + 1, rank)) return true;
            rank.Remove(node.NodeID);
            return false;
        }
    }
    class Node
    {
        public int NodeID;
        public UnionFindTree ConnectionID = new UnionFindTree();
        public LinkedList<Node> Edges =new LinkedList<Node>();
        public Node(int id) { NodeID = id; }
        public void Join(Node other)
        {
            Edges.AddFirst(other);
            other.Edges.AddFirst(this);
            ConnectionID.Join(other.ConnectionID);
        }
    }

    class UnionFindTree
    {
        static int i = 0;
        int ID = ++i;
        UnionFindTree parent;
        private UnionFindTree Top
        {
            get
            {
                return (parent = parent?.Top) ?? this;
            }
            set
            {
                if (Top != value.Top) Top.parent = value.Top;
            }
        }
        public void Join(UnionFindTree other)
        {
            Top = other.Top; 
        }
        public bool IsSameUnion(UnionFindTree other)
        {
            return Top == other.Top;
        }
    }
}

