  if (*R)[u] == u { return u }
  (*R)[u] = Find(R, (*R)[u])
  return (*R)[u]
}
func Union(R *[]int, u, v int) {
  ru, rv := Find(R, u), Find(R, v)
  if ru < rv {
    (*R)[rv] = ru
  } else if rv < ru {
    (*R)[ru] = rv
  }
}

func Bipartite(G [][]int, u int) bool {
  N := len(G)
  D := make([]int, N)
  for i := range D {
    D[i] = -1
  }
  D[u] = 0
  Q := make([]int, 0)
  Q = append(Q, u)
  for 0 < len(Q) {
    q := Q[0]
    Q = Q[1:]
    for _, adj := range G[q] {
      if D[adj] < 0 {
        D[adj] = (D[q] + 1) % 2
        Q = append(Q, adj)
      } else if D[q] == D[adj] {
        return false
      }
    }
  }
  return true
}

