  for i := range R {
    R[i] = i
  }
  var a, b int
  for i := 0; i < M; i++ {
    NextInt(&a, &b)
    a, b = a - 1, b - 1
    G[a] = append(G[a], b)
    G[b] = append(G[b], a)
    Union(&R, a, b)
  }
  U := make([]int, N)
  for i := range R {
    U[Find(&R, i)]++
  }
  C := make([]int, 3)
  for i, u := range U {
    if u == 0 { continue }
    if u == 1 {
      C[0]++
    } else if Bipartite(G, i) {
      C[1]++
    } else {
      C[2]++
    }
  }
  Write((2 * N - C[0]) * C[0] + 2 * (C[1] + C[2]) * C[1] + C[2] * C[2])
}

func main() {
  Solve()
  Output()
}

