	for (int i = 1; i <= m; i++){
		scanf("%d %d",&u,&v);
		G[u].push_back(v);
		G[v].push_back(u);
	}
	memset(used, 0, sizeof(used));
	memset(rec, 0, sizeof(rec));
	cnt1 = cnt2 = cnt3 = 0;
	for (int i = 1; i <= n; i++){
		if (!used[i]) bfs(i);
	}
	ans = 2LL * cnt1 * n - 1LL * cnt1 * cnt1 + 2LL * cnt3 * cnt2 + 1LL * cnt3 * cnt3 + 2LL * cnt2 * cnt2;
	printf("%lld\n", ans);
	return 0;
}

