fn exec() {
    let mut sc = Scanner::new();
    let (n, m): (usize, usize) = (sc.ne(), sc.ne());
    let mut uf = UnionFind::new(n);
    let mut edge = Vec::new();
    for _ in 0..m {
        let u = sc.ne::<usize>() - 1;
        let v = sc.ne::<usize>() - 1;
        edge.push((u, v));
        uf.unite(u, v);
    }
    let mut cnt = vec![0; n];
    for &(u, _) in &edge {
        cnt[uf.root(u)] += 1;
    }
    let (mut ans1, mut ans2, mut ans3) = (0, 0, 0);
    for i in 0..n {
        if uf.root(i) != i {
            continue;
        }
        if uf.size(i) == 1 {
            ans3 += (n * 2) - 1;
            continue;
        }
        if cnt[uf.root(i)] >= uf.size(i) {
            ans2 += 1;
        } else {
            ans1 += 1;
        }
    }
    let mut ans = ans3;
    for i in 0..n {
        if uf.root(i) != i || uf.size(i) == 1 {
            continue;
        }
        if cnt[uf.root(i)] >= uf.size(i) {
            ans += ans1 + ans2;
        } else {
            ans += ans1 * 2 + ans2;
        }
    }
    println!("{}", ans);
}

