pub struct GraphRec {
    pub n: usize,
    pub visited: Vec<bool>,
    pub cost: Vec<usize>,
    pub b: bool,
    pub cnt: usize,
}
impl GraphRec {
    pub fn new(n: usize) -> Self {
        Self {
            n,
            visited: vec![false; n],
            cost: vec![0; n],
            b: true,
            cnt: 0,
        }
    }
    pub fn dfs(&mut self, u: usize, graph: &Graph) {
        let d = self.cost[u];
        self.visited[u] = true;
        self.cnt += 1;
        for a in graph.adjacency(u) {
            if !self.visited[a.to] {
                self.cost[a.to] = (d + 1) % 2;
                self.dfs(a.to, graph);
            } else if (self.cost[u] + self.cost[a.to]) % 2 == 0 {
                self.b = false;
            }
        }
    }
}
