use std::collections::VecDeque;
use std::io::*;
use std::str::FromStr;

fn main() {
    let n: usize = read();
    let m: usize = read();
    let mut graph: Vec<Vec<usize>> = vec![vec![]; n];
    for _ in 0..m {
        let (a, b) = (read::<usize>() - 1, read::<usize>() - 1);
        graph[a].push(b);
        graph[b].push(a);
    }
    let mut used = vec![0; n];
    let mut zero = 0;
    let mut nibu = 0;
    let mut not_nibu = 0;
    for i in 0..n {
        if used[i] == 0 {
            if graph[i].len() == 0 {
                zero += 1;
                continue;
            }
            let mut que: VecDeque<usize> = VecDeque::new();
            que.push_back(i);
            let mut nibu_check = true;
            used[i] = 1;
            while !que.is_empty() {
                let q = que.pop_front().unwrap();
                for j in &graph[q] {
                    if used[*j] == 0 {
                        used[*j] = if used[q] == 1 { 2 } else { 1 };
                        que.push_back(*j);
                    }
                    if used[*j] == used[q] {
                        nibu_check = false;
                        break;
                    }
                }
            }
            if nibu_check {
                nibu += 1;
            } else {
                not_nibu += 1;
            }
        }
    }
    println!(
        "{}",
        zero * zero
            + zero * (n - zero) * 2
            + nibu * nibu * 2
            + not_nibu * nibu * 2
            + not_nibu * not_nibu
    );
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

