#[derive(Debug, Clone)]
struct UnionFindTree {
    parent: Vec<isize>,
    size: Vec<usize>,
    height: Vec<u64>,
}

impl UnionFindTree {
    fn new(n: usize) -> UnionFindTree {
        UnionFindTree {
            parent: vec![-1; n],
            size: vec![1usize; n],
            height: vec![0u64; n],
        }
    }

    fn find(&mut self, index: usize) -> usize {
        if self.parent[index] == -1 {
            return index;
        }
        let idx = self.parent[index] as usize;
        let ret = self.find(idx);
        self.parent[index] = ret as isize;
        ret
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }

    fn get_size(&mut self, x: usize) -> usize {
        let idx = self.find(x);
        self.size[idx]
    }

    fn unite(&mut self, index0: usize, index1: usize) -> bool {
        let a = self.find(index0);
        let b = self.find(index1);
        if a == b {
            false
        } else {
            if self.height[a] > self.height[b] {
                self.parent[b] = a as isize;
                self.size[a] += self.size[b];
            } else if self.height[a] < self.height[b] {
                self.parent[a] = b as isize;
                self.size[b] += self.size[a];
            } else {
                self.parent[b] = a as isize;
                self.size[a] += self.size[b];
                self.height[a] += 1;
            }
            true
        }
    }
}

struct AdjacentMatrix {
    mat: Vec<Vec<usize>>,
}

impl AdjacentMatrix {
    pub fn new(n: usize) -> AdjacentMatrix {
        AdjacentMatrix {
            mat: vec![vec![0; n]; n],
        }
    }

    pub fn connect(&mut self, x: usize, y: usize) {
        self.mat[x][y] = 1;
        self.mat[y][x] = 1;
    }
}

struct Solver {
    adj_mat: AdjacentMatrix,
    colors: Vec<i32>, // 0 uncolored, 1 or -1
}

impl Solver {
    fn new(n: usize) -> Solver {
        Solver {
            adj_mat: AdjacentMatrix::new(n),
            colors: vec![0; n],
        }
    }
    fn solve(&mut self, idx: usize, color: i32) -> bool {
        if self.colors[idx] != 0 {
            return self.colors[idx] == color;
        }
        self.colors[idx] = color;
        for i in 0..self.adj_mat.mat[idx].len() {
            if self.adj_mat.mat[idx][i] == 0 {
                continue;
            }
            if self.colors[i] == 0 {
                let result = self.solve(i, color * -1);
                if !result {
                    return false;
                }
            } else if self.colors[i] == color {
                return false;
            }
        }
        true
    }
}

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 0..m {
        let v = sc.read::<usize>() - 1;
        let u = sc.read::<usize>() - 1;

        graph[u].push(v);
        graph[v].push(u);
    }

    let mut bipartite: usize = 0;
    let mut single: usize = 0;
    let mut others: usize = 0;
    let mut color = vec![0; n];
    for i in 0..n {
        if color[i] == 0 {
            color[i] = 1;
            if graph[i].is_empty() {
                single += 1;
            } else if color_dfs(i, &graph, &mut color) {
                bipartite += 1;
            } else {
                others += 1;
            }
        }
    }

    let ans1 = single * n * 2 - single * single;
    let ans2 = others * (others + bipartite) * 2 - others * others;
    let ans3 = bipartite * bipartite * 2;
    println!("{}", ans1 + ans2 + ans3);
}

fn color_dfs(v: usize, graph: &[Vec<usize>], color: &mut [usize]) -> bool {
    let mut ok = true;
    for &next in graph[v].iter() {
        if color[next] == 0 {
            color[next] = if color[v] == 1 { 2 } else { 1 };
            ok = ok && color_dfs(next, graph, color);
        } else if color[next] == color[v] {
            ok = false;
        }
    }
    ok
}

