fn run() {
    input! {
        n: usize,
        m: usize,
        e: [(usize1, usize1); m],
    }
    let mut g = vec![vec![]; n];
    for (a, b) in e {
        g[a].push(b);
        g[b].push(a);
    }
    let mut x = 0;
    let mut y = 0;
    let mut z = 0;
    let mut used = vec![false; n];
    let mut depth = vec![0; n];
    for r in 0..n {
        if used[r] {
            continue;
        }
        used[r] = true;
        if g[r].is_empty() {
            z += 1;
            continue;
        }
        let mut q = vec![];
        let mut stack = vec![r];
        while let Some(v) = stack.pop() {
            q.push(v);
            for &u in &g[v] {
                if used[u] {
                    continue;
                }
                used[u] = true;
                depth[u] = depth[v] ^ 1;
                stack.push(u);
            }
        }
        let mut cond = true;
        for &v in &q {
            for &u in &g[v] {
                if depth[u] == depth[v] {
                    cond = false;
                }
            }
        }
        if cond {
            x += 1;
        } else {
            y += 1;
        }
    }
    let mut ans = 0;
    ans += z * z;
    ans += 2 * (n - z) * z;
    ans += x * x * 2;
    ans += y * y;
    ans += 2 * x * y;
    println!("{}", ans);
}

fn main() {
    run();
}

