fn check(v: usize, c: bool, edges: &[Vec<usize>], col: &mut [bool],
         vis: &mut [bool], conn: &mut Vec<usize>) -> bool {
    if vis[v] {
        return c == col[v];
    }
    vis[v] = true;
    col[v] = c;
    conn.push(v);
    let mut bip = true;
    for &w in edges[v].iter() {
        bip &= check(w, !c, edges, col, vis, conn);
    }
    bip
}


fn bipartite(edges: &[Vec<usize>]) -> (usize, usize, usize) {
    let n = edges.len();
    let mut col = vec![false; n];
    let mut vis = vec![false; n];
    let mut bip = 0;
    let mut odd = 0;
    let mut single = 0;
    for i in 0 .. n {
        if vis[i] { continue; }
        let mut conn = Vec::new();
        let is_b = check(i, false, edges, &mut col, &mut vis, &mut conn);
        if !is_b || conn.len() == 1 {
            if conn.len() == 1 {
                single += 1;
            } else {
                odd += 1;
            }
        } else {
            bip += 1;
        }
    }
    (bip, odd, single)
}

fn solve() {
    let n = get();
    let m = get();
    let mut edges = vec![Vec::new(); n];
    for _ in 0 .. m {
        let u = get::<usize>() - 1;
        let v = get::<usize>() - 1;
        edges[u].push(v);
        edges[v].push(u);
    }
    let (bip, odd, single) = bipartite(&edges);
    let bip = bip as i64;
    let odd = odd as i64;
    let single = single as i64;
    let n = n as i64;
    println!("{}", 2 * bip * (bip + odd) + odd * odd
             + n * n - (n - single) * (n - single));
}

