    for i in 0..n {
        if color[i] == 0 {
            let mut count = 0;
            color[i] = 1;
            let is_bipartite = coloring(&graph, &mut color, i, &mut count);
            pairs.push((count, is_bipartite));
        }
    }

    let mut num_single = 0;
    let mut num_bipartite = 0;
    for &(count, is_bipartite) in pairs.iter() {
        if count == 1 {
            num_single += 1;
        } else if is_bipartite {
            num_bipartite += 1;
        }
    }
