fn is_bipartite(
    v: usize,
    c: bool,
    adj: &[Vec<usize>],
    colors: &mut [Option<bool>]
) -> bool {
    match colors[v].clone() {
        None => {
            colors[v] = Some(c);
            adj[v].iter().all(|&next| is_bipartite(next, !c, adj, colors))
        },
        Some(prev_c) => c == prev_c
    }
}

