fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let m: usize = sc.read();
    let mut graph = vec![vec![]; n];
    for _ in 0..m {
        let a = sc.read::<usize>() - 1;
        let b = sc.read::<usize>() - 1;
        graph[a].push(b);
        graph[b].push(a);
    }

    let mut color = vec![0; n];
    let mut single = 0;
    let mut bipartite = 0;
    let mut other = 0;
    for i in 0..n {
        if color[i] == 0 {
            color[i] = 1;
            let is_bipartite = dfs(i, &graph, &mut color);
            let is_single = graph[i].len() == 1;
            if is_single {
                single += 1;
            } else if is_bipartite {
                bipartite += 1;
            } else {
                other += 1;
            }
        }
    }

    let mut ans = single * n * 2 - single * single;
    ans += (bipartite + other) * other * 2 - other * other;
    ans += bipartite * bipartite * 2;
    println!("{}", ans);
}

fn dfs(v: usize, graph: &Vec<Vec<usize>>, color: &mut Vec<u8>) -> bool {
    let mut ok = true;
    for &next in graph[v].iter() {
        if color[next] == 0 {
            color[next] = if color[v] == 1 { 2 } else { 1 };
            ok &= dfs(next, graph, color);
        } else {
            ok &= color[next] != color[v];
        }
    }
    ok
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

